INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The foetus is most likely to be ''damaged by ingestion of teratogenic substances during:-', 'Third trimester.', 'Second trimester', 'First trimester.', 'Risk is equal throughout pregnancy.', 'C', 'Per Myles embryology, the first trimester (organogenesis, especially weeks 3-8) is the period of greatest vulnerability to teratogens, when ingested teratogenic substances most often cause structural malformations. Later trimesters carry mainly functional/growth effects, so risk is not equal throughout pregnancy.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Perineal tear extending beyondthe fourchetteis to which degree.', '1st degree perineal tear.', '2nd degree perineal tear.', '3rd degree perineal tear.', '4th degree perineal tear.', 'A', 'Per Myles, a first-degree perineal tear involves only the fourchette, perineal skin and vaginal mucosa, i.e. it extends just beyond the fourchette without muscle involvement. A second-degree tear additionally involves the perineal muscles, third-degree the anal sphincter, and fourth-degree the rectal mucosa.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Second degree perineal tear involves;-v', 'The fourchette and the anal sphincter', 'Bulbo cavernosus and pubococygeous muscles only', 'Damage to the anal sphincter and rectal mucosa', 'Fourchette and superficial perineal muscles', 'D', 'Per Myles, a second-degree perineal tear involves the fourchette, vaginal mucosa and the superficial/deep perineal muscles but spares the anal sphincter. Anal sphincter involvement denotes third-degree and rectal mucosa involvement fourth-degree, so options citing the anal sphincter are incorrect.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The temporary structure in foetal circulation that connects the right atrium to the left atrium is the', 'Ductus arteriosus', 'Ductus venosus', 'Foramen ovale', 'Hypogastric arteries', 'C', 'Per Myles fetal circulation, the foramen ovale is the opening in the interatrial septum that shunts oxygenated blood from the right atrium to the left atrium, bypassing the non-functioning fetal lungs. The ductus arteriosus links the pulmonary artery to the aorta, and the ductus venosus links the umbilical vein to the inferior vena cava.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A pregnant woman with cardiac disease stage III will present with;-', 'No symptoms during ordinary physical activity', 'Symptoms during mild physical activity', 'Symptoms at rest', 'Symptoms during ordinary physical activity', 'B', 'Per the NYHA classification used in Myles, Class/Stage III cardiac disease produces marked limitation with symptoms on less-than-ordinary (mild) physical activity, though the patient is comfortable at rest. No symptoms on ordinary activity is Class I, symptoms on ordinary activity is Class II, and symptoms at rest denote Class IV.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Lactational amenorrhoea method (LAM) is recommended for a woman who;-', 'Breastfeeds on demand, wants protection for one year only, usually resumes menstruation after six months', 'Breastfeeds exclusively, has not resumed menstruation, has a baby more than six months old', 'Breastfeeds exclusively, has history of delayed menstrual resumption, has a baby less than one year', 'Breastfeeds exclusively, has not resumed menstruation, has a baby less than six months old', 'D', 'Per Kenya National Family Planning Guidelines, the lactational amenorrhoea method is effective only when all three criteria are met simultaneously: exclusive/near-exclusive breastfeeding, continued amenorrhoea, and an infant under six months of age. Options citing a baby over six months, one year, or predicting menstrual resumption violate these criteria.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In breech delivery, Lovset manouvre is applied in;-', 'Extended legs', 'Extended arms', 'Stuck head', 'Extended head', 'B', 'Per Myles, the Lovset manoeuvre is used in breech delivery to deliver extended (nuchal) arms by rotating the fetal trunk so each shoulder passes under the symphysis. Extended head is managed by the Mauriceau-Smellie-Veit manoeuvre and extended legs by the Pinard manoeuvre.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Features of dichorionic twins include; -', 'Two amnions, one placenta', 'Two placentae, dizygotic', 'One amnion, one placenta, dizygotic', 'One amnion, two chorions, one placenta', 'B', 'Per Myles, dichorionic twins each have their own chorion and placenta (which may appear fused) with separate amnions, and are usually dizygotic. ''Two placentae, dizygotic'' is the correct descriptor; the options describing a single shared amnion/placenta describe monochorionic/monoamniotic twins.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Late neonatal deaths are deaths occurring;-', 'After 24 hours of birth', 'Up to one year after birth', '14-28 days after birth', '7-28 days after birth', 'D', 'Per WHO/Kenya MOH definitions, early neonatal death occurs in the first 0-7 days and late neonatal death from 7 up to 28 days after birth. Option D (7-28 days) matches the standard definition; ''after 24 hours'', ''up to one year'' and ''14-28 days'' are incorrect.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The approximate time that the blastocyst spends traveling to the uterus for implantation is:-', '2 days', '7 days', '10 days', '14 weeks', 'B', 'Per Myles embryology, after fertilisation the developing zygote/blastocyst travels down the fallopian tube and reaches the uterus for implantation at about day 6-7. Seven days is the closest correct figure; 2 days is too early and 10 days/14 weeks are too late.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The phases of the ovarian cycle are:-', 'Menstrual, follicular and luteal', 'Menstrual, proliferative and secretory', 'Follicular, luteal and Ovulation', 'Secretory, luteal and follicular', 'C', 'Per Myles Textbook for Midwives and standard reproductive physiology, the three phases of the OVARIAN cycle are: (1) Follicular phase — follicle development under FSH from day 1 to ovulation; (2) Ovulatory phase — LH surge triggers release of the mature ovum; (3) Luteal phase — the corpus luteum secretes progesterone after ovulation. Option C (''Follicular, luteal and Ovulation'') is the only option that contains all three correct ovarian phase names, making it the best available answer. Note: the internal order within option C lists the luteal phase before ovulation, which is clinically wrong — the correct sequence is follicular → ovulatory → luteal. However, no other option contains all three correct phase names. Option A adds ''menstrual'', which belongs to the uterine (endometrial) cycle, not the ovarian cycle. Option B (''menstrual, proliferative and secretory'') describes the three phases of the uterine/endometrial cycle, not the ovarian cycle. Option D is a scrambled version of uterine cycle phases. Option C, despite its internal ordering error, is the only option listing the three authentic ovarian cycle phases.', 'BScN', 'Paper I', 'Midwifery', 'Reproductive Physiology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The layer of the inner cell mass from which bones and muscle tissue developis the:-', 'Mesoderm', 'Ectoderm', 'Endoderm', 'Cytotrophoblast', 'A', 'Per Myles embryology, the mesoderm (middle germ layer of the inner cell mass) gives rise to bone, muscle, connective tissue, and the cardiovascular and urogenital systems. Ectoderm forms skin and the nervous system, endoderm forms the gut and visceral linings, and the cytotrophoblast is a trophoblast layer, not a germ layer.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In Cardiac disease in pregnancy', 'Slight limitation to physical activity is class I', '2nd stage of labour should be by assisted vacuum extraction', 'Grade III disease can be managed as an outpatient', 'Ergometrine is important in management of 3rd stage of labour', 'D', 'Among these flawed options, D is the item the examiner intends about third-stage management, but note the clinical caution: in cardiac disease ergometrine/Syntometrine is actually AVOIDED because it causes a sudden rise in venous return and blood pressure that can precipitate cardiac failure (oxytocin is preferred). The other options are clearly false (NYHA Class I has NO limitation, and Grade III disease requires admission, not outpatient care).', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Common causes of third trimester bleeding include the following except:', 'Bloody show', 'Placenta previa', 'Abruptio placenta', 'Threatened abortion.', 'D', 'Per Myles, causes of third-trimester (antepartum) haemorrhage include placenta praevia, abruptio placentae and bloody show (the operative-delivery cervical show). Threatened abortion by definition occurs before 24 weeks (first/second trimester), so it is the exception.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following signs show the presence of multiple pregnancy except:', 'Uterus larger than expected (>4cm) for dates', 'Excessive maternal weight gain that is not explained by oedema or obesity', 'Oligohydramnios', 'Multiplicity of small parts', 'C', 'Per Myles, signs of multiple pregnancy include a uterus large for dates (>4 cm above expected), excessive unexplained weight gain, multiplicity of fetal small parts and polyhydramnios. Oligohydramnios (reduced liquor) is not a feature of multiple pregnancy, so it is the exception.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following are changes that one may experience during menopause except', 'Painful coitus', 'Sex become more enjoyable', 'Reduced libido', 'Urinary retention', 'B', 'Per Myles, menopausal oestrogen decline causes vaginal atrophy with dyspareunia (painful coitus), reduced libido and urinary symptoms. ''Sex becoming more enjoyable'' is not a menopausal change, so it is the exception.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following are factors that cause the floating of the fetal head at term', 'Abruptio placenta', 'Persistent occipital posterior presentation', 'Deflexion of the fetal head', 'Gynaecoid pelvis', 'C', 'Per Myles, a floating (non-engaged) fetal head at term results from deflexion or malposition of the head, placenta praevia, cephalopelvic disproportion, high parity and polyhydramnios. Deflexion of the fetal head is the recognised cause listed; a gynaecoid pelvis actually favours engagement, and abruptio placentae/persistent OP are not primary causes of a floating head as framed here.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The management of cord prolapse is', 'Examination under anesthesia', 'Complete bed rest', 'Knee-chest position while awaiting theatre', 'Caesarean section once the blood has been grouped and cross-matched', 'C', 'Per Myles, management of cord prolapse aims to relieve cord compression: place the mother in knee-chest (or exaggerated Sims/Trendelenburg) position and elevate the presenting part while expediting delivery, usually by emergency Caesarean. Knee-chest positioning while awaiting theatre is the correct immediate measure; simple bed rest or examination under anaesthesia do not address cord compression.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Regarding pregnancy induced hypertension', 'Young primigravidas have the lowest incidences', 'Eclampsia if diagnosed prior to 20 weeks necessitates conservative management', 'Pre-eclampsia /eclampsia is least common in extremes of ages', 'A familial history is a significant finding.', 'D', 'Per Myles, pre-eclampsia/pregnancy-induced hypertension is commoner in young primigravidae and at the extremes of maternal age, and shows a familial/genetic tendency, so a positive family history is a significant finding (D). The other statements are false: young primigravidae have HIGHER (not lowest) incidence, and pre-eclampsia/eclampsia is MORE (not least) common at age extremes.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following anticoagulant is not used in the 1st trimester', 'Warfarin sulphate', 'Heparin', 'Clexane', 'Fondaparinux.', 'A', 'Per Myles and the Kenya EML/BNF, warfarin is teratogenic (warfarin embryopathy) and is avoided in the first trimester, whereas heparin and LMWHs (Clexane/enoxaparin, fondaparinux) do not cross the placenta and are preferred in pregnancy. Warfarin is therefore the anticoagulant not used in the first trimester.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Njau was giving a health talk to a mother who had just delivered her first child. He was supposed to check for correct positioning as the mother breastfed her child. A sign of correct positioning in breastfeeding include', 'Infant''s body straight and whole body facing the mother', 'Mouth wide open', 'More areola above than below', 'Lower lip turned outward', 'A', 'Per Kenya MOH/BFHI breastfeeding guidance, signs of correct POSITIONING are the baby''s head and body held straight and in line, the whole body facing and held close to the mother. The other options (mouth wide open, more areola visible above than below, everted lower lip) are signs of good ATTACHMENT rather than positioning.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Concerning Trichomonas vaginalis, which one of the following is not true?', 'The discharge often has bubbles', 'The spouse often has no symptoms', 'Pruritus is a prominent feature', 'Laboratory diagnosis is usually necessary before treatment', 'D', 'Per Kenya STI syndromic management guidelines, trichomoniasis presents with frothy/bubbly discharge, prominent pruritus, and an often asymptomatic partner, and is treated syndromically (metronidazole) without waiting for laboratory confirmation. Thus ''laboratory diagnosis is usually necessary before treatment'' is the statement that is NOT true.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Most common immunoglobulin secreted by mother in milk and colostrum is:', 'IgA', 'IgG', 'IgE', 'IgD', 'A', 'Per Myles and standard immunology (Abbas), secretory IgA is the predominant immunoglobulin in breast milk and colostrum, coating the neonatal gut mucosa to provide passive local immunity. IgG crosses the placenta but is not the main milk immunoglobulin, and IgE/IgD are present only in trace amounts.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Second degree perineal tear involves;-', 'The fourchette and the anal sphincter', 'Bulbo cavernosus and pubococygeous muscles only', 'Damage to the anal sphincter and rectal mucosa', 'Fourchette and superficial perineal muscles', 'D', 'Per Myles, a second-degree perineal tear involves the fourchette, vaginal mucosa and the superficial perineal muscles but spares the anal sphincter. Involvement of the anal sphincter or rectal mucosa denotes third- or fourth-degree tears, so those options are incorrect.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Toxoplasmosis in a new born is mostly acquired through:-', 'Contact with maternal genito urinary secretions.', 'Nosocomial transfer from the environment at birth.', 'Contaminated water and test feeds given to the newborn.', 'The placenta before birth of the baby.', 'D', 'Per Myles and TORCH/congenital infection principles, congenital toxoplasmosis is acquired transplacentally when the mother''s primary Toxoplasma infection crosses the placenta to the fetus before birth. It is not acquired via genito-urinary secretions, nosocomial contact, or contaminated feeds in the newborn.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The technique in which a midwife inserts his/her hand into the vagina and exerts pressure into the posterior fetal shoulder is:', 'Rubin''s manoeuvre', 'McRoberts manoeuvre', 'Mauriceau-smillie-veit manoeuvre', 'Lovset Manuvre', 'A', 'Per Myles, in shoulder dystocia the Rubin manoeuvre involves inserting a hand vaginally and pressing on the posterior aspect of a fetal shoulder to adduct and rotate it into the oblique diameter. McRoberts is maternal hip hyperflexion (no vaginal hand), and Mauriceau-Smellie-Veit and Lovset are breech (not shoulder-dystocia) manoeuvres.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('After diagnosis of cord prolapse, the priority action for the midwife would be to:', 'Hasten delivery by use of oxytocin infusion', 'Inform the mother to lie in left lateral position', 'Prepare the mother for emergency caesarean section', 'Minimize pressure from the cord', 'D', 'Per Myles, the immediate priority in cord prolapse is to relieve cord compression (elevate the presenting part, knee-chest/Trendelenburg or exaggerated Sims position) to preserve fetal oxygenation while preparing for delivery. Oxytocin is contraindicated as it worsens compression, and left lateral positioning alone or moving straight to theatre are secondary to first minimising cord pressure.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The commonly performed episiotomy is medial lateral because it:', 'Avoids damage to anal sphincter, prevents Bartholin''s gland injury', 'Avoids damage to anal sphincter, is easy to repair', 'Prevents Bartholon''s gland injury, has reduced blood loss', 'Is easy to repair, less painful', 'B', 'Per Myles, the medio-lateral episiotomy is preferred because its angled incision directs away from the anal sphincter/rectum, reducing the risk of extension into a third/fourth-degree tear while remaining repairable. Compared with the midline it actually causes more blood loss and is somewhat harder to repair, so ''avoids anal sphincter damage and is repairable'' (B) is the best-fitting rationale; it is unrelated to Bartholin''s gland injury.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The characteristics of anterior fontanelle include:', 'Diamond shaped, closes at 6 weeks', 'Closes at 18 months, triangular in shape', 'Triangular in shape, closes at 6 weeks', 'Diamond shaped, closes at 18 months', 'D', 'Per Myles Textbook for Midwives, the anterior fontanelle (bregma) is diamond/kite-shaped and closes by about 18 months, making D correct. The posterior fontanelle is the triangular one that closes by around 6 weeks, so options A, B and C (which mislabel shape or closure time) are wrong.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Conditions which predispose to breech presentation include:', 'Preterm labour, oligohydramnious, fibromyomata', 'Placenta praevia, large baby, oligohydramnios', 'Polyhydramnios, hydrocephalus, uterine malformations', 'Uterine abnormalities, large baby, oligohydramnios', 'C', 'Per Myles Textbook for Midwives, breech presentation is predisposed by factors allowing free fetal movement or preventing engagement: polyhydramnios, fetal abnormality such as hydrocephalus, and uterine malformations (option C). Oligohydramnios restricts fetal movement and does not predispose to breech, so options A, B and D are wrong.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The type of breech where the baby presents with the hips flexed and the legs extended is called.', 'Frank breech', 'Complete breech', 'Footling breech', 'Knee presentation', 'A', 'Per Myles Textbook for Midwives, a frank (extended) breech has the hips flexed with the legs extended upward against the trunk, splinting the fetus; it is the commonest breech type, so A is correct. Complete breech has hips and knees flexed (B), footling has a foot presenting (C), and knee presentation has a flexed knee lowermost (D).', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The classical signs of respiratory distress syndrome in a neonate are:', 'Metabolic acidosis, tachycardia, hypoxaemia', 'Cyanosis, respiratory acidosis, atelectasis', 'Nasal flaring, chest indrawing, bradypnoea', 'Tachypnea, expiratory grunting, intercostal and substernal recession.', 'D', 'Per Kenya Basic Paediatric Protocols and Myles Textbook for Midwives, the classic signs of neonatal respiratory distress syndrome are tachypnoea, expiratory grunting, nasal flaring and intercostal/substernal recession (option D). Option C is wrong because the infant is tachypnoeic, not bradypnoeic; options A and B list late/derived findings (acidosis, atelectasis) rather than the classic clinical signs.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The characteristics of a post term infant include:', 'Loose, dry, desquamating skin, small fontanelles, narrow sutures', 'Worried look, firm skull bones, wrinkled skin', 'Abundant hair, overgrown nails, dry loose skin', 'Wide fontanelles, soft skull bones, narrow suture', 'C', 'Per Myles Textbook for Midwives, the post-term (post-mature) infant has abundant scalp hair, long overgrown nails and dry, cracked, desquamating loose skin with little vernix, so C is correct. Fontanelles and sutures are not widened or narrowed as a defining feature, making options A, B and D (which cite altered fontanelles/skull bones) wrong.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The hormone responsible for relaxing the pelvic girdle, softening the cervix and suppressing uterine contractions towards the end of pregnancy is:', 'Oxytocin', 'Progesterone', 'Oestrogen', 'Relaxin', 'D', 'Per Myles Textbook for Midwives, relaxin softens the cervix and ligaments, relaxes the pelvic girdle joints and helps suppress uterine activity in preparation for labour (option D). Oxytocin stimulates contractions (A), progesterone maintains pregnancy but is not the pelvic-relaxing hormone described (B), and oestrogen promotes uterine growth and contractility (C).', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The common age of onset for gonococcal opthalmia neonatorum is:', 'Between 21-28 days after birth', 'Between 0-7 days after birth', 'Between 7-14 days after birth', 'At 28 days of age', 'B', 'Per WHO/Kenya MOH ophthalmia neonatorum guidance, gonococcal ophthalmia neonatorum presents early, within the first week of life (0-7 days), classically on days 2-5, so B is correct. Chlamydial conjunctivitis presents later (about 5-14 days), which excludes options C, A (21-28 days) and D (28 days).', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Choanal atresia should be suspected in a newborn who is:', 'Cyanosed due to prematurity', 'Cyanosed due to depression of respiratory by drugs given to mother during labour', 'Cyanosed at rest and becomes pink when crying', 'Cyanosed when crying and pink at rest', 'C', 'Per Myles and standard paediatric texts, newborns are obligate nasal breathers, so in bilateral choanal atresia the infant is cyanosed at rest but becomes pink when crying because crying opens the mouth and bypasses the blocked nasal passage (option C). Option D reverses this pattern; cyanosis from prematurity (A) or maternal drug depression (B) is not relieved by crying.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The absence of one of the arteries during placental examination is a probable indication that the newborn has:', 'A congenital heart disease', 'Renal agenesis', 'Oesophageal atresia', 'Downs syndrome', 'A', 'Per Myles Textbook for Midwives, a single umbilical artery (absence of one of the two umbilical arteries) is associated with congenital anomalies, classically congenital heart disease and renal defects; of the listed options congenital heart disease (A) is the standard textbook association taught in Kenyan midwifery. Renal agenesis (B) is one possible renal anomaly but the single-artery association is with cardiac and renal defects generally, and oesophageal atresia (C) and Down syndrome (D) are not the classic single-artery associations.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The initial characteristics of rigid cervix in cervical dystocia include:-', 'Thin, tight, unyielding,', 'Thick, tight, oedematous', 'Long, thick, oedematous.', 'Thick, oedematous, unyielding.', 'A', 'Per Myles Textbook for Midwives, in cervical dystocia the rigid cervix is initially thin, tight and unyielding, failing to dilate despite good contractions (option A); oedema and thickening are later developments, so options B, C and D (which include oedema/thickening as initial features) are wrong.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The trophoblastic cells form', 'Fetus and amnion.', 'Placenta and fetus.', 'Chorion and amnion.', 'Placenta and chorion.', 'D', 'Per Myles Textbook for Midwives, the trophoblast (outer cell layer of the blastocyst) develops into the chorion and forms the fetal portion of the placenta (option D). The fetus and amnion arise from the inner cell mass, not the trophoblast, so options A, B and C are wrong.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('During labour, a midwife discourages the woman to lie in supine position to prevent:', 'Maternal hypertension and fetal compromise.', 'Maternal hypotension and fetal compromise.', 'Fetal compromise and maternal oedema.', 'Obstructed labour and maternal hypotension.', 'B', 'Per Myles Textbook for Midwives, the supine position causes aortocaval compression (supine hypotensive syndrome), reducing venous return and cardiac output and producing maternal hypotension with consequent fetal compromise (option B). It causes hypotension, not hypertension (A), and the primary mechanism is not oedema or obstructed labour, excluding C and D.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The reflex elicited when the midwife allows the head of the baby to drop by 45degree is:', 'Stepping.', 'Rooting.', 'Grasping.', 'Moro.', 'D', 'Per Myles and Basic Paediatric Protocols, the Moro (startle) reflex is elicited by allowing the baby''s head to drop back about 45 degrees, producing symmetrical abduction and extension of the arms followed by an embracing adduction (option D). Stepping (A), rooting (B) and grasping (C) are elicited by different stimuli (foot contact, cheek stroking, palm pressure).', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Active management of 3rd stage of labour include:', 'Give oxytocin 10 iu intramuscular, empty the bladder, deliver the placenta through continuous cord traction.', 'Check for signs of placental separation, deliver the placenta through continuous cord traction, give intramuscular oxytocin 10 iu.', 'Give oxytocin 10 iu intramuscular, feel for a contraction, deliver the placenta by continuous cord traction.', 'Give oxytocin 10 iu intramuscular, deliver the placenta by continuous cord traction, massage uterus for a contraction.', 'A', 'Per Kenya MOH/WHO guidelines, active management of the third stage is: give oxytocin 10 IU IM within one minute of birth, ensure the bladder is empty, then deliver the placenta by controlled cord traction with counter-traction, followed by uterine massage; option A gives the uterotonic first and reflects this sequence. Option B wrongly gives oxytocin last, and options C and D omit bladder care or misplace uterine massage.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('During examination of the placenta, blood vessels are observed running through the membranes.This is an indication of:', 'Circumvallate placenta.', 'Velamentous insertion of the cord.', 'Succenturiate placenta.', 'Battledore insertion of the cord.', 'B', 'Per Myles Textbook for Midwives, velamentous insertion of the cord occurs when the umbilical vessels leave the cord and run unprotected through the membranes before reaching the placenta, seen at examination as vessels coursing through the membranes (option B). Circumvallate placenta (A) shows a raised ring, succenturiate lobe (C) has an accessory lobe with vessels connecting two placental masses, and battledore insertion (D) is marginal cord insertion.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Half hourly observation recorded on the partograph during the first stage of labour include:', 'Blood pressure, descent, fetal heart rate.', 'Fetal heart rate, contractions , maternal pulse.', 'Cervical dilatation, maternal pulse rate, blood pressure', 'Temperature, colour of liquor, maternal pulse rate.', 'B', 'Per WHO/Kenya partograph guidelines, fetal heart rate, contractions and maternal pulse are recorded half-hourly during the first stage of labour (option B). Blood pressure and temperature are recorded less frequently (about 4-hourly) and cervical dilatation/descent about 4-hourly, so options A, C and D (which include these less-frequent parameters as half-hourly) are wrong.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nursing interventions for a pregnant woman with nausea and vomiting at 10 weeks of gestation and no signs of dehydration include:', 'Advise her to avoid large volume drinks, raising the head of the bed.', 'Admit to hospital, start intravenous fluid therapy.', 'Advice small carbohydrate meals, give drugs to prevent vomiting.', 'Advice on small carbohydrate meals, avoid spicy meals.', 'D', 'Per Myles and Kenya reproductive health guidelines, mild first-trimester nausea and vomiting without dehydration is managed conservatively with small frequent carbohydrate meals and avoidance of spicy/fatty foods (option D). Hospital admission and IV fluids (B) are reserved for hyperemesis with dehydration, and routine antiemetic drugs (C) are not first-line for mild symptoms; option A omits the dietary carbohydrate advice that is the core intervention.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Discharge from the uterus that occur in puerperium during the first four days is known as:', 'Lochia rubra.', 'Lochia alba.', 'Lochia serosa.', 'Vaginal blood loss.', 'A', 'Per Myles Textbook for Midwives, lochia rubra is the red, blood-stained discharge of the first 3-4 days of the puerperium (option A). It is followed by lochia serosa (pinkish-brown, C) and then lochia alba (white/yellow, B); ''vaginal blood loss'' (D) is a non-specific term, so A is correct.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A strong uterine contraction should last:', 'Below 20 seconds.', 'Between 40 - 60 seconds.', 'Above 60 seconds.', 'Between 20 - 40 seconds.', 'B', 'Per Myles Textbook for Midwives, a strong contraction in established active labour lasts about 40-60 seconds (option B). Contractions below 20 seconds (A) are weak, so B correctly identifies the duration of a strong contraction; options C and D do not represent the typical strong-contraction range.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The sequence of abdominal examination for antenatal mothers is:', 'Inspection, pelvic palpation, fundal palpation, lateral palpation, auscultation.', 'Inspection, pelvic palpation, fundal palpation, pelvic palpation, auscultation.', 'Inspection, pelvic palpation, lateral palpation, fundal palpation, auscultation.', 'Inspection, fundal palpation, lateral palpation, pelvic palpation, auscultation.', 'D', 'Per Myles Textbook for Midwives, the systematic sequence of antenatal abdominal examination is inspection, then fundal palpation, lateral palpation and pelvic palpation, followed by auscultation of the fetal heart (option D). Options A, B and C disorder the palpation steps (e.g. pelvic before fundal), so they are wrong.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The presentation of the fetus is defined as:', 'The relationship between the long axis of the fetus and long axis of the uterus.', 'The relationship of the fetal head and limbs to its trunk.', 'The part of the fetus that lies at the pelvic brim.', 'The name of the part of the presentation which is used when referring to fetal position.', 'C', 'Per Myles Textbook for Midwives, presentation is the part of the fetus that lies at the pelvic brim/lower pole of the uterus (option C). Option A defines lie (relationship of fetal to uterine long axis), option B defines attitude (relationship of head and limbs to trunk), and option D describes the denominator used for position.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Cervical effacement in the first stage of labour refers to:', 'The process of enlargement of the cervical os from a tightly closed aperture to an opening large enough to permit passage of the fetus.', 'The inclusion of the cervical canal into the lower uterine segment.', 'Thickening of the lower uterine segment.', 'Thinning and stretching of the lower uterine segment.', 'B', 'Per Myles Textbook for Midwives, effacement is the taking-up (inclusion) of the cervical canal into the lower uterine segment so the cervix shortens and thins (option B). Option A describes dilatation of the os; options C and D describe lower-segment changes but not the specific definition of effacement.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Mechanical factors involved in physiology of 1st stage of labour include:', 'General fluid pressure, rupture of membranes, formation of fore-waters.', 'General fluid pressure, formation of retraction ring, rupture of membranes.', 'Formation of fore-waters, polarity, contraction and retraction.', 'Rupture of membranes, cervical dilation, cervical effacement.', 'A', 'Per Myles Textbook for Midwives, the mechanical factors in the first stage of labour are the formation of the fore-waters, general fluid pressure and rupture of the membranes (option A). Polarity, contraction and retraction (options B and C) are physiological rather than mechanical factors, and option D lists dilatation/effacement which are outcomes rather than the mechanical factors themselves.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The uterine support that fans out from the sidewalls of the cervix to the side walls of the pelvis is referred to as:', 'Utero sacral ligament.', 'Broad ligament.', 'Round ligament.', 'Transverse cervical ligament.', 'D', 'Per Myles Textbook for Midwives, the transverse cervical (cardinal/Mackenrodt''s) ligaments fan out from the sides of the cervix and upper vagina to the side walls of the pelvis and are the main support of the uterus (option D). The uterosacral (A) runs to the sacrum, the broad ligament (B) is a peritoneal fold, and the round ligaments (C) run to the labia majora.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In mechanism of normal labor which movement occurs when the largest transverse diameter of the fetal head is born:', 'Restitution.', 'Crowning.', 'Descent.', 'Extension.', 'B', 'Per Myles Textbook for Midwives, crowning occurs when the head no longer recedes between contractions and the widest transverse (biparietal) diameter is born, distending the vulva (option B). Restitution (A) is the head realigning with the shoulders, descent (C) is downward movement through the pelvis, and extension (D) is the mechanism by which the head is born under the symphysis.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In physiology of puerperium, autodigestion of dead tissues is referred to as:', 'Ischaemia.', 'Involution.', 'Autolysis.', 'Sub-involution.', 'C', 'Per Myles Textbook for Midwives, autolysis is the self-digestion of muscle fibres and dead tissue by proteolytic enzymes and is a key mechanism of uterine involution in the puerperium (option C). Involution (B) is the overall process of the uterus returning to its non-pregnant state, ischaemia (A) is reduced blood supply, and sub-involution (D) is failure of the uterus to involute.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following features can be elicited on abdominal inspection:', 'Striae gravidarum, linea nigra, lie,', 'Fetal heart rate, presentation, position contractions.', 'Shape, striae gravidarum, linea nigra, surgical scars.', 'Fundal height, lie, presentation, position.', 'C', 'Per Myles Textbook for Midwives, inspection of the pregnant abdomen reveals shape/size, skin changes (striae gravidarum, linea nigra) and surgical scars (option C). Lie, presentation and position are determined by palpation and the fetal heart by auscultation, not inspection, so options A, B and D (which include palpation/auscultation findings) are wrong.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('One of the following include predisposing factors to hydramnious.', 'Oesophageal atresia, choanal atresia, open neural tube defects.', 'Chorioangioma, prolonged pregnancy, rhesus Isoimmunisation.', 'Multiple gestation, chorioangioma, esophageal atresia', 'Choanal atresia, renal agenesis, open neural tube defect.', 'C', 'Per Myles Textbook for Midwives, polyhydramnios is predisposed by conditions impairing fetal swallowing or increasing fluid: multiple gestation, chorioangioma of the placenta, oesophageal atresia and open neural tube defects; option C best groups genuine causes (multiple gestation, chorioangioma, oesophageal atresia). Renal agenesis and choanal atresia (options A and D) cause oligohydramnios, not polyhydramnios, so they are wrong.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A diagnosis of gestational diabetes is made when.', 'Fasting blood sugar is less than 6.1 mmols/litre', 'During a glucose tolerance test, blood sugar at 2 hours is more than 11.1 mmols/litre.', 'During a glucose tolerance test, blood sugar at 2 hours is less than 11.1 mmols/litre', 'Random blood sugar is less than 11 mmols/litre', 'B', 'Per WHO/Kenya diagnostic criteria, a raised 2-hour value on the OGTT indicates hyperglycaemia in pregnancy, and a 2-hour value more than 11.1 mmol/L is diagnostic (option B). A fasting value less than 6.1 (A), a 2-hour value less than 11.1 (C) and a random value less than 11 (D) describe normal or non-diagnostic results, so they are wrong.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The degree of placenta praevia has a substantial portion in the lower uterine segment with its edge at the margin of the internal os.', 'Type 1', 'Type 2', 'Type 3', 'Type 4', 'B', 'Per Myles Textbook for Midwives, in Type 2 (marginal) placenta praevia the placenta occupies a substantial portion of the lower uterine segment with its lower edge reaching the margin of the internal os but not covering it (option B). Type 1 is low-lying not reaching the os (A), Type 3 partially covers the os (C), and Type 4 completely covers the os (D).', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('While attending an antenatal woman at 28 weeksgestation, the midwife finds that she has elevated blood pressure and proteinuria, what is the possiblediagnosis.', 'Pregnancy induced hypertension', 'Eclampsia', 'Gestational hypertension', 'Pre- eclampsia', 'D', 'Per Myles and Kenya MOH guidelines, new-onset hypertension after 20 weeks accompanied by proteinuria is pre-eclampsia (option D). Gestational/pregnancy-induced hypertension (A, C) is raised BP without proteinuria, and eclampsia (B) additionally involves convulsions, so D is correct.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('One of the following factors causes jaundice by interfering with transportation of bilirubin.', 'Reduced albumin binding capacity', 'Hypoglycaemia', 'Reduced gut motility', 'Increased beta glucoronidase enzyme.', 'A', 'Per Myles Textbook for Midwives, unconjugated bilirubin is transported in blood bound to albumin, so reduced albumin binding capacity impairs bilirubin transport and raises free unconjugated bilirubin, increasing jaundice/kernicterus risk (option A). Hypoglycaemia (B), reduced gut motility (C) and increased beta-glucuronidase (D) affect metabolism or enterohepatic reabsorption rather than transport of bilirubin.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following include signs of uterine rupture.', 'Severe abdominal pains, bandl''s ring, palpable fetal parts in the abdomen', 'Strong uterine contractions, altered fetal heart rate, presentation regress.', 'Caesation of contractions, presentation regress, fetal part palpable in the abdomen.', 'Uterine apoplexy, presentation regress maternal collapse.', 'A', 'Per Myles Textbook for Midwives, uterine rupture is signalled by severe abdominal pain, a Bandl''s (pathological retraction) ring, and, once rupture occurs, easily palpable fetal parts in the abdomen with cessation of contractions and maternal collapse; option A best combines these classic signs. Options B, C and D mix incompatible features such as continuing strong contractions or omit key signs, making them less complete/accurate.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A woman develops 2nd degree uterine inversion, what are the possible findings.', 'The body of the uterus is inverted into the internal OS.', 'The fundus of the uterus reaches the external OS.', 'The uterus, cervix and vagina are visible.', 'The uterus inverts within 24 hours of delivery.', 'B', 'Per Myles Textbook for Midwives, in second-degree uterine inversion the fundus passes through the cervix and reaches the external os/vagina but is not yet visible outside the vulva (option B). First degree keeps the fundus within the cavity/at the internal os (A), and complete (third-degree) inversion protrudes outside the vulva (C); option D describes timing, not the degree.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In face presentation, whatare the presenting diameters.', 'Mental vertical and Bi temporal.', 'Mental vertical and Bi parietal', 'Submental bregmatic and Bi parietal', 'Submental bregmatic and Bi temporal', 'D', 'Per Myles Textbook for Midwives, in a fully extended face presentation the presenting diameters are the submentobregmatic (9.5 cm) and the bitemporal (8.2 cm), so option D is correct. The mentovertical is the presenting diameter of a brow presentation, so options A and B are wrong, and option C pairs the correct submentobregmatic with the incorrect biparietal.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following includes management of preterm pre-labour rupture of membranes.', 'If pregnancy is more than 34 weeks give tocolytics.', 'If pregnancy is more than 34 weeks give corticosteroids.', 'If pregnancy is below 32 weeks and there are signs of infection give tocolytics', 'If pregnancy is below 32 weeks give corticosteroids.', 'D', 'Per Kenya MOH/WHO PPROM guidance, antenatal corticosteroids are given before 34 weeks (e.g. below 32 weeks) to promote fetal lung maturity, so option D is correct. Tocolytics are generally avoided in PPROM and are absolutely contraindicated with infection (option C), and corticosteroids are not indicated after 34 weeks (option B); option A wrongly gives tocolytics beyond 34 weeks.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Common factors aggravating cardiac failure in clients who have cardiac disease in pregnancyinclude:', 'Anaemia, hypertension, multiple gestation, malaria.', 'Singleton gestation, excessive rest, smoking ,anaemia.', 'Multiple gestation, assisted vaginal delivery, anaemia, obesity.', 'Obesity, smoking, malposition, emotional upset.', 'A', 'Per Myles Textbook for Midwives, factors aggravating cardiac failure in a pregnant cardiac patient include anaemia, hypertension, multiple gestation and infection such as malaria, all of which increase cardiac workload (option A). Options B, C and D include protective or irrelevant items (excessive rest, singleton gestation, malposition, emotional upset) that are not the recognised aggravating factors.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following include management of a pregnant woman with pyelonephritis .', 'Urine for culture and sensitivity, oral antibiotics, intravenous fluids, antipyretics.', 'Admission to hospital, urine for culture and sensitivity, parenteral antibiotics.', 'Urine for culture and sensitivity, nurse as outpatient, intravenous antibiotics, antipyretics.', 'Plenty of fluids ,oral antibiotics, antipyretics, nurse as outpatient.', 'B', 'Per Kenya MOH and Myles guidelines, acute pyelonephritis in pregnancy requires hospital admission, urine for culture and sensitivity, and parenteral (IV) antibiotics with IV fluids and antipyretics (option B). Outpatient management with oral antibiotics (options A, C, D) is inadequate for the systemic risk of pyelonephritis in pregnancy, and option C contradictorily nurses the woman as an outpatient on IV antibiotics.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A low birth weight baby is one:', 'Born before 37 completed weeks.', 'Whose weight at birth is below the 10th percentile for gestational age.', 'Weight is appropriate for gestational age.', 'Birth weight is below 2500gm regardless of gestation.', 'D', 'Per WHO/Kenya MOH definition, low birth weight (LBW) is any live birth weighing less than 2500 g regardless of gestational age. Option A defines prematurity (before 37 completed weeks), and option B (weight below the 10th percentile for gestational age) defines small-for-gestational-age; option C (appropriate for gestational age) is the opposite concept. Only D captures the pure weight-based LBW definition.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which one of the following is not a predisposing factorto amniotic fluid embolism.', 'Over stimulation of the uterus with oxytocics.', 'Intrauterine fetal death.', 'Spontaneous rupture of membrane', 'Placenta abruption', 'C', 'Per Myles Textbook for Midwives, recognised predisposing factors to amniotic fluid embolism include uterine over-stimulation with oxytocics (A), intrauterine fetal death (B) and placental abruption (D) - all conditions that allow amniotic fluid/debris to enter the maternal circulation. Simple spontaneous rupture of membranes (C) is a normal event and is not itself a recognised predisposing factor, so it is the exception. Note: rupture of membranes must coincide with an open venous route for embolism, which SROM alone does not provide.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In the right occipito posterior position the midwife will elicit.', 'The sinciput is facing left illiopectineal eminence and the occiput facing right sacroiliac joint.', 'The occiput is facing the right sacroiliac joint and sinciput is on left sacroiliac joint', 'Occiput on right sacroiliac joint and the sinciput on right illiopectineal eminence.', 'The occiput is facing the left sacroiliac joint and the sinciput on right illiopectineal eminence.', 'A', 'In the right occipito-posterior (ROP) position the denominator (occiput) points to the right sacroiliac joint while the sinciput lies opposite at the left iliopectineal eminence (Myles Textbook for Midwives). Option A states exactly this. B wrongly places the sinciput at a sacroiliac joint; C wrongly puts both occiput and sinciput on the right; D describes a left-occipito-posterior orientation, not ROP.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In assistance breech delivery, to deliver fetal legs in frank breech,which manoeuvreshould the midwife apply to deliver the head.', 'Loveset', 'Mauriceau smellieveit', 'Popliteal fossa press', 'Burns marshall', 'B', 'The Mauriceau-Smellie-Veit manoeuvre is the standard controlled method of delivering the aftercoming head in breech birth, promoting flexion by finger pressure on the malar/maxilla with shoulder traction (Myles Textbook for Midwives). Loveset (A) delivers extended arms, popliteal fossa pressure (C) delivers extended legs in frank breech, and Burns-Marshall (D) is an alternative head-delivery method by suprapubic sweeping/traction - but MSV is the manoeuvre named for head delivery here.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('One of the following includes management of tuberculosis and the newborn.', 'If the woman has been on treatment for more than 2 months to her EDD and is smear negative, give baby prophylaxis isoniazid.', 'If the woman has active lung tuberculosis, give baby BCG.', 'If the woman is smear negative and has been on treatment for more than 2 months to her EDD give the baby BCG.', 'If the woman has been on treatment for less than two months to her EDD give the baby BCG.', 'A', 'Per Kenya MOH/WHO TB guidelines, when the mother''s TB is non-infectious (smear-negative and treated for more than 2 months before her EDD), the newborn is given isoniazid preventive therapy (A). Giving BCG to a baby of a mother with active/infectious TB (B) is unsafe, and BCG is deferred until INH prophylaxis is completed rather than given immediately in the smear-negative treated mother (C) or the recently-treated infectious mother (D).', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When performing vaginal examination eliciting a rounded brim generous fore pelvis. Straight sidewalls, blunt ischial spines and subpubic arch of 900cis an indication of.', 'Anthropoid pelvis', 'Android pelvis', 'Gynaecoid pelvis', 'Platypelloid pelvis', 'C', 'A rounded brim, generous forepelvis, straight side walls, blunt ischial spines and a subpubic arch of about 90 degrees describe the gynaecoid pelvis - the classic female pelvis most favourable for vaginal delivery (Myles Textbook for Midwives). The anthropoid (A) has a long oval antero-posterior brim, the android (B) a heart-shaped brim with prominent spines and narrow arch, and the platypelloid (D) a flattened kidney-shaped brim; none match a rounded brim with a 90-degree arch.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('After alteration of fetal circulation, the temporary structure becomes ligamentum teres.', 'Ductus arteriosus', 'Umbilical vein', 'Ductus Venosus', 'Foramen ovale', 'B', 'After birth the obliterated umbilical vein becomes the ligamentum teres (round ligament of the liver) - option B (anatomy of fetal circulation; Myles). The ductus venosus (C) becomes the ligamentum venosum, the ductus arteriosus (A) becomes the ligamentum arteriosum, and the foramen ovale (D) closes to form the fossa ovalis; none of these become the ligamentum teres.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('During history taking a pregnant woman gives history of having had one previous delivery to a viable baby. Which term would be used to refer to her.', 'A. Primigravida', 'B. Multipara', 'C. Nullipara', 'D. Primipara', 'D', 'A primipara is a woman who has given birth once to a viable infant, which matches this woman with one previous viable delivery (Myles Textbook for Midwives definitions). Primigravida (A) means pregnant for the first time, multipara (B) means having delivered more than once, and nullipara (C) means never having carried a pregnancy to viability - none fit a single prior viable birth.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In which anatomical variation of the placenta is there the cord inserted into the membranes.', 'A. Velamentous', 'B. Circumvallate', 'C. Succenturiate', 'D. Battledore', 'A', 'In velamentous insertion the umbilical cord inserts into the membranes rather than the placental mass, with the vessels running unprotected through the membranes to reach the placenta (Myles). Battledore (D) is marginal insertion at the placental edge, succenturiate (C) is an accessory placental lobe, and circumvallate (B) is a membrane-fold (raised ring) anomaly of the chorionic plate - none describe cord insertion into the membranes.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('During antenatal care the fundus is palpated at the level of the symphysis pubis, what is the fundal height.', 'A. 24 wks', 'B. 20 wks', 'C. 12 wks', 'D. 18 wks', 'C', 'The uterine fundus first becomes palpable abdominally just above the symphysis pubis at about 12 weeks gestation (Myles Textbook for Midwives, fundal height milestones). It reaches the umbilicus at about 20-22 weeks, so 20 wks (B) and 24 wks (A) are too high for a symphysis-level fundus; 18 wks (D) is also above symphysis level. 12 weeks is correct.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Part of the presentation that determines the position of the fetus is referred to as.', 'A. Vertex', 'B. Mentum', 'C. Occiput', 'D. Denominator', 'D', 'The denominator is the named landmark of the presenting part used to describe the fetal position relative to the maternal pelvis (Myles). The occiput (C, for vertex) and mentum (B, for face) are specific denominators, and the vertex (A) is a presenting area rather than the position-defining term; the general term requested is denominator.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Lightening is diagnosed when:-', 'A. A woman experiences painless uterine contractions', 'B. When woman experiences the first fetal movement', 'C. When there is descent of the fetal head into the pelvis leading to lowering of the fundus.', 'D. The fundus reaches the xiphisternum.', 'C', 'Lightening is the descent of the presenting part into the pelvic brim in the last weeks of pregnancy, which lowers the fundus and relieves epigastric/diaphragmatic pressure (Myles). Painless uterine contractions (A) are Braxton Hicks, the first felt fetal movement (B) is quickening, and a fundus at the xiphisternum (D) describes term fundal height before descent - not lightening.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which suture separates the two parietal bones?', 'A. Coronal', 'B. Sagittal', 'C. Lambdoidal', 'D. Frontal', 'B', 'The sagittal suture runs between the two parietal bones of the fetal skull (Myles, fetal skull anatomy). The coronal suture (A) separates the frontal bones from the parietals, the lambdoidal suture (C) separates the occipital bone from the parietals, and the frontal (metopic) suture (D) lies between the two frontal bones - none lies between the parietals.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The term Chadwick`s signs is used to refer to:-', 'A. Bluish violet discouration of the vaginal walls', 'B. Pulsation of the fornices', 'C. Softening of the isthmus', 'D. Causation of menstruation', 'A', 'Chadwick''s sign is the bluish-violet discolouration of the vaginal walls and cervix caused by increased pelvic vascularity and congestion in early pregnancy (Myles Textbook for Midwives). Softening of the isthmus (C) is Hegar''s sign; pulsation of the fornices (B, Osiander''s sign) and cessation of menstruation (D) are different signs, so A is correct.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('One of the following is a probable sign of pregnancy.', 'A. Visualization of fetal heart pulsation on ultrasound.', 'B. Palpation of fetal movement', 'C. Presence of human chorionic gonodotrophic hormone', 'D. Softening of the lower uterine segment.', 'C', 'Detection of human chorionic gonadotrophin (hCG) is a PROBABLE sign of pregnancy because it can occasionally be positive without a normal intrauterine pregnancy (e.g. gestational trophoblastic disease). Ultrasound visualisation of the fetal heart (A) and palpation of fetal movements by the examiner (B) are POSITIVE (definite) signs; softening of the lower segment/Hegar''s (D) is also probable, but among the listed options hCG is the intended probable sign.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('One of the following options includes predisposing factors to hydramnious.', 'A. Oesophageal atresia, choenal atresia, open neural tube defects.', 'B. Chorioangioma, spina bifida, rhesus ISO immunisation.', 'C. Premature rupture of membranes, chorioangioma, oesophageal atresia', 'D. Choanal atresia, renal agenesis open neural tube defect.', 'A', 'Polyhydramnios (hydramnios) results from impaired fetal swallowing or excess fluid: oesophageal atresia, choanal atresia and open neural tube defects all raise liquor volume, making A correct (Myles). Options B, C and D each include renal agenesis or premature rupture of membranes/isoimmunisation combinations that either cause oligohydramnios (renal agenesis) or are not the classic swallowing-obstruction group, so they are excluded.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('While attending an antenatal waman at 22 weeks gestation, the midwife finds that she has elevated blood pressure and no proteinuria, what is the possible diagnosis.', 'A. Pregnancy induced hyopertyension', 'B. Eclampsia', 'C. Gestational hypertension', 'D. Pre- eclampsia', 'C', 'Note the stem states 22 weeks with raised BP and NO proteinuria; new hypertension after 20 weeks without proteinuria is gestational hypertension (Kenya MOH maternal guidelines; Myles). Pregnancy-induced hypertension (A) is an older synonym but gestational hypertension is the precise current term; pre-eclampsia (D) requires proteinuria/end-organ signs and eclampsia (B) adds convulsions - neither is present.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following includes management of preterm prelabour rupture of membranes.', 'A. If pregnancy is more than 34 weeks give tococytics.', 'B. Do a digital vaginal exam to assess for dilation.', 'C. Give steroids if gestation is 36 weeks.', 'D. Give prophylactic antibiotics against chorioamnionitis.', 'D', 'In preterm prelabour rupture of membranes (PPROM), prophylactic antibiotics such as erythromycin reduce chorioamnionitis and prolong latency (Kenya MOH/WHO; Myles), making D correct. Digital vaginal examination (B) is avoided as it introduces infection, antenatal steroids are indicated below 34 weeks not at 36 (C), and tocolytics are not routinely given, certainly not above 34 weeks (A).', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following are predisposing factors to hydraminous.', 'A. Oesophageal atresia, multiple gestation, open neural tube defects, chorioangioma.', 'B. Isoimmunisation, renal agenesis, multiple gestation, diabetes mellitus', 'C. Open neural tube defects, choanal atresia, isoimmunisation, multiple gestation.', 'D. Diabetes mellitus, oesophageal atresia, physiologic oedema, neural tube defect.', 'A', 'Predisposing factors to polyhydramnios include oesophageal atresia, multiple gestation, open neural tube defects and chorioangioma - all in option A (Myles). Options B and C include renal agenesis or isoimmunisation groupings: renal agenesis causes oligohydramnios not polyhydramnios, and D adds physiologic oedema which is unrelated, so A is the only fully correct set.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following are pre-requisites for performing vacuum extraction.', 'A. Fully dilated cervix, inflated Foleys catheter balloon, vertex presentation, ruptured membranes.', 'B. Uterine contractions co-operative woman, term baby vertex presentation.', 'C. Intrauterine fetal death, decent less than 1/5, cephalic presentation, ruptured membranes.', 'D. Descent more than 1/5, cephalic presentation ruptured membranes, no uterine contractions.', 'A', 'Prerequisites for vacuum extraction are full cervical dilatation, ruptured membranes, cephalic/vertex presentation, an engaged head with adequate descent, and an empty bladder (hence an inflated Foley catheter balloon after catheterisation) - all in option A (Myles). B omits full dilatation and ruptured membranes; C includes intrauterine fetal death and inadequate descent (less than 1/5 palpable actually means engaged, but paired with IUFD is wrong for a live-birth ventouse); D specifies no uterine contractions, which is unsuitable.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('During caesarean section, a transverse incision made on the abdomen at the level of the symphysis pubis is referred to as', 'A. Classical incision', 'B. Lower uterine segment incision', 'C. Sub umbilical midline incision', 'D. Pfannenstiel', 'D', 'The Pfannenstiel incision is the transverse suprapubic abdominal (skin) incision made just above the symphysis pubis, commonly used for caesarean section (Myles). Classical (A) and lower uterine segment (B) refer to the UTERINE incision, not the abdominal wall, and the sub-umbilical midline (C) is a vertical, not transverse, abdominal incision - so D is correct.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In assisted breech delivery, to deliver extended arms, which maneuver can be applied.', 'A. Loveset', 'B. Burns marshall', 'C. Mauriceau Smellie Veit', 'D. popliteal fossa press', 'A', 'Loveset''s manoeuvre delivers extended (nuchal) arms in breech birth by rotating the fetal trunk so each shoulder is brought under the symphysis pubis where the arm can be swept down (Myles). Burns-Marshall (B) and Mauriceau-Smellie-Veit (C) deliver the aftercoming head, and popliteal fossa pressure (D) delivers extended legs - none deliver extended arms.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In face presentation which of the following is true?', 'A. The presentation diameter is mentovertical.', 'B. The head is well flexed.', 'C. The occiput is easily palpable.', 'D. Bitemporal diameter is one of the presenting diameters.', 'D', 'In face presentation the head is fully extended and the presenting diameters are the submentobregmatic (9.5 cm) and the biTemporal (~8.2 cm), so the bitemporal diameter is indeed one of the presenting diameters (D) (Myles). The mentovertical diameter (A) presents in brow, not face; the head is extended not flexed (B), and the occiput is NOT easily palpable because it is flexed back against the fetal spine (C).', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The management of a pregnant woman with pyelonephritis include.', 'A. Urine for culture and sensitivity, oral antibiotics , antipyretics, intravenous fluids.', 'B. Admission to hospital, urine for culture and sensitivity, oral antibiotics, antipyretics.', 'C. Urine for culture and sensitivity, intravenous antibiotics, intravenous fluids.', 'D. Plenty of fluids, oral antibiotics, nurse as an outpatient, antipyretics.', 'C', 'Acute pyelonephritis in pregnancy requires hospital admission with urine culture and sensitivity, IV antibiotics and IV fluids because of the high risk of sepsis, dehydration and preterm labour (Kenya MOH maternal guidelines; Myles). Option C captures the IV antibiotic/IV fluid management. Options A, B and D rely on oral antibiotics or outpatient care, which are inadequate for acute pyelonephritis.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following includes indications for induction of labour .', 'A. Chorio-amnionitis, Rhesus isoimmunisation, prolonged pregnancy, intrauterine fetal death.', 'B. Prolonged pregnancy, hypertensive disorders, intrauterine fetal demise, and placenta praevia.', 'C. Maternal request, bad obstetrics history, chorio-aminonitis, grand multiparity.', 'D. Previous myomectomy, placenta praevia, prolonged rupture of membranes intrauterine growth restriction.', 'A', 'Indications for induction of labour include chorioamnionitis, Rhesus isoimmunisation, prolonged (post-term) pregnancy and intrauterine fetal death - all in option A (Kenya MOH; Myles). Placenta praevia is an absolute CONTRAINDICATION to induction, which excludes options B and D; option C lists maternal request and grand multiparity, which are not standard indications.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('An antenatal client reports back to the clinic complaining of nausea, epigastric pain, black stools and constipation. What is the possible diagnosis?', 'A. Minor disorders of pregnancy.', 'B. Impending eclampsia', 'C. Side effects of iron', 'D. Peptic ulcer disease.', 'C', 'Oral iron supplementation routinely causes nausea, epigastric discomfort, constipation and black/dark stools, and this expected benign picture in an antenatal client points to iron side effects (Kenya MOH ANC/iron supplementation guidance). Peptic ulcer disease (D) is less likely without other risk features, impending eclampsia (B) presents with hypertension/headache/visual changes, and ''minor disorders of pregnancy'' (A) is too vague and does not explain black stools as well as iron does.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Development of hypertension and proteinuria after the 20th week of gestation is diagnostic.', 'A. Pregnancy induced hypertension', 'B. Gestational hypertension', 'C. Pre eclampsia', 'D. Eclampsia', 'C', 'New-onset hypertension WITH proteinuria after 20 weeks gestation is diagnostic of pre-eclampsia (Kenya MOH maternal guidelines; Myles). Gestational hypertension (B) and PIH (A) lack proteinuria, and eclampsia (D) is pre-eclampsia complicated by convulsions - not yet present - so pre-eclampsia is correct.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('To prevent isoimmunisation in rhesus negative pregnant woman, a midwife should take the following step.', 'A. Give anti D imunoglobulin within 72 hours of birth of a rhesus negative baby.', 'B. Give anti D immunoglobulin at 28 weeks if indirect coombs test is negative.', 'C. Give anti D immunoglobulin at 28 weeks if indirect coombs test is positive .', 'D. Should not give anti D immunoglobulin within 72 hours of birth of a rhesus positive baby.', 'A', 'Postnatal anti-D prophylaxis is given to a non-sensitised Rh-negative mother within 72 hours of birth to prevent isoimmunisation; option A is the closest to correct practice and is the best available choice. Strictly, anti-D is required when the baby is Rh-POSITIVE (option A as written says Rh-negative baby, which is the situation where anti-D is NOT needed), and routine 28-week antenatal prophylaxis does not depend on a positive indirect Coombs (excluding C); option D wrongly withholds anti-D after an Rh-positive baby.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('While examining a client, the midwife finds that there are uterine contractions accompanied by cervical dilation and effacement at 30 weeks of gestation. What is the possible diagnosis?', 'A. Threatened abortion', 'B. False labour', 'C. Precipitate labour', 'D. Preterm labour', 'D', 'Regular uterine contractions accompanied by cervical dilatation and effacement before 37 weeks (here 30 weeks) define preterm labour (Kenya MOH; Myles). False labour (B) produces no cervical change, threatened abortion (A) occurs before 28 weeks/viability without effacement-dilatation of established labour, and precipitate labour (C) refers to abnormally rapid labour, not the gestation-based diagnosis asked here.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which performing first examination of the newborn, the midwife elicits a fluctuating mass on the scalp due to accumulation of serous fluid. What is the possible diagnosis.', 'A. Cephalohematoma', 'B. Caput succedaneum', 'C. Subdural hematoma', 'D. Subaponeurotic hemorrhage', 'B', 'Caput succedaneum is a diffuse, soft, fluctuant scalp swelling of serous oedema fluid, present at birth and crossing suture lines (Myles; Basic Paediatric Protocols) - matching the ''fluctuating mass due to serous fluid'' described. Cephalohaematoma (A) is a firmer blood collection that does not cross sutures and appears hours after birth, subdural haematoma (C) is intracranial bleeding, and subaponeurotic (subgaleal) haemorrhage (D) is a boggy blood collection that can cross sutures and cause shock - not a serous swelling.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following factors increase production of bilirubin in newborns except?.', 'A. Polycythaemia', 'B. Sepsis', 'C. Abo incompatibility', 'D. Reduced albumin binding capacity', 'D', 'Polycythaemia, sepsis and ABO incompatibility all increase bilirubin PRODUCTION through increased red cell mass or haemolysis (Basic Paediatric Protocols; neonatal jaundice physiology). Reduced albumin binding capacity (D) does not increase production; it raises the level of free/unbound bilirubin and kernicterus risk, so it is the exception.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following includes signs of ruptured uterus.', 'A. Caesation of contractions, bandls ring, normal fetal heart rate, maternal collapse.', 'B. Strong uterine contractions, altered abdominal contours, maternal collapse, altered fetal heart rate.', 'C. Altered abdominal contour, caesation of contractions, fetal palpable in the abdomen, presentation regress.', 'D. Bandis ring, strong uterine contractions, tarchcadia, severe abdominal pains.', 'C', 'After uterine rupture, contractions cease, the abdominal contour alters, the fetus becomes easily palpable (having escaped into the peritoneal cavity) and the presenting part regresses on vaginal examination - all in option C (Kenya MOH; Myles). Options describing continuing STRONG contractions (B, D) or a NORMAL fetal heart rate (A) are inconsistent with established rupture, where fetal distress/death and cessation of contractions are expected.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following include direct causes of maternal deaths.', 'A. Antepartum hemorrhage preeclampsia, sepsis, obstructed labour.', 'B. Post partum haemorrhage , pre – elampsia, anaemia, unsafe abortion.', 'C. Pre – eclampsia, unsafe abortion, cardic disease, sepsis.', 'D. Pre-eclampsia, unsafe abortions, obstructed labour, HIV.', 'A', 'Direct maternal deaths result from obstetric complications: antepartum haemorrhage, pre-eclampsia/eclampsia, puerperal sepsis and obstructed labour - all direct causes in option A (Kenya MOH; WHO). Options B, C and D include anaemia, cardiac disease and HIV, which are INDIRECT causes (pre-existing/aggravated conditions), so they are excluded.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A midwife should not administer the next dose of magnesium sulphate to a pre-eclamptic woman if.', 'A. The Bp is 140/90mmHq', 'B. Patella reflexes are present', 'C. Respiratory rate is more than 16 Bpm.', 'D. The urine output is 80m/s in the last four hours.', 'A', 'Before each repeat dose of magnesium sulphate the safety criteria must ALL be met: respiratory rate above 16/min (C is safe), patellar reflexes present (B is safe) and urine output adequate, above ~100 mL in 4 hours (D is safe). A BP of 140/90 (A) is not a magnesium safety/toxicity parameter, so it is the one value that would NOT by itself justify withholding the dose; as written the item is imperfect but A is the best answer (MgSO4 monitoring per Kenya MOH/WHO).', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following are risks of preterm prelabour rupture of membranes except.', 'A. Chorioaninionits', 'B. Cord prolapsed', 'C. Preterm labour', 'D. Congenital abnormalities', 'D', 'Risks of preterm prelabour rupture of membranes include chorioamnionitis (A), cord prolapse (B) and preterm labour (C), all direct consequences of early membrane rupture (Kenya MOH; Myles). Congenital abnormalities (D) are not caused by PPROM (a fetal anomaly may predispose to polyhydramnios/rupture, but rupture does not cause anomalies), so D is the exception.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following include definite indications for caesarean section.', 'A. CPD, one previous scar, pre- eclampsia, transverse lie', 'B. CPD, transverse lie, more than one caesarean section scar', 'C. Twin gestation, non reassuring fetal status, pre-eclampsia, diabetes mellitus.', 'D. One previous scar, twin gestation, breech presentation CPD', 'B', 'Absolute (definite) indications for caesarean section include cephalopelvic disproportion, transverse/oblique lie and two or more previous caesarean scars - all in option B (Kenya MOH; Myles). One previous scar, twin gestation, breech and pre-eclampsia (in A, C and D) are RELATIVE indications where vaginal birth may still be attempted, so those option sets are not all ''definite''.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A whitish curdy like vaginal discharge is diagnostic of.', 'A. Bacterial vaginosis', 'B. Trichomoniasis', 'C. Chlamydia', 'D. Vulva vaginal candidiasis', 'D', 'A thick, white, curd-like (cottage-cheese) vaginal discharge with vulval itching is characteristic of vulvovaginal candidiasis (Kenya STI guidelines). Bacterial vaginosis (A) produces a thin grey, fishy-smelling discharge, trichomoniasis (B) a frothy greenish-yellow discharge, and chlamydia (C) is often asymptomatic or mucopurulent - none give a curd-like discharge, so D is correct.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following is not suitable client for an IUCD:-', 'Woman with cervicitis.', 'Post abortion 19 years old.', 'Women who are HIV positive with no complications.', 'Women who are taking ARV with no clinical complications.', 'A', 'Active cervicitis is an unsuitable (contraindicated) state for IUCD insertion because instrumenting an infected/inflamed cervix risks ascending pelvic infection (WHO Medical Eligibility Criteria, adopted in Kenya MOH Family Planning Guidelines - cervicitis/PID is Category 4 for IUCD initiation). Option B (post-abortion after infection excluded), C (HIV-positive, clinically well) and D (on ARVs, stable) are all eligible for IUCD, so they are suitable and therefore wrong answers to a ''not suitable'' item.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Concerning jadalle as a method of contraception:-', 'It is an implant with an effectiveness period of 3 years.', 'It is an injectable with effectiveness period of 3 months.', 'It is an implant with an effectiveness period of 5 years.', 'Amenorrhoea is a rare side effects.', 'C', 'Jadelle is a two-rod levonorgestrel subdermal implant licensed for 5 years, so C is correct (Kenya MOH Family Planning Guidelines/WHO). A (3-year implant) describes Implanon/single-rod, not Jadelle; B is false because Jadelle is an implant not an injectable (the 3-month injectable is DMPA); D is false because amenorrhoea and menstrual changes are COMMON, not rare, with progestogen-only implants.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following is true about obstructed labour except?', 'There is no advance in presenting part.', 'There is no advance in cervical dilatation.', 'It is due to cephalopelvic disproportion.', 'It is due to malpresentation and malposition.', 'C', 'This is an ''except'' item; A and B are true (obstructed labour shows arrest of descent of the presenting part and arrest of cervical dilatation) and D is true (malpresentation/malposition is a recognised cause). C is the required answer only if read as CPD being the sole/defining cause, which is over-restrictive since obstruction has several causes (Myles Textbook for Midwives; Kenya MOH). The stem is imperfectly worded because CPD is in fact a genuine cause, making the ''except'' ambiguous, but C is the least-defensible universal statement and the best available choice.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following is true about neonatal hypothermia except?', 'Baby''s temperature is below 360C.', 'It is predisposed by asphyxia neonatorum.', 'It is predisposed by sepsis.', 'Baby''s temperature is below 350C.', 'D', 'Neonatal hypothermia is defined as an axillary temperature below 36.5C (mild 36.0-36.4, moderate 32.0-35.9, severe <32) per WHO/Kenya Basic Paediatric Protocols, so option A (<36C) is broadly acceptable as a threshold while D (<35C) misstates the standard cut-off and is the ''except''. B (asphyxia) and C (sepsis) are true predisposing factors. D is the correct answer.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which degree of placenta praevia has substantial portion in the lower uterine segment and partially coversthe internal os?', 'Type 1.', 'Type 2', 'Type 3.', 'Type 4.', 'B', 'Type II (marginal) placenta praevia has a substantial portion in the lower uterine segment and reaches/partially covers the internal os (Myles Textbook for Midwives). Type I (lateral) is low but does not reach the os; Type III partially covers the os only when closed; Type IV completely covers the os. Given the description ''partially covers the internal os'', Type II is the best fit and B is correct.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following statements is true about Vitamin K in newborn babies?', 'It is poorly transported across the placental barrier.', 'It is synthesized in the bowels by normal bacteria.', 'It is important in activating clotting factors.', 'All the above.', 'D', 'All three statements are true, so ''All the above'' (D) is correct (Myles; Kenya Basic Paediatric Protocols): vitamin K crosses the placenta poorly, is synthesised by gut flora which are absent at birth, and is essential for activating clotting factors II, VII, IX and X - hence prophylactic vitamin K at birth. A, B and C are each individually true but incomplete, making D the single best answer.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the occurrence of uterine contractions that produce progressive cervical effacement and dilation between 24 weeks and 37 weeks of gestation:-', 'Threatened abortion.', 'Preterm labour.', 'False labour.', 'Precipitate labour.', 'B', 'Regular uterine contractions producing progressive cervical effacement and dilatation between 24 and 37 weeks define preterm labour (Myles; Kenya MOH maternal guidelines). A (threatened abortion) is before 24/28 weeks with a closed os; C (false labour) has no progressive cervical change; D (precipitate labour) is very rapid labour to term, not defined by gestation. B is correct.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('One of the following is not a contraindication to vaginal delivery:-', 'Cephalopelvic disproportion.', 'Transverse lie.', 'One previous scar.', 'Placenta praevia type 2 posterior.', 'C', 'A single previous lower-segment caesarean scar is not an absolute contraindication to vaginal birth; a trial of labour (VBAC) is permitted (Myles; Kenya MOH). Cephalopelvic disproportion (A), transverse lie (B) and placenta praevia type 2 (D) are all contraindications to vaginal delivery, so C is the correct ''not a contraindication''.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following statements is true about neonatal hypoglycaemia:-', 'Treat by giving baby oral glucose.', 'It is predisposed by neonatal hypothermia.', 'The baby blood sugar is below 3.5mmols/litre.', 'Treat by giving 25% glucose intravenously.', 'B', 'Hypothermia increases glucose consumption and predisposes to neonatal hypoglycaemia, so B is the true statement (Kenya Basic Paediatric Protocols). A is wrong because symptomatic hypoglycaemia is treated with IV dextrose, not oral glucose; C is wrong because the threshold is <2.6 mmol/L, not 3.5; D is wrong because the correct treatment is IV 10% dextrose, not 25% glucose. B is correct.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following statements are true about respiratory distress syndrome except?', 'Signs and symptoms are present at birth.', 'It occurs due to inadequate surfactant factor.', 'It is predisposed by prematurity.', 'It is predisposed by neonatal hypothermia.', 'A', 'This is an ''except'' item. RDS from surfactant deficiency (hyaline membrane disease) typically develops within minutes to hours after birth and worsens progressively over the first days, rather than being fully present at the moment of birth, so A is the false statement (Myles; Kenya Basic Paediatric Protocols). B (surfactant deficiency), C (prematurity) and D (hypothermia) are all true, making A the required answer.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('One of the following is not a way to diagnose cephalopelvic disproportion:-', 'X-ray pelvimetry.', 'Digital vaginal examination.', 'Pawlicks grip.', 'Speculum vaginal examination.', 'D', 'Speculum examination visualises the cervix and vaginal walls and does NOT assess bony pelvic capacity, so it cannot diagnose cephalopelvic disproportion - D is the correct ''not a way'' (Myles Textbook for Midwives). X-ray pelvimetry (A), digital vaginal/clinical pelvic assessment (B) and Pawlik''s grip for head fitting/engagement (C) all contribute to assessing CPD.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Development of hypertension and proteinuria before 20th week of gestation is referred to as:-', 'Gestational hypertension.', 'Pre-eclampsia.', 'Pregnancy induced hypertension.', 'Superimposed pre-eclampsia.', 'D', 'Hypertension with proteinuria before 20 weeks reflects pre-existing (chronic) hypertension/renal disease; new-onset proteinuria on that chronic background is superimposed pre-eclampsia, so D is the best fit (Myles; Kenya MOH). Gestational hypertension (A/C) and pre-eclampsia (B) are by definition diagnosed only after 20 weeks, so they cannot apply before 20 weeks. D is correct.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following enzymes act on unconjugated bilirubin in the liver:-', 'Stercobilinogenase.', 'Glucuronic reductase.', 'Glucuronyl transferase.', 'Beta glucuronidase.', 'C', 'Glucuronyl (UDP-glucuronosyl) transferase conjugates fat-soluble unconjugated bilirubin with glucuronic acid in the hepatocyte to form water-soluble conjugated bilirubin, so C is correct (standard physiology; Myles). Its immaturity underlies neonatal physiological jaundice. Beta-glucuronidase (D) deconjugates bilirubin in the gut (increasing enterohepatic reabsorption), while stercobilinogenase (A) and ''glucuronic reductase'' (B) are not the conjugating hepatic enzyme.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following statements are true about preventing isoimmunisation except:-', 'Anti D immunoglobulin should be given at 28 weeks if indirect coombs test is positive.', 'Anti D immunoglobulin should be given to Rhesus negative women within 72 hours of birth to a Rhesus positive baby.', 'Anti D immunoglobulin should be given at 28 weeks if indirect coombs test is negative.', 'Anti D immunoglobulin should not be given to women who give birth to Rhesus negative baby.', 'A', 'This ''except'' item asks which statement is FALSE. Routine antenatal anti-D at 28 weeks is given to non-sensitised Rhesus-negative women, i.e. those with a NEGATIVE indirect Coombs (option C is correct practice); once already sensitised (Coombs positive) anti-D is useless, so A is the false statement and the answer. B (anti-D within 72 hours of delivering a Rh-positive baby) and D (no anti-D needed if the baby is Rh-negative) are both correct.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following are signs of ruptured uterus except:-', 'Severe abdominal pain, tachycardia, altered abdominal contours, fetus palpable in the abdomen.', 'Caesation of contractions, altered abdominal contours, maternal collapse, altered fetal heart rate.', 'Caesation of contractions, altered fetal heart rate, maternal collapse.', 'Tarchycardia, altered abdominal contours, maternal collapse, presentation regress.', 'C', 'Classic ruptured uterus presents with cessation of contractions, altered/abnormal abdominal contour with easily palpable fetal parts, altered or absent fetal heart, maternal collapse/shock and severe abdominal pain (Myles Textbook for Midwives). Options A, B and D each include the key sign of altered abdominal contour; option C omits it, making it the least complete grouping and the ''except'' answer C.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following are parts of the female external genitalia:', 'Prepuce, clitoris, frenulum, fourchette.', 'Prepuce, clitoris, fourchette, urethra.', 'Prepuce, clitoris, frenulum, rectum.', 'Prepuce, clitoris, urethra, rectum.', 'A', 'The vulva (external genitalia) includes the mons pubis, labia majora and minora, clitoris with its prepuce and frenulum, vestibule and fourchette (Myles anatomy). Option A lists prepuce, clitoris, frenulum and fourchette - all true vulval structures. B, C and D each wrongly include the urethra and/or rectum, which are separate structures, so A is correct.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('An abnormal opening extending between the bladder and the vagina that allows the continuous involuntary discharge of urine into the vaginal vault is called:', 'A vaginal fistula.', 'Rectovaginal fistula.', 'Vesico-vaginal fistula.', 'Enterovaginal fistula.', 'C', 'An abnormal communication between the bladder and vagina causing continuous involuntary leakage of urine is a vesico-vaginal fistula (Myles; Kenya MOH obstetric fistula guidelines), so C is correct. Rectovaginal (B) and enterovaginal (D) fistulae leak faeces/bowel content, not urine, and ''vaginal fistula'' (A) is a non-specific term. C is correct.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Cryptomenorrhoea is one of the disorders of menstruation.The best description for this disorder is:', 'It is physiological and pathological which falls under primary and secondary menstruation.', 'It is when menses have commenced but there is no external bleeding and it is also referred to as false amenorrhea.', 'It is the absence of menstruation and it can be metrorrhagia or menorrhagia.', 'It is the menstruation which has occurred for a time and has then ceased due to hormonal disorders and local diseases.', 'B', 'Cryptomenorrhoea (concealed or false amenorrhoea) is when menstruation occurs but the blood is retained with no external bleeding, typically from outflow obstruction such as an imperforate hymen, so B is correct (Myles/gynaecology texts). A, C and D describe primary/secondary amenorrhoea and abnormal bleeding patterns (metrorrhagia/menorrhagia), which do not match cryptomenorrhoea. B is correct.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('On abdominal examination, the fetal buttocks are palpated on the lower uterine pole.What is the denominator?', 'Breech', 'Sacrum.', 'Sinciput.', 'Pubic Symphisis', 'B', 'Buttocks palpated at the lower pole indicate a breech presentation, whose denominator (the fixed reference point on the presenting part) is the sacrum, so B is correct (Myles Textbook for Midwives). Breech (A) is the presentation, not the denominator; sinciput (C) is the denominator/reference for brow, and the pubic symphysis (D) is a maternal landmark. B is correct.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following borders the uterus posteriorly?', 'Recto-uterine pouch of Douglass and rectum.', 'Utero-vesical pouch and the bladder.', 'Recto-uterine pouch of Douglass and the bladder.', 'Utero-vesical pouch and the rectum.', 'A', 'Posteriorly the uterus is related to the recto-uterine pouch (pouch of Douglas) and the rectum, so A is correct (Myles anatomy of the uterus). The utero-vesical pouch and bladder (B) lie ANTERIORLY, so options B, C and D misplace the posterior relations. A is correct.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In which part of the fallopian tube does fertilization take place?', 'Interstitial part.', 'Infundibulum.', 'Ampulla', 'Isthmus.', 'C', 'Fertilisation normally occurs in the ampulla, the widest and longest part of the fallopian tube (Myles embryology). The infundibulum (B) captures the ovum, the isthmus (D) is the narrow segment nearest the uterus, and the interstitial part (A) traverses the uterine wall; none is the usual site of fertilisation. C is correct.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following hormones cause uterine contractions?', 'Oestrogen and prostaglandins.', 'Relaxin and oxytocin.', 'Oxytocin and prostaglandins.', 'Progesterone and oestrogen.', 'C', 'Oxytocin and prostaglandins are the principal hormones that stimulate myometrial (uterine) contractions, so C is correct (Myles). Progesterone and relaxin (options B, D) promote uterine quiescence/relaxation, and oestrogen increases contractility mainly by upregulating oxytocin receptors rather than acting alone, so the pairing in A is less accurate than C. C is correct.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following are the longest diameters of the fetal skull?', 'Mental vertical.', 'Submental bregmation.', 'occipito bregmatic.', 'Occipital frontal.', 'A', 'The mentovertical diameter (about 13.5 cm), presenting in a brow presentation, is the longest antero-posterior diameter of the fetal skull, so A (''mental vertical'') is correct (Myles). Occipitofrontal is ~11.5 cm, submentobregmatic ~9.5 cm and occipitobregmatic ~9.5 cm - all shorter. A is correct.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('During fetal development quickening takes place at what gestation?', '4 weeks – 8 weeks.', '16 weeks – 20 weeks.', '8 weeks – 12 weeks.', '24 weeks – 28 weeks.', 'B', 'Quickening, the mother''s first perception of fetal movements, is usually felt between 16 and 20 weeks (earlier in multiparas, later in primigravidas), so B is correct (Myles). 4-8 weeks (A) and 8-12 weeks (C) are too early for maternal perception, and 24-28 weeks (D) is too late. B is correct.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The part of the fetal head that determines the position is referred to as:-', 'The presentation.', 'The presenting part.', 'The denominator.', 'The occiput.', 'C', 'Position is defined as the relationship of the denominator of the presenting part to fixed points on the maternal pelvis, so the denominator determines position - C is correct (Myles). The presentation (A) is the part that enters the pelvis first, the presenting part (B) is what overlies the os, and the occiput (D) is only the denominator for a vertex presentation, not the general answer. C is correct.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the process through which a new born baby losses heat to cold surfaces?', 'Conduction.', 'Convention.', 'Evaporation.', 'Radiation.', 'A', 'Conduction is heat loss from the newborn to a cold surface in direct contact (e.g. a cold weighing scale or mattress), so A is correct (Kenya Basic Paediatric Protocols; Myles). Convection (B) is loss to cooler moving air, evaporation (C) is loss from wet skin/liquor, and radiation (D) is loss to nearby cold objects without contact. A is correct.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following is not a hormone produced by the anterior pituitary gland?', 'Luteinizing hormone.', 'Follicle stimulating hormone.', 'Oxytocin.', 'Prolactin.', 'C', 'Oxytocin is synthesised in the hypothalamus and stored/released from the POSTERIOR pituitary, not produced by the anterior pituitary, so C is the correct ''not a hormone of the anterior pituitary'' (standard physiology; Myles). LH (A), FSH (B) and prolactin (D) are all anterior pituitary hormones. C is correct.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('After conception, the fertilized ovum is referred to as?', 'Zygote.', 'Embryo.', 'Morula.', 'Blastocyst.', 'A', 'Immediately after fertilisation the union of ovum and sperm forms a single diploid cell, the zygote, so A is correct (Myles embryology). The zygote then cleaves into the morula (C) and cavitates into the blastocyst (D), and only later is termed the embryo (B). A is correct.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which part of the blastocyst develops into the placenta and the chorion?', 'The mesoderm.', 'Inner cell mass.', 'Trophoblast.', 'Cytotrophoblast', 'C', 'The outer trophoblast layer of the blastocyst develops into the placenta and chorion, so C is correct (Myles embryology). The inner cell mass (B) forms the embryo proper, the cytotrophoblast (D) is only the inner cellular layer of the trophoblast, and the mesoderm (A) is a germ layer derived from the embryonic disc. C is correct.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the anatomical variation of the placenta whereby the cord is inserted at the edge of the placenta?', 'Succenturiate', 'Circumvallate.', 'Velamentous.', 'Battledore.', 'D', 'A battledore placenta is the variation where the umbilical cord is inserted at the margin/edge of the placenta, so D is correct (Myles). Velamentous (C option text) insertion is into the membranes, succenturiate (A) is an accessory lobe, and circumvallate (B) has a raised ring of membranes at the placental edge. D is correct.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('During pregnancy, the fundus at 16 weeks is at which level?', 'Upper margin of the umbilical.', 'Lying between the symphysis pubic and the umbilicus.', 'Lying between the umbilicus and the xiphisternum.', 'At the xiphoid sternum.', 'B', 'At 16 weeks the uterine fundus is palpable midway between the symphysis pubis and the umbilicus, so B is correct (Myles). It reaches the level of the umbilicus at about 22-24 weeks, so A (upper margin of umbilicus) is too high for 16 weeks; C (umbilicus to xiphisternum) and D (xiphisternum) correspond to the third trimester. B is correct.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('One of the following includes contraindications for induction.', 'Transverse lie, placenta abruption, choriammonitis', 'Active genital herpes infection, cord presentation, pelvic structural abnormalities.', 'Active genital herpes infection, rhesus isoimmunisation, preterm pre-labour, rupture of membranes.', 'Previous myomectomy, prolonged pregnancy, rhesus isoimmunisation.', 'B', 'Contraindications to induction of labour include active genital herpes (viral shedding risk to the neonate), cord presentation/prolapse and pelvic structural abnormalities causing obstruction - option B lists valid contraindications (Myles; Kenya MOH). Option A includes placental abruption and chorioamnionitis which usually warrant delivery, and C and D mix in indications such as prolonged pregnancy and Rhesus isoimmunisation, so B is the best answer.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When performing 1st examination of the newborn the midwife makes a diagnosis of Erb''s palsy. What are the possible findings.', 'A. Paralysis of the lower arm, wrist and hand.', 'B. Paralysis of the shoulder and the arm, not the hand.', 'C. A drop of the hand with no grasping reflexes.', 'D. Complete paralysis of the shoulder, the arm and the hand.', 'B', 'Erb''s palsy results from injury to the upper brachial plexus (C5-C6), causing paralysis of the shoulder and upper arm (adducted, internally rotated, pronated ''waiter''s tip'' position) with the hand spared, so B is correct (Myles; Kenya Basic Paediatric Protocols). Klumpke''s palsy (lower plexus, C8-T1) affects the wrist and hand (options A and C), and complete plexus injury (D) affects the whole limb. B is correct.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Trisomy 21 results into:-', 'A. Edwards Syndrome', 'B. Downs Syndrome', 'C. Patau Syndrome', 'D. Sheehans Syndrome', 'B', 'Trisomy 21 (an extra chromosome 21) causes Down syndrome, so B is correct (standard genetics; Myles). Edwards syndrome (A) is trisomy 18, Patau syndrome (C) is trisomy 13, and Sheehan''s syndrome (D) is postpartum pituitary necrosis, not a trisomy. B is correct.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which degree of placenta praevia has substantial portions in the lower uterine segment and completely covers the internal cervical Os.', 'A. Type 5', 'B. Type 4', 'C. Type 2', 'D. Type 3', 'B', 'Type IV (central) placenta praevia has a substantial portion in the lower uterine segment and completely covers the internal os even when the cervix is dilated, so B (Type 4) is correct (Myles). Type 2 (C) partially reaches the os, Type 3 (D) partially covers it, and ''Type 5'' (A) does not exist in the four-grade classification. B is correct.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('While attending to an antenatal woman at 28 weeks of gestation, the midwife finds that she has elevated blood pressure and proteinuria. After one hour the patient loses consciousness. What is the possible diagnosis?', 'A. Gestation hypertension', 'B. Pregnancy induced hypertension', 'C. Pre-eclampsia', 'D. Eclampsia', 'D', 'Hypertension plus proteinuria after 20 weeks is pre-eclampsia; when it is complicated by convulsions or loss of consciousness it becomes eclampsia, so D is correct (Myles; Kenya MOH PET/eclampsia guidelines). Gestational hypertension (A) and PIH (B) lack proteinuria/end-organ features, and pre-eclampsia (C) precedes but does not itself include the loss of consciousness described. D is correct.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In left occipito posterior position the following findings can be elicited.', 'A. Siniciput facing right illiopectineal eminence, sagittal suture in right oblique diameter and the occiput facing left sacro iliac joint.', 'B. Sinciput facing right illiopectineal eminence, sagittal suture in left oblique diameter and the occiput facing left iliac joint.', 'C. Sinciput facing left sacro iliac joint , sagittal suture in left oblique diameter and the occiput facing right illiopechneal eminence.', 'D. Sinciput facing left illiopectineal line, sagittal suture in transverse diameter and the occiput facing right illiopechneal line.', 'A', 'In left occipitoposterior (LOP) the occiput points to the left sacro-iliac joint, the sinciput faces the right iliopectineal eminence, and the sagittal suture lies in the right oblique diameter of the pelvis - option A matches this exactly (Myles). B places the suture in the wrong oblique, C reverses occiput and sinciput, and D describes a transverse position, so A is correct.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which anatomical variation of the placenta has the cord inserted into the membranes:', 'A. Circumvallate.', 'B. Succentiariate.', 'C. Battle done.', 'D. Valamentous.', 'D', 'In a velamentous insertion the umbilical cord inserts into the membranes at a distance from the placenta, with the vessels running unprotected between amnion and chorion to reach the placental edge, so D is correct (Myles). Circumvallate (A) is a membrane ring anomaly, succenturiate (B) is an accessory lobe, and battledore (C) is marginal cord insertion into the placenta itself. D is correct.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The relationship between the long axis of the fetus and long axis of uterus is referred to as:', 'A. Attitude', 'B. Flexion.', 'C. Lie.', 'D. Presentation', 'C', 'Per Myles Textbook for Midwives, lie is the relationship between the long axis of the fetus and the long axis of the uterus (longitudinal, transverse or oblique). Attitude is the relationship of fetal parts to one another; flexion is a degree of that attitude; presentation is the fetal part occupying the lower pole. Only lie fits the definition.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In fetal circulation, the temporary structure connecting the right atrium to the left atrium is known as:', 'A. Hypogastric arteries.', 'B. Foremen ovale.', 'C. Ductus arteriosus.', 'D. Ductus venosus.', 'B', 'Per Myles fetal circulation, the foramen ovale is the flap opening in the interatrial septum that shunts oxygenated blood from the right atrium to the left atrium, bypassing the non-functional fetal lungs. The ductus arteriosus links the pulmonary artery to the aorta, the ductus venosus links umbilical vein to inferior vena cava, and the hypogastric arteries become the umbilical arteries carrying deoxygenated blood; none connect the two atria.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In mechanism of normal labour which movement occurs when the largest transverse diameter of the fetal skull is born:-', 'A. Crowning', 'B. Restitution', 'C. Descent', 'D. External rotation of head', 'A', 'Per Myles mechanism of normal labour, crowning is the moment the largest transverse diameter (biparietal) of the fetal head distends the vulva and the head no longer recedes between contractions. Descent is ongoing downward movement, restitution is realignment of the head with the shoulders after delivery of the head, and external rotation follows restitution as the shoulders rotate internally; none coincide with birth of the widest transverse diameter.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In physiology of peurperium, what is the process of auto digestion of dead tissues:', 'A. Involution', 'B. Ischaemia', 'C. Autolysis', 'D. Sub involution', 'C', 'Per Myles physiology of the puerperium, autolysis is the self-digestion of the enlarged uterine muscle cells by proteolytic enzymes, reducing their size and contributing to involution. Involution is the overall return of the uterus to its non-pregnant state, ischaemia (vasoconstriction) is another involution mechanism but not auto-digestion, and sub-involution is failure of involution; only autolysis names the enzymatic breakdown of dead tissue.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The outer layer of the blastocyst which has nucleated protoplasm capable of breaking down the decidua is referred to us:-', 'A. Cytotrophoblast', 'B. Blastocale', 'C. Mesoderm', 'D. Syncytiotrophoblast', 'D', 'Per Myles embryology, the syncytiotrophoblast is the outer, multinucleated protoplasmic layer of the trophoblast that erodes the decidua and maternal vessels to embed the blastocyst. The cytotrophoblast is the inner cellular layer, the blastocoele is the fluid cavity, and mesoderm is a germ layer formed later; only the syncytiotrophoblast has the invasive nucleated protoplasm described.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In fetal development the testis descend into the scrotum at between:', 'A. 24 weeks – 28 weeks', 'B. 28 weeks – 32 weeks', 'C. 32 weeks – 36 weeks', 'D. 20 weeks – 24 weeks', 'C', 'Per Myles fetal development, the testes descend from the abdomen through the inguinal canal into the scrotum at about 32-36 weeks; palpable scrotal testes are therefore a sign of maturity in the term male neonate. Descent before 32 weeks (options A, D at 20-28 weeks) is too early, and 28-32 weeks (B) precedes completed descent; 32-36 weeks is correct.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following is not a positive sign of pregnancy:.', 'A. Visualization of fetal pulsation on ultrasound.', 'B. Palpation of fetal movement.', 'C. Presence of human chorionic gonadotrophic hormone in urine', 'D. Palpation of fetal parts.', 'C', 'Per Myles Textbook for Midwives, positive (diagnostic) signs of pregnancy are attributable directly to the fetus: visualisation of fetal pulsation on ultrasound (A), palpation of fetal movement (B) and palpation of fetal parts (D). Presence of urinary hCG (C) is only a probable sign because it can be raised in molar or ectopic pregnancy and certain tumours; hence C is NOT a positive sign and is the correct answer to this ''except''-type stem.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which region of the fetal skull is bounded by the anterior fontanella two parietal eminencies and the posterior fontanelle:', 'A. Occiput', 'B. Vertex', 'C. Sincuput', 'D. Forehead', 'B', 'Per Myles, the vertex is the diamond-shaped region of the fetal skull bounded by the anterior fontanelle, the two parietal eminences and the posterior fontanelle; it is the presenting area in a well-flexed cephalic presentation. The occiput lies behind the posterior fontanelle, the sinciput (brow) is in front of the anterior fontanelle, and the forehead is anterior still; only the vertex is bounded by both fontanelles.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following structures bound the uterus anterior:', 'A. Recto uterine pouch and rectum.', 'B. Utero vesical pouch and rectum', 'C. Recto vesical pouch and bladder', 'D. Utero vesical pouch and bladder', 'D', 'Per Myles pelvic anatomy, the uterus is bounded anteriorly by the uterovesical pouch and the urinary bladder, while the recto-uterine pouch (of Douglas) and rectum lie posteriorly. Options citing the recto-uterine/recto-vesical pouch or rectum describe posterior relations, so D is the only correct anterior boundary.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which anatomical variation of the placenta has the cord inserted into margin of the placenta:', 'A. Circumvallate.', 'B. Succentiariate.', 'C. Battledore.', 'D. Valamentous.', 'C', 'Per Myles, a battledore placenta is the variant in which the umbilical cord is inserted into the margin (edge) of the placenta, resembling a table-tennis bat. Velamentous insertion is into the membranes away from the placental edge, circumvallate has a raised chorionic ridge, and succenturiate is an accessory lobe; only battledore describes marginal cord insertion.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which uterine support is also referred to as the cardinal ligaments:', 'A. Transverse cervical ligaments.', 'B. Uterosacral ligament.', 'C. Broad ligament.', 'D. Round ligament.', 'A', 'Per Myles, the transverse cervical (cardinal / Mackenrodt''s) ligaments fan out from the cervix and upper vagina to the lateral pelvic walls and are the chief mechanical support of the uterus. The uterosacral ligaments run posteriorly to the sacrum, the broad ligament is a peritoneal fold giving little support, and the round ligaments maintain anteversion, not primary support.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In fetal circulation, the temporary structure connecting the left umbilical vein to the inferior venacava is known as:', 'A. Hypogastric arteries.', 'B. Foremen ovale.', 'C. Ductus arteriosus.', 'D. Ductus venosus.', 'D', 'Per Myles fetal circulation, the ductus venosus connects the left umbilical vein to the inferior vena cava, allowing oxygenated blood to largely bypass the liver. The foramen ovale is an atrial shunt, the ductus arteriosus links pulmonary artery to aorta, and the hypogastric arteries are the paired umbilical arteries; only the ductus venosus matches the described connection.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which suture separates the frontal bone from the two parietal bones:', 'A. Coronal.', 'B. Sagittal.', 'C. Lambdoidal.', 'D. Frontal.', 'A', 'Per Myles, the coronal suture separates the frontal bone from the two parietal bones. The sagittal suture runs between the two parietal bones, the lambdoidal suture separates the parietals from the occipital bone, and the frontal (metopic) suture lies between the two frontal bones; only the coronal fits the description.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The obstetrical conjugate of the pelvic brim measures how many centimetres:', 'A. 12cm', 'B. 11cm', 'C. 13cm', 'D. 12.5cm', 'B', 'Per Myles, the obstetric conjugate runs from the sacral promontory to the posterior inner border of the symphysis pubis and, at about 11 cm, is the smallest and most important AP diameter of the pelvic brim through which the head must pass. The true/anatomical conjugate is ~11.5-12 cm and the diagonal conjugate ~12.5-13 cm, so 12, 12.5 and 13 cm describe other conjugates, not the obstetric one.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('After alteration of fetal circulation at birth which temporary structure becomes ligametumteres', 'A. Umbilical vein', 'B. Ductus arterosis', 'C. Ductus venosus', 'D. Foramen ovale', 'A', 'Per Myles, after birth the obliterated left umbilical vein becomes the ligamentum teres (round ligament) of the liver. The ductus venosus becomes the ligamentum venosum, the ductus arteriosus becomes the ligamentum arteriosum, and the foramen ovale closes to the fossa ovalis; only the umbilical vein becomes the ligamentum teres.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Damaged sore nipples caused by incorrect attachment of the baby to the breast is managed by.', 'A. Stop breastfeeding, put mother on antibiotics, apply warm compress', 'B. Administer analgesics, apply tropical antibiotics, encourage breast feeding when woman is not in pain.', 'C. Correct positioning of the baby on breast, give paracetamol, give antibiotics.', 'D. Correct positioning of baby on breast, apply expressed breast milk on damaged nipples, express breast milk to avoid engorgement.', 'D', 'Per Kenya MOH/BFHI breastfeeding guidance, sore/damaged nipples from poor attachment are managed by correcting positioning and attachment, applying a little expressed breast milk to the nipple to aid healing, and expressing to prevent engorgement while breastfeeding continues. Stopping breastfeeding (A) and routine antibiotics (A, B, C) are wrong because there is no infection; antibiotics are reserved for mastitis, making D the complete correct management.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Components of a partograph that assess progress of labour include.', 'A. Contractions, descent, moulding', 'B. Contractions, fetal heart rate, liquor amnii', 'C. Descent, moulding, liquor amnii', 'D. Blood pressure, contractions, descent.', 'A', 'Per the WHO/Kenya MOH partograph, progress of labour is monitored by cervical dilatation, descent of the head, uterine contractions and moulding; fetal heart rate and liquor assess fetal condition and blood pressure assesses maternal condition. Option A (contractions, descent, moulding) lists only progress parameters, whereas B, C and D each mix in fetal or maternal condition parameters (FHR, liquor, BP).', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('During antenatal care the fundus is palpable at the xiphisternum. What is the gestation', 'A. 12 weeks', 'B. 24 weeks', 'C. 36 weeks', 'D. 40 weeks', 'C', 'Per Myles antenatal abdominal examination, the fundus reaches the xiphisternum at about 36 weeks; near term (40 weeks) the fundus usually drops slightly with lightening as the head engages. At 12 weeks the fundus is just palpable above the symphysis and at 24 weeks it is at the umbilicus, so 36 weeks is correct.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Preventive measures offered during antenatal care include.', 'A. Tetanus toxoid, sulphadoxine pyrimethamine, mebendazole', 'B. Folic acid, ferrous sulfate, hemoglobin check.', 'C. Tetanus toxoid, insecticide treated nets, counsel on diet.', 'D. Haemoglobin check, insecticide treated nets, sulphadoxine pyrimethamine', 'A', 'Per Kenya MOH focused antenatal care, the classic preventive interventions are tetanus toxoid immunisation, intermittent preventive treatment of malaria with sulphadoxine-pyrimethamine (IPTp) and deworming with mebendazole. Options B and D centre on haematinics, haemoglobin checks and diet counselling, which are supportive/screening measures rather than the specific preventive triad; C mixes in ITNs and diet counselling but omits a full preventive set, so A is the best fit.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When performing a pelvic assessment, eliciting a heart shaped brim, narrow forepelvis, convergent sidewalls prominent ischial spines and an acute subpubic arch is an indication of.', 'A. Anthropoid pelvis', 'B. Android pelvis', 'C. Gynaecoid pelvis', 'D. Platypelloid pelvis', 'B', 'Per Myles, the android (male-type) pelvis has a heart-shaped brim, narrow forepelvis, convergent (funnelling) side walls, prominent ischial spines and a narrow/acute subpubic arch, predisposing to deep transverse arrest and obstructed labour. The gynaecoid has a rounded brim and wide arch, the anthropoid a long oval AP brim, and the platypelloid a flat kidney-shaped brim; only the android matches every feature listed.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When performing vaginal examination the midwife should diagnose vertex presentation if she palpate:', 'A. A region from the anterior fontanelle and the coronal suture, to the orbital ridges.', 'B. A region between the foramen magnum and the posterior fontanelle.', 'C. A region bounded by the posterior fontanelle, two parietal eminencies and anterior fontanelle.', 'D. A region from the orbital rides to the mentum', 'C', 'Per Myles, vertex presentation is confirmed on vaginal examination when the palpated area is the vertex, bounded by the anterior fontanelle, the two parietal eminences and the posterior fontanelle. Option A (anterior fontanelle/coronal suture to orbital ridges) describes brow, B (foramen magnum to posterior fontanelle) the occiput/face region, and D (orbital ridges to mentum) the face; only C delineates the vertex.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The physiology the explains caesation of ovulation during pregnancy is that.', 'A. The circulating levels of oestrogen and progesterone are high.', 'B. Circulation levels of oestrogen and progesterone are low.', 'C. Low levels of oestrogen and progesterone promote release of FSH & LH', 'D. High levels of oestrogen and progesterone promote release of follicle stimulating hormone and luteinizing hormones.', 'A', 'Per reproductive physiology (Myles), the persistently high circulating oestrogen and progesterone from the corpus luteum and then the placenta exert negative feedback on the hypothalamic-pituitary axis, suppressing FSH and LH and so preventing further follicular maturation and ovulation during pregnancy. Options describing low hormone levels or hormones promoting FSH/LH release are physiologically incorrect.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('During examination of the placenta the cord is inserted at the edge. What is this anatomical variation.', 'A. Circumvallata', 'B. Velamentous', 'C. Battledore', 'D. Succenturiate.', 'C', 'Per Myles, cord insertion at the edge/margin of the placenta is a battledore insertion. Velamentous insertion is into the membranes, circumvallate has a raised chorionic ring on the fetal surface, and succenturiate is an accessory lobe joined by vessels; only battledore describes marginal cord insertion.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('One of the following includes management of clients with cardiac disease in pregnancy:', 'A. Administer tocolytics if a woman goes into preterm labour.', 'B. Perform caesarean section on all women with cardiac disease.', 'C. Administer anticoagulants on women who have prosthetic valves.', 'D. Use ergometrine in AMTSL if syntocin is not available.', 'C', 'Per Myles/MOH management of cardiac disease in pregnancy, women with mechanical prosthetic valves require anticoagulation to prevent valve thrombosis and embolism. Tocolytics are used cautiously (beta-agonists strain the heart), caesarean is reserved for obstetric indications rather than performed on all, and ergometrine is avoided because its vasoconstriction sharply raises blood pressure and cardiac load; hence C is correct.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following statements includes management of a pregnant woman who has a Hb of less than 5gm/dl:', 'A. Administer total dose iron infusion.', 'B. Transfuse with whole blood with no diuretic.', 'C. Transfuse with red blood cells under a diuretic.', 'D. Administer oral haematinics.', 'C', 'Per Kenya MOH management of severe anaemia in pregnancy (Hb <5 g/dl), transfuse packed/red cells slowly under cover of a diuretic such as furosemide to avoid circulatory overload and heart failure. Whole blood without a diuretic (B) risks overload, total-dose iron infusion (A) and oral haematinics (D) act far too slowly to correct life-threatening anaemia, so C is correct.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A diagnosis of gestational diabetes is made is:', 'A. If fasting blood sugar is less than 7mmols/Litre.', 'B. Random blood sugar is less than 11mmols/Litre.', 'C. During a glucoses tolerance test, blood sugar at 2 hours is less than 11mmols/Litre.', 'D. During a glucose tolerance test, blood sugar at 2 hour is more than 11mmols/Litre.', 'D', 'Per WHO/MOH OGTT criteria, gestational diabetes is diagnosed by a raised glucose value, and only option D describes an elevated result (2-hour OGTT more than 11 mmol/L). Options A, B and C all state values that are below the thresholds and therefore normal. Note the item is imperfect because current WHO 2-hour diagnostic cut-off for GDM is >=8.5 mmol/L (>=11.1 is overt diabetes), but among the choices given D is the only one describing a diagnostic (raised) value.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following statements best describes the complete breech:', 'A. The hips are flexed and the legs are extended on the abdomen.', 'B. The hips and knees are flexed and feet are tucked besides the buttocks.', 'C. The hips and legs are not fully flexed, the feet are lower than the buttocks.', 'D. Hips are extended, knees are flexed.', 'B', 'Per Myles, in a complete (flexed) breech both hips and knees are flexed so the feet are tucked beside the buttocks. Option A (hips flexed, legs extended on abdomen) is the frank breech, option C (feet lower than buttocks, not fully flexed) is a footling/incomplete breech, and D describes a knee presentation; only B fits the complete breech.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following investigations should be carried out on a baby born of a rhesus negative woman:', 'A. Blood for culture & sensitivity, haemoglobin, indirect coombs test, full blood count.', 'B. Peripheral blood smear, serum bilirubin, indirect coombs test, white blood cell count.', 'C. Direct coombs test, rhesus factor, haemoglobin, serum bilirubin.', 'D. Blood group, rhesus factor, indirect coombs test, peripheral blood film.', 'C', 'Per Myles/MOH care of the baby of a Rh-negative mother (risk of haemolytic disease of the newborn), the relevant neonatal investigations are the baby''s blood group and rhesus factor, a DIRECT Coombs test (detects maternal antibody already bound to the baby''s red cells), haemoglobin and serum bilirubin to gauge haemolysis. Options A, B and D specify the INDIRECT Coombs, which tests free serum antibody (maternal side) and is not the correct neonatal test, so C is correct.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('On 1st examination, new born baby is found to have an inwardly rotated arm, extended elbow, flexed wrist and a partially closed hand. What is the likely diagnosis?', 'A. Klumpke palsy.', 'B. Fracture of clavicle.', 'C. Total brachial plexus palsy.', 'D. Erb''s palsy.', 'D', 'Per Myles/Kenya Basic Paediatric Protocols, Erb''s palsy from upper brachial plexus (C5-C6) injury gives the classic ''waiter''s tip'' posture: arm adducted and internally (inwardly) rotated, extended elbow, pronated forearm, flexed wrist and partially closed hand. Klumpke''s palsy affects the lower plexus (C8-T1) giving a claw hand, total brachial plexus palsy produces a completely flaccid arm, and clavicle fracture causes pseudo-paralysis with crepitus rather than this fixed posture.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which degree of placenta praevia involves the lower uterine segment but does not extend to the margin of internal cervical OS:', 'A. Type 2.', 'B. Type 4.', 'C. Type 3.', 'D. Type 1.', 'D', 'Per Myles classification of placenta praevia, Type 1 (lateral/low-lying) means the placenta dips into the lower uterine segment but does not reach the internal cervical os. Type 2 (marginal) reaches the os edge, Type 3 partially covers it, and Type 4 (complete/central) covers it fully; only Type 1 does not extend to the margin of the os.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following include effects of hydramnios:', 'A. Postpartum hemorrhage, cord prolapse, prolonged pregnancy, placenta abruption.', 'B. Placenta praevia, preterm prelabour, rupture of membranes, maternal obstetric obstruction, unstable lie.', 'C. Placenta abruption, postdatism, unstable lie, post partum hemorrhage.', 'D. Cord prolapse, preterm labour, postpartum hemorrhage, prelabour rupture of membranes.', 'D', 'Per Myles, polyhydramnios overdistends the uterus and predisposes to unstable/abnormal lie, cord prolapse, preterm labour, prelabour rupture of membranes and postpartum haemorrhage from poor uterine retraction. Option D lists cord prolapse, preterm labour, PPH and PROM correctly, whereas A, B and C incorrectly add placenta praevia, placental abruption or postdatism, which are not direct effects of hydramnios.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following statements describes a frank breech:', 'A. The hips and knees are flexed and the feet is tricked besides the buttocks.', 'B. The hips and the legs are not fully flexed and the feet are lower than the buttocks.', 'C. The hips are flexed and the legs are extended on the abdomen.', 'D. Hips are extended, knees are flexed.', 'C', 'Per Myles, a frank (extended) breech has the hips flexed and the legs extended up over the abdomen so the feet lie near the head; it is the commonest and most favourable breech. Option A (feet tucked beside buttocks) is a complete breech, B (feet lower than buttocks) a footling, and D (hips extended, knees flexed) a knee presentation; only C describes a frank breech.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In assisted breech delivery, when the head is well flexed, which manoeuvre that a midwife should apply the head:', 'A. Loveset.', 'B. Mauricean smellie veit.', 'C. Popliteal fossa press.', 'D. Burns Marshall.', 'D', 'Per Myles assisted breech delivery, when the after-coming head is well flexed the Burns Marshall manoeuvre delivers it by grasping the ankles and applying controlled traction/extension over the perineum. Mauriceau-Smellie-Veit is used chiefly to promote flexion and jaw/shoulder traction when the head is deflexed or delivery is difficult, Lovset''s manoeuvre delivers extended arms, and ''popliteal fossa press'' is a distractor; hence D is correct.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The best option of family planning for breastfeeding mothers is:', 'A. Combined oral contraceptives, barrier method.', 'B. Progesterone only pills, barrier method.', 'C. Non-hormonal IUCD, barrier method.', 'D. Implants, barrier method.', 'B', 'Per Kenya MOH/WHO family planning guidelines, progesterone-only pills do not reduce milk supply and, paired with a barrier method, are a preferred option for breastfeeding mothers. Combined oral contraceptives (A) contain oestrogen which diminishes milk production and are avoided; while the non-hormonal IUCD and implants are also acceptable, the item asks for the ''best'' pill/hormonal choice for lactation, which is the progesterone-only method.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Emergency contraceptives can be used in the following situations:', 'A. Coerced sexual intercourse, broken condoms.', 'B. Regular family planning method, broken condoms.', 'C. Pregnancy, coerced sexual intercourse.', 'D. Misplaced IUCD, pregnancy.', 'A', 'Per Kenya MOH/WHO FP guidelines, emergency contraception is indicated after unprotected or inadequately protected intercourse, including coerced sex/rape and condom breakage. It must not be used as a regular ongoing method (B) and is not used in an established pregnancy (C, D), so A is the only fully correct indication set.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Partially breastfeeding mother and child receiving much of other drinks, the best time to start depo-provera injectable is:', 'A. 6 weeks after child birth.', 'B. 6 months after child birth.', 'C. Within 7 days after child birth.', 'D. Any time she is certain that there is no pregnancy.', 'A', 'Per Kenya MOH/WHO FP guidelines, in a partially breastfeeding woman DMPA (Depo-Provera) can be initiated from about 6 weeks postpartum, balancing effective contraception against progestogen exposure in early lactation. Starting within 7 days (C) is too early for a breastfeeding mother, waiting to 6 months (B) leaves her unprotected too long, and ''any time no pregnancy is certain'' (D) ignores the postpartum/lactation timing rule.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following statements about screening for syphilis in pregnancy are correct except?', 'A. It should be carried out on all pregnant women.', 'B. It does not require a pelvic exam.', 'C. It is costly and should therefore only be carried out on women at high risk.', 'D. It should result in fewer stillbirth weight babies.', 'C', 'Per Kenya MOH ANC/PMTCT guidance, syphilis screening (RPR/VDRL or rapid test) is a cheap test offered UNIVERSALLY to all pregnant women, does not require a pelvic examination, and reduces stillbirths and congenital syphilis. The false statement being sought by this ''except'' stem is C, which wrongly claims the test is costly and should be limited to high-risk women; A, B and D are all true statements.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The term Hegar''s Sign is used to refer to:', 'A. Pulsation of fornices.', 'B. Bluish violet discouration of the virginal walls.', 'C. Softening of the lower uterine segment.', 'D. Cessation of menstruation.', 'C', 'Per Myles, Hegar''s sign is softening and compressibility of the lower uterine segment/isthmus felt on bimanual examination at about 6-12 weeks, a probable sign of pregnancy. Bluish-violet discolouration of the vaginal walls is Chadwick''s/Jacquemier''s sign, pulsation of the fornices is Osiander''s sign, and cessation of menstruation is amenorrhoea; only softening of the lower segment defines Hegar''s sign.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The uterine support that maintains anteverted position of the uterus as referred to as:', 'A. Uterosacral ligaments.', 'B. Broad ligaments.', 'C. Round ligaments.', 'D. Transverse cervical ligaments.', 'C', 'Per Myles Textbook for Midwives, the round ligaments run from the uterine cornua through the inguinal canal to the labia majora and pull the fundus forward, maintaining the anteverted/anteflexed position of the uterus. The uterosacral and transverse cervical (cardinal) ligaments provide posterior/lateral cervical support rather than anteversion, and the broad ligaments are peritoneal folds that merely drape the uterus without active support.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following statements best describes the obstetric conjugate of the pelvic brim', 'A. A line from the sacral promontory taken to the upper most point of the upper border of the symphysis pubis.', 'B. A line from the sacral promontory taken to the posterior border of the upper surface of the symphysis pubis.', 'C. A line taken from the sacral promontory to the lower border of the symphysis pubis.', 'D. An anteroposterior diameter of the pelvic brim.', 'B', 'Per Myles Textbook for Midwives, the obstetric conjugate is measured from the sacral promontory to the posterior (inner) border of the upper surface of the symphysis pubis (~11 cm) and is the shortest fixed antero-posterior diameter the fetal head must negotiate at the brim. Option A (uppermost point of the border) describes the true/anatomical conjugate; option C (to the lower border) is the diagonal conjugate; option D is too vague as several AP diameters exist at the brim.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which statement best describes the velamentous cord insertion:', 'A. The cord is attached to the edge of the placenta.', 'B. The cord is inserted on the membranes.', 'C. Double chorion and double amnion.', 'D. An extra lobe.', 'B', 'Per Myles Textbook for Midwives, in velamentous cord insertion the umbilical cord is inserted into the membranes at a distance from the placenta, with the vessels running unprotected between amnion and chorion before reaching the placental edge (predisposing to vasa praevia/haemorrhage). Insertion at the placental edge is battledore (option A); double chorion/amnion (C) describes dichorionic-diamniotic twinning; an extra lobe (D) is a succenturiate lobe.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('After alteration of the fetal circulation, which temporarily structure becomes ligamentum arteriosus?', 'A. Umbilical vein.', 'B. Ductus arteriosus.', 'C. Ductus venosus.', 'D. Foramen ovale.', 'B', 'Per Myles Textbook for Midwives, the ductus arteriosus (which shunts blood from the pulmonary artery to the aorta in fetal life) constricts after birth and fibroses into the ligamentum arteriosum. The umbilical vein becomes the ligamentum teres; the ductus venosus becomes the ligamentum venosum; and the foramen ovale closes to form the fossa ovalis, so options A, C and D are wrong.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following include features of a gynaecological pelvis:', 'A. Kidney shaped brim, narrow forepelvis convergent side walls, subpubic arch of less 90%.', 'B. Rounded brim, generous forepelvis, blunt ischial spines, subpubic arch of 90%.', 'C. Rounded brim, divergent sideways, blunt ischial spines, subpubic arch more than 90%.', 'D. Heart shaped brim, wide fore pelvis, blunt ischial spines, convergent side walls.', 'B', 'Per Myles Textbook for Midwives, the gynaecoid (ideal female) pelvis has a rounded brim, generous forepelvis, straight side walls, blunt ischial spines and a sub-pubic arch of about 90 degrees. Option A (kidney-shaped brim, narrow forepelvis, convergent walls, arch <90 degrees) describes the android pelvis; option C''s arch of more than 90 degrees fits the platypelloid/anthropoid pattern; option D''s heart-shaped brim with convergent walls again describes the android pelvis.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('During antenatal care the midwife teaches the woman on the following major risk factors:', 'A. Heart burn, constipation, vaginal bleeding.', 'B. Vaginal bleeding, severe headache, baby moving less.', 'C. Laboured breathing, abdominal pains, frequency in micturition.', 'D. Fainting, muscle cramps, feeling very tired.', 'B', 'Per Kenya MOH antenatal danger-sign counselling (and Myles), the woman is taught to report vaginal bleeding, severe headache/visual disturbance (pre-eclampsia) and reduced fetal movements as major warning signs requiring urgent review. Heartburn, constipation, muscle cramps and mild tiredness (options A, C, D) are minor discomforts of pregnancy, not danger signs.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In physiological changes in pregnancy, which term is used to refer to pulsation of the fornices:', 'A. Chadwick''s sign.', 'B. Hegar''s sign.', 'C. Osiander''s sign.', 'D. Braxton hicks.', 'C', 'Per Myles Textbook for Midwives, Osiander''s sign is the increased pulsation felt in the lateral vaginal fornices in early pregnancy owing to raised pelvic vascularity. Chadwick''s sign (A) is the bluish/violet discolouration of the vagina and cervix; Hegar''s sign (B) is softening/compressibility of the isthmus; Braxton Hicks (D) are intermittent painless uterine contractions.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The relationship between the fetal head and limbs with its trunk is known as:', 'A. Attitude.', 'B. Flexion.', 'C. Lie.', 'D. Position.', 'A', 'Per Myles Textbook for Midwives, attitude is the relationship of the fetal head and limbs to its trunk (the degree of flexion or extension). Lie (C) is the relationship of the long axis of the fetus to the long axis of the uterus; position (D) is the relationship of the denominator to the maternal pelvis; and flexion (B) is only one component of attitude, not the defining term.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which reflex is elicited by stroking the sides of the baby''s mouth and cheek causing the baby to turn towards the source of stimuli and open its mouth?', 'A. Moro reflex.', 'B. Suckling reflex.', 'C. Rooting reflex.', 'D. Traction reflex.', 'C', 'Per Myles Textbook for Midwives, stroking the cheek or corner of the mouth makes the newborn turn its head towards the stimulus and open the mouth to seek the nipple, the rooting reflex. The Moro reflex (A) is a startle/embrace response to sudden movement; the suckling reflex (B) is triggered once an object is placed in the mouth; the traction/grasp reflex (D) involves gripping on stimulation of the palm.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The term chloasma is best described as:', 'A. Stretching of the collagen layer of the skin.', 'B. Reddening of the palms.', 'C. Minute red elevations in the skin.', 'D. Pigmentation of the face causing a facial mask.', 'D', 'Per Myles Textbook for Midwives, chloasma (melasma, the ''mask of pregnancy'') is increased melanin pigmentation over the face (forehead, cheeks, upper lip) driven by raised oestrogen and MSH. Stretching of the collagen/skin (A) produces striae gravidarum, reddening of the palms (B) is palmar erythema, and minute red skin elevations (C) describe spider naevi.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When performing examination of the placenta; a midwife finds an extra lobe, which term is used to refer to this anatomical variation?', 'A. Circumvallate.', 'B. Succenturiate.', 'C. Battledore.', 'D. Velamentous.', 'B', 'Per Myles Textbook for Midwives, a succenturiate lobe is an accessory placental lobe joined to the main placenta by blood vessels running through the membranes; if retained it is a major cause of postpartum haemorrhage and infection. Circumvallate (A) is a raised opaque ring on the fetal surface, battledore (C) is marginal cord insertion, and velamentous (D) is insertion of the cord into the membranes.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A midwife should perform Barlow''s test on a new born to rule out congenital abnormality of the:', 'A. Hip joint.', 'B. Shoulder joint.', 'C. Ankle joint.', 'D. Knee joint.', 'A', 'Per Myles Textbook for Midwives and the Kenya Basic Paediatric Protocols, Barlow''s test (with the complementary Ortolani''s test) is performed on the newborn hip to detect developmental dysplasia/congenital dislocation of the hip: Barlow''s attempts to dislocate an unstable hip while Ortolani''s relocates it. It does not assess the shoulder, ankle or knee (options B, C, D).', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('One of the following includes hormones that are produced by the placenta:', 'A. Human chorionic gonadotrophic hormone, oestrogen, progesterone, follicle stimulating hormone.', 'B. Luteinizing hormone, prolactin, oxytocin, oestrogen.', 'C. Human placental lactogen. Progesterone, oestrogen, human chorionic gonadotrophic hormone.', 'D. Follicle stimulating hormone, luteinizing hormone, prolactin, oestrogen.', 'C', 'Per Myles Textbook for Midwives, the placenta produces human placental lactogen (hPL), progesterone, oestrogen and human chorionic gonadotrophin (hCG), all listed in option C. Follicle-stimulating hormone and luteinizing hormone are anterior-pituitary gonadotrophins (excluding A and D), and oxytocin/prolactin (B) are pituitary hormones, not placental products.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which reproductive tract infection is characterized by a whitish curdy-like vaginal discharge:', 'A. Bacterial vaginosis.', 'B. Vulvavaginal candidiasis.', 'C. Chlamydia.', 'D. Trichomoniasis.', 'B', 'Per the Kenya National RH/STI guidelines, vulvovaginal candidiasis presents with a thick, white, curdy (cottage-cheese) discharge with vulval itching and non-offensive odour. Bacterial vaginosis (A) causes a thin homogeneous grey discharge with a fishy odour, chlamydia (C) is often asymptomatic or gives mucopurulent cervicitis, and trichomoniasis (D) produces a frothy greenish-yellow offensive discharge.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In which congenital abnormality is there a defect on the abdominal wall through which the intestines protrude?', 'A. Omphalocele.', 'B. Exomphalos.', 'C. Gastroschisis.', 'D. Diaphragmatic hernia.', 'C', 'Per Myles Textbook for Midwives and the Kenya Basic Paediatric Protocols, gastroschisis is a full-thickness paraumbilical abdominal wall defect through which uncovered bowel protrudes with no covering sac. In omphalocele/exomphalos (options A and B are the same lesion) the herniated viscera are covered by a peritoneal-amniotic sac at the umbilicus, and a diaphragmatic hernia (D) involves abdominal contents entering the thorax, not protruding through the abdominal wall.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A preterm baby is one:', 'A. Born before 37 completed weeks.', 'B. Whose weight is small for gestational age.', 'C. Whose weight is appropriate for gestational age.', 'D. Whose birth weight is below 2500gm regardless of gestation.', 'A', 'Per the WHO/Myles definition adopted in Kenya, a preterm baby is one born before 37 completed weeks of gestation, regardless of birth weight. Small- or appropriate-for-gestational-age (B, C) refers to weight-for-age classification, and a birth weight below 2500 g (D) defines low birth weight, which is a separate category from prematurity.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('One of the following include the correct intervention for a woman who has cardiac disease in pregnancy:', 'A. Administer tocolytics if the woman goes into labour.', 'B. Perform caesarean section to all women with cardiac diseases in pregnancy.', 'C. Administer Intravenous fluids in the intrapartum period.', 'D. Avoid use of ergometrine in active management third stage of labour and use of syntocinon instead.', 'D', 'Per Myles Textbook for Midwives, in cardiac disease ergometrine is avoided in active management of the third stage because it causes a sudden rise in venous return and afterload that can precipitate pulmonary oedema; oxytocin (syntocinon) given slowly is preferred. Tocolytics are not indicated routinely (A), caesarean is not required for all cardiac patients as vaginal birth with a short second stage is generally safer (B), and large IV fluid loads (C) risk fluid overload in the compromised heart.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following include effects of hydramnious:', 'A. Post partum haemorrhage, cord prolapse, prolonged pregnancy, placenta abruptio.', 'B. Placenta abruptio, maternal ureteric obstruction, unstable lie, post partum haemorrhage.', 'C. Cord prolapse, preterm prelabour, rupture of membranes, preterm labour, prolonged pregnancy.', 'D. Placenta praevia, unstable lie, placenta abruptio, hypertensive disorders.', 'B', 'Per Myles Textbook for Midwives, polyhydramnios over-distends the uterus, causing maternal pressure symptoms (dyspnoea, oedema, ureteric obstruction), unstable lie, an increased risk of abruption on sudden decompression, and atonic postpartum haemorrhage, all captured in option B. Prolonged/post-term pregnancy (in A and C) and placenta praevia (in D) are not effects of hydramnios, so those options are incorrect.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The immediate effects of hyperemesis gravidarum include:', 'A. Electrolyte imbalance, anaemia, ketosis.', 'B. Dehydration, ketosis, anaemia.', 'C. Anaemia, electrolyte imbalance, dehydration.', 'D. Dehydration, electrolyte imbalance, ketosis.', 'D', 'Per Myles Textbook for Midwives, persistent severe vomiting in hyperemesis gravidarum causes the immediate triad of dehydration, electrolyte imbalance (hypokalaemia, hyponatraemia) and ketosis from starvation. Anaemia is a later consequence of prolonged poor intake, so every option that lists anaemia (A, B, C) is wrong; only D contains the three immediate effects.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following precaution should be observed before administering the nest dose of magnesium sulphate to a preclamptic woman:', 'A. Urine output is 80mls in the last four hours.', 'B. Respiratory rate is less than 16 breaths per minute.', 'C. Blood pressure is 140/90mmHg or more.', 'D. Deep tendon reflexes are present and normal.', 'D', 'Per the Kenya MOH pre-eclampsia/eclampsia protocol (and Myles), before each maintenance dose of magnesium sulphate the midwife must confirm that deep tendon (patellar) reflexes are present, respiratory rate is at least 16/min, and urine output is at least 30 ml/hr (100 ml/4 hr). Absent reflexes, a respiratory rate below 16 (B), or low urine output signal magnesium toxicity and contraindicate the dose; a BP of 140/90 or more (C) is not a safety check for magnesium administration, and 80 ml over 4 hours (A) is actually below the safe threshold.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In shoulder dystocia, the manoeuvre in which the midwife pushes the posterior shoulder in the direction of the fetal chest to rotate the anterior shoulder is referred to as:', 'A. Woods screw.', 'B. Zavanelli.', 'C. Rubins.', 'D. Mac Roberts.', 'C', 'Per Myles Textbook for Midwives, the Rubin manoeuvre in shoulder dystocia involves pushing the posterior aspect of the most accessible shoulder towards the fetal chest to adduct the shoulders and reduce the bisacromial diameter. The Woods (corkscrew) manoeuvre (A) rotates the posterior shoulder in the opposite direction across the front of the chest, Zavanelli (B) is cephalic replacement, and McRoberts (D) is hyperflexion of the maternal hips onto the abdomen.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Key elements assessed prior to prescribing prostaglandins for induction of labour are:', 'A. Lie of the baby, dilatation of the cervix, effacement of the cervix, station of the presenting part, position of the cervix.', 'B. Lie of the baby, amniotomy, position of the cervix, effacement of the cervix, willingness of the mother.', 'C. Amniotomy, dilatation of the cervix, position of the baby, consistency of the cervix station of presenting part.', 'D. Station of presenting part, effacement of the cervix, position of the cervix, dilation of the cervix, consistency of the cervix.', 'D', 'Per Myles Textbook for Midwives, cervical favourability before prostaglandin induction is assessed by the Bishop score components: dilatation, effacement, consistency and position of the cervix, plus station of the presenting part, exactly the five elements in option D. Amniotomy (in B and C) is an intervention, not an assessment, and lie of the baby (in A and B) is not a Bishop score component, so those options are wrong.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following landmarks are assessed by the midwife during digital pelvimetry:', 'A. Intertuberous diameter, ischial spines, sub-pubic arch.', 'B. Sacral promontory, symphysis pubis, sciatic notch.', 'C. Intertuberous diameter, pelvic brim, sacral promontory.', 'D. Pubic arch, sciatic notch, hollow of the sacrum.', 'D', 'Per Myles Textbook for Midwives, clinical (digital) pelvimetry assesses the sub-pubic arch, the sacro-sciatic notch, the hollow/curve of the sacrum, the ischial spines and reachability of the sacral promontory, all internally palpable landmarks as listed in option D. The intertuberous (bituberous) diameter cited in options A and C is measured externally, and the pelvic brim in C is not directly palpable digitally, so those options are less correct.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Trisomy 13 results into:', 'A. Edwards syndrome.', 'B. Down syndrome.', 'C. Patau syndrome.', 'D. Sheehan syndrome.', 'C', 'Per standard genetics (and Myles), trisomy 13 is Patau syndrome (holoprosencephaly, cleft lip/palate, polydactyly, cardiac defects). Trisomy 18 is Edwards syndrome (A), trisomy 21 is Down syndrome (B), and Sheehan syndrome (D) is postpartum pituitary necrosis from severe haemorrhage, unrelated to any trisomy.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The classical presentation of acutepyelonephritis include:', 'A. Fever cost-vertebral angle pain, nausea and vomiting.', 'B. Fever, diarrhoea and vomiting.', 'C. Flank pain, dysuria and frequency.', 'D. Cost-vertebral angle pain, pyuria, leucocytosis.', 'A', 'Per Brunner & Suddarth''s, acute pyelonephritis classically presents with fever/chills, costovertebral-angle (flank) pain and tenderness, and nausea and vomiting, often accompanied by lower-tract symptoms, matching option A. Fever with diarrhoea and vomiting (B) suggests gastroenteritis; flank pain with dysuria and frequency alone (C) is incomplete; and pyuria/leucocytosis (D) are laboratory findings rather than the classical clinical presentation.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The most common form of bladder cancer is:', 'A. Transitional cell bladder cancer.', 'B. Renal cell carcinoma.', 'C. Papillary cancer.', 'D. Carcinoma in situ.', 'A', 'Per Brunner & Suddarth''s, transitional cell (urothelial) carcinoma is by far the most common histological type of bladder cancer. Renal cell carcinoma (B) is a kidney tumour, not bladder; papillary lesions (C) are a morphological subtype/growth pattern of urothelial cancer rather than the most common type overall; and carcinoma in situ (D) is a flat high-grade non-invasive lesion, not the commonest bladder cancer.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Hypospadia is:', 'A. Congenital anomaly of the penile shaft where by the urethra orifice is located below the penile shaft.', 'B. Congenital of the penile shaft whereby the urethra orifice is situated above the penile shaft.', 'C. A situation whereby there is absence of urethra orifice.', 'D. Congenital absence of the testis.', 'A', 'Per Brunner & Suddarth''s/paediatric surgery, hypospadias is a congenital anomaly in which the urethral meatus opens on the ventral (under/below) surface of the penile shaft. An opening on the dorsal (upper) surface is epispadias (B), absence of the urethral opening (C) is not the definition, and congenital absence of the testis (D) is anorchia, so those options are wrong.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which uterine support has ovarian vessels is?', 'A. Transverse cervical ligament', 'B. Ovarian ligament', 'C. Broad ligament', 'D. Round ligament', 'C', 'Per Myles Textbook for Midwives, the ovarian (gonadal) vessels reach the ovary within the suspensory ligament (infundibulopelvic ligament), which is the upper lateral extension of the broad ligament; of the options offered the broad ligament is therefore the uterine support that conveys the ovarian vessels. The transverse cervical (cardinal) ligament (A) carries the uterine vessels, while the ovarian ligament (B) and round ligament (D) are fibromuscular cords that do not transmit the ovarian vessels.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In the 3rd degree of inversion of the uterus:', 'A. The fundus reaches outside the vagina.', 'B. The cervix uterus and vagina are inverted and visible.', 'C. The external os is turned upside down.', 'D. The body of the uterus is inverted into the internal os.', 'A', 'Per Myles Textbook for Midwives, third-degree (complete) uterine inversion is total inversion in which the whole uterus, including the fundus, is turned inside out and protrudes outside the vagina. First-degree inversion is confined within the uterine cavity, and second-degree passes through the cervix into the vagina without appearing at the vulva, so options B, C and D do not describe the third degree.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The recommended time to give BCG vaccination to a baby born to a mother with infectious tuberculosis is:', 'A. Immediately after birth.', 'B. After the baby has used isoniazid for prophylaxis.', 'C. Anytime the midwife comes into contact with the baby.', 'D. After one year the baby will be born with acquired immunity.', 'B', 'Per Kenya National TB (NLTP) guidance, a baby born to a mother with infectious TB is given isoniazid preventive therapy first and BCG is delayed until the INH prophylaxis is completed, because isoniazid inhibits the live BCG organism and would neutralise an immediately given vaccine (making option A wrong). Vaccinating at any chance contact (C) is not protocol, and a newborn is not born with acquired immunity to TB (D).', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The effects of multiple gestation in the mother include:', 'A. Anaemia, polyhydramnios, twin to twin transfusion', 'B. Pressure symptoms, anaemia, polyhydramnios.', 'C. Locked twins, cord prolapse, obstructed labour.', 'D. Prolonged labour, pressure symptoms, Low birth weight', 'B', 'Per Myles Textbook for Midwives, maternal effects of multiple pregnancy include pressure symptoms from the over-distended uterus (dyspnoea, oedema, varicosities), anaemia from increased iron and folate demand, and polyhydramnios, all listed in option B. Twin-to-twin transfusion (A), locked twins and cord prolapse (C), and low birth weight (D) are fetal or intrapartum complications, not maternal effects, so those options are incorrect.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Vaginal examination is indicated after rupture of membranes mainly to:', 'A. Assess progress or delay in labour.', 'B. Determine the presentation in case of doubt.', 'C. Confirm full dilatation of cervix.', 'D. To exclude cord prolapse.', 'D', 'Per Myles Textbook for Midwives, a vaginal examination after rupture of the membranes is performed chiefly to exclude cord prolapse (and cord presentation), particularly when the presenting part is high or ill-fitting, because a prolapsed cord is an obstetric emergency. Assessing progress or delay (A), determining presentation (B) and confirming full dilatation (C) are routine reasons for VE, not the specific main indication triggered by ruptured membranes.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Mechanical factors involved in physiology of first stage of labour are:', 'A. General fluid pressure, formation of retraction ring, rupture of membranes.', 'B. Rupture of membranes, formation of fore waters, general fluid pressure.', 'C. Formation of fore waters , polarity, contraction and retraction ring.', 'D. Rupture of membranes, cervical effacement, formation of retraction ring.', 'B', 'Per Myles Textbook for Midwives, the mechanical factors operating in the first stage of labour are the formation of the forewaters, general fluid pressure, and finally rupture of the membranes, exactly the trio in option B. Polarity, contraction and retraction, and formation of the retraction ring (in options A, C, D) are muscular (uterine action) factors, not mechanical, so those options are wrong.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When the occiput is on the left sacro iliac joint and the sinciput is on the right illiopectineal eminence, what is the position :', 'A. Lift occipito-anterior.', 'B. Right occipito-posterior.', 'C. Right occipito-anterior.', 'D. Left occipito-posterior.', 'D', 'Per Myles Textbook for Midwives, the denominator in a vertex presentation is the occiput; when the occiput lies against the mother''s LEFT sacro-iliac joint it is directed both posteriorly and to the left, defining the Left Occipito-Posterior (LOP) position, with the sinciput correspondingly at the right ilio-pectineal eminence, matching the stem exactly. A Right OP (B) would place the occiput at the right sacro-iliac joint, and the anterior positions (A and C) would place the occiput near the ilio-pectineal eminence, so they are wrong.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following methods can be used to diagnose cephalopelvic disproportion:', 'A. X-ray pelvimetry.', 'B. Speculum vaginal examination.', 'C. Ultrasound scanning.', 'D. External cephalic version.', 'A', 'Per Myles Textbook for Midwives, cephalopelvic disproportion is objectively assessed by X-ray (radiographic) pelvimetry, which measures the pelvic diameters and relates them to the fetal head size. A speculum examination (B) inspects the cervix/vagina and does not measure the pelvis, ultrasound (C) chiefly assesses the fetus rather than reliably diagnosing bony CPD, and external cephalic version (D) is a treatment for malpresentation, not a diagnostic test.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Microorganisms that can cross the placental barrier and affect the fetus include:', 'A. Chlamydia trachomatis, Neisseria gonorrhoea.', 'B. Treponema pallidum, chlamydia trachomatis.', 'C. Tubercle bacillus, Neisseria gonorrhoea.', 'D. Treponema pallidum, tubercle bacillus.', 'D', 'Per Myles/Kenya RH guidelines, Treponema pallidum (congenital syphilis) and the tubercle bacillus (congenital TB) can cross the placental barrier to infect the fetus in utero, as in option D. Chlamydia trachomatis and Neisseria gonorrhoeae (in options A, B, C) are typically acquired by the neonate during passage through an infected birth canal (causing ophthalmia neonatorum), not transplacentally.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A pregnant woman with cardiac disease grade III will present with:', 'A. Symptoms during mild physical activity.', 'B. No symptoms during ordinary physical activity.', 'C. Symptoms at rest.', 'D. Symptoms during less ordinary physical activity.', 'A', 'Per the NYHA functional classification used in Myles, Grade III cardiac disease means marked limitation of activity: the woman is comfortable at rest but symptomatic on less-than-ordinary (mild) physical activity, matching option A. Symptoms at rest (C) define Grade IV, no symptoms on ordinary activity (B) is Grade I, and option D is essentially a restatement of Grade III, making A the clearest single best answer.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Obstetric indications for induction of labour include:', 'A. Intrauterine fetal demise, prolonged pregnancy.', 'B. Intrauterine growth restriction, intrauterine fetal death.', 'C. Unstable lie, prolonged pregnancy.', 'D. Unstable lie, intrauterine growth restriction.', 'A', 'Per Myles/Kenya maternal-newborn guidelines, recognised obstetric indications for induction of labour include intrauterine fetal death/demise and prolonged (post-term) pregnancy, both listed in option A. Unstable lie (in options C and D) is a contraindication to induction because of cord-prolapse risk; intrauterine growth restriction (B and D) may prompt delivery but the pairing with unstable lie/IUFD makes A the fully correct combination.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In a baby born of thick meconium stained liquor and does not initiate breathing, the first step the midwife must take is:', 'A. Dry and stimulate.', 'B. Inflate five rescue breaths.', 'C. Administer oxygen by mask.', 'D. Oropharyngeal suctioning.', 'D', 'In the classic Myles/older Kenya neonatal resuscitation teaching for a NON-vigorous baby born through THICK meconium-stained liquor who does not breathe, clearing the airway by oropharyngeal (mouth then nose) suctioning is taught as the first step before positive-pressure ventilation, making D the intended answer. Drying/stimulation (A) is the universal first step for a clear-liquor baby but is de-emphasised here because meconium in the airway must be cleared; inflation breaths (B) and oxygen by mask (C) come only after the airway is patent.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following factors cause neonatal jaundice by interfering with transportation of bilirubin:', 'A. Reduced gastric motility.', 'B. Reduced albumin binding capacity.', 'C. Increased beta glucuronidase enzyme.', 'D. Hypoxia, hypothermia, hypoglycaemia.', 'B', 'Per Myles Textbook for Midwives and Basic Paediatric Protocols, unconjugated bilirubin is transported in blood bound to albumin, so a reduced albumin binding capacity impairs bilirubin TRANSPORT and raises free bilirubin, contributing to neonatal jaundice (B). Increased beta-glucuronidase (C) and reduced gastric motility (A) increase enterohepatic RE-circulation, not transport; hypoxia/hypothermia/hypoglycaemia (D) displace bilirubin but the question specifically asks about interference with transport, which is the albumin mechanism.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following factors predisposes to amniotic fluid embolism:', 'A. Spontaneous rupture of membranes.', 'B. Vaginal delivery.', 'C. Caesarean section.', 'D. Bimanual compression of the uterus.', 'C', 'Per Myles Textbook for Midwives, amniotic fluid embolism is predisposed by conditions allowing amniotic fluid to breach the maternal circulation, including caesarean section/operative delivery (C), tumultuous or induced labour, advanced maternal age, multiparity and abruption. Spontaneous rupture of membranes (A), uncomplicated vaginal delivery (B) and bimanual uterine compression (D) are not recognised specific predisposing factors.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Trisomy 21 is characterized by:', 'A. Small head with flattened forehead.', 'B. Obliquely slanted eyes and a single palmar crease.', 'C. Receding chin and cleft palate.', 'D. Low set ears and multiple palmar crease.', 'B', 'Per Myles Textbook for Midwives and Basic Paediatric Protocols, Down syndrome (trisomy 21) is characterised by upward obliquely slanted (Mongoloid) palpebral fissures and a SINGLE transverse (simian) palmar crease (B), with flat facial profile and protruding tongue. Option D is wrong because it states MULTIPLE palmar creases; small flattened forehead (A) and receding chin/cleft palate (C) are not the classic trisomy-21 features.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('During caesarean section, vertical incision made on the abdominal wall below the umbilicus is referred to', 'A. Pfannesteil.', 'B. Lower uterine segment incision.', 'C. classical incision.', 'D. Sub umbilical midline incision.', 'D', 'Per Myles Textbook for Midwives, a vertical midline skin incision on the abdominal wall below the umbilicus is the sub-umbilical midline incision (D). Pfannenstiel (A) is a transverse suprapubic abdominal incision, while classical (C) and lower uterine segment (B) refer to incisions on the UTERUS, not the abdominal wall.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A pregnant woman with cardiac disease grade I will presents with:', 'A. Symptoms during mild physical activity.', 'B. No symptoms during ordinary physical activity.', 'C. Symptoms at rest.', 'D. Symptoms during ordinary physical activity.', 'B', 'Per the NYHA functional classification used in Myles Textbook for Midwives, Grade I cardiac disease means no limitation of activity, so ordinary physical activity causes no symptoms (B). Symptoms with ordinary activity (D) is Grade II-III, symptoms with mild/less-than-ordinary activity is Grade III, and symptoms at rest (C) is Grade IV.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('During labour the midwife discourages the woman from lying in supine position to prevent:', 'A. Obstructed labour, fetal compromise', 'B. Maternal hypotension, fetal compromise', 'C. Maternal hypotension, obstructed labour', 'D. Maternal hypertension, fetal compromise', 'B', 'Per Myles Textbook for Midwives, the supine position allows the gravid uterus to compress the inferior vena cava (aortocaval compression), reducing venous return and causing maternal hypotension with consequent fetal compromise (supine hypotensive syndrome) - answer B. The supine position does not cause obstructed labour or hypertension, excluding options A, C and D; a left-lateral tilt prevents the syndrome.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In which process does a new born baby loss heat through cold air current?', 'A. Conduction', 'B. Evaporation', 'C. Convection', 'D. Radiation', 'C', 'Per Myles Textbook for Midwives and Basic Paediatric Protocols on newborn thermoregulation, heat loss to moving/cold air currents around the baby occurs by convection (C). Conduction (A) is loss to a cold surface in direct contact, evaporation (B) is loss from wet skin, and radiation (D) is loss to nearby cold objects without contact.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In mechanism of labour, restitution refers to:', 'A. Correction of the twist on the fetal neck', 'B. Shoulders aligning with the wider pelvic diameter', 'C. Pressure on the fetal axis bring about flexion', 'D. Birth of the largest transverse diameter of the fetal head', 'A', 'Per Myles Textbook for Midwives, restitution is the slight untwisting of the fetal head that corrects the twist on the neck produced by internal rotation, realigning the head with the shoulders (A). Shoulders aligning with the wider pelvic diameter (B) is internal rotation of the shoulders, flexion from axis pressure (C) occurs in descent, and birth of the largest transverse diameter (D) is extension/crowning.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Moulding of the fetal head during labour is diagnosed when the midwife palpates:', 'Flat membranes surrounding the fetal head', 'Overlapping of skull bones', 'Bones of the vault. sutures and fontanelles', 'Features of the presenting part.', 'B', 'Per Myles Textbook for Midwives, moulding is diagnosed on vaginal examination by palpating OVERLAPPING of the fetal skull bones at the sutures as the head adapts to the maternal pelvis (B). Palpating sutures and fontanelles or bones of the vault alone (C) denotes no moulding, flat membranes (A) relates to the forewaters, and features of the presenting part (D) is a general finding.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following include definite indications of an episiotomy?', 'Fetal compromise, first delivery', 'Rigid perineum, first delivery', 'Previous 4th degree tear reconstruction, Previous pelvic floor surgery', 'Fetal compromise, HIV positive woman', 'C', 'Per Myles Textbook for Midwives, definite (absolute) indications for episiotomy are situations where perineal integrity must be actively protected, such as previous 4th-degree tear reconstruction or previous pelvic floor/perineal surgery (C). Fetal compromise, rigid perineum and first delivery (A, B) are relative indications, and HIV-positive status (D) is not itself an indication - routine episiotomy is in fact discouraged in HIV as it increases transmission risk.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following structures lie posteriorly to the uterus:', 'Utero vesical pouch and the bladder', 'Utero vesical pouch and the rectum', 'Recto uterine pouch and the rectum', 'Recto uterine pouch and the bladder', 'C', 'Per Myles Textbook for Midwives pelvic anatomy, the structures lying POSTERIOR to the uterus are the recto-uterine pouch (of Douglas) and the rectum (C). The utero-vesical pouch and the bladder (A) lie ANTERIOR to the uterus, so options containing the bladder or utero-vesical pouch posteriorly are incorrect.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The term Osiander''s sign is used to refer to:', 'Pulsation of fornices', 'Softening of the isthmus', 'Caesation of menstruation', 'Bluish violet discouration of vaginal walls', 'A', 'Per Myles Textbook for Midwives, Osiander''s sign is the increased arterial pulsation felt through the lateral vaginal fornices in early pregnancy due to increased pelvic blood supply (A). Softening of the isthmus (B) is Hegar''s sign, cessation of menstruation (C) is a presumptive sign, and bluish-violet discolouration of the vaginal walls (D) is Jacquemier''s/Chadwick''s sign.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The midwife should perform ortolani''s test on a newborn baby to rule out congenital abnormality of the:', 'Knee joint.', 'Shoulder joint.', 'Ankle joint.', 'Hip joint.', 'D', 'Per Myles Textbook for Midwives and neonatal examination guidelines, Ortolani''s test is performed on the newborn to detect developmental dysplasia/congenital dislocation of the HIP joint (D) by relocating a dislocated femoral head. It does not assess the knee, shoulder or ankle joints (A, B, C).', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following screening tests may be carried out by a midwife on a woman to diagnose preterm prelabour rupture of membranes (PPROM):', 'Initial and weekly full haemogram to rule out leucocytosis.', 'Perform obstetric ultrasound to determine the source of vaginal loss.', 'Undertaking digital vaginal examination to determine the integrity of the membranes.', 'Placing a vaginal pad over the vulva and examining it an hour later visually and by odour.', 'D', 'Per Myles Textbook for Midwives, PPROM is assessed by sterile speculum examination and a pad test - placing a vaginal pad over the vulva and inspecting it later visually and by odour for amniotic fluid (D). Digital vaginal examination (C) is CONTRAINDICATED as it introduces infection, while full haemogram (A) and ultrasound (B) do not directly confirm membrane rupture (ultrasound shows liquor volume but not the leak source).', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('One of the precautions that must be observed before administering the maintenance dose of magnesium sulphate in management of pre-eclampsia is:', 'Urine output is 80mls or less in the last four hours.', 'Respiratory rate of less than 16 breaths per minute.', 'Patella reflexes present and normal.', 'Blood pressure of 140/90 mmHg or more.', 'C', 'Per Kenya MOH/WHO pre-eclampsia and eclampsia guidelines, before each maintenance dose of magnesium sulphate the patellar (knee) reflexes must be PRESENT and normal (C), the respiratory rate must be at least 16/min, and urine output at least 100 mL over the preceding 4 hours. Absent reflexes, RR below 16 (B), or urine output of 80 mL or less in 4 hours (A) indicate toxicity and the dose must be withheld; blood pressure of 140/90 or more (D) is not a magnesium-toxicity precaution.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following include causes of oligohydramnios:', 'Esophageal atresia, open neural tube defects, chorioangioma.', 'Maternal diabetes, multiple gestation, rhesus isoimmunisation.', 'Renal agenesis, post term pregnancy, open neural tube defects.', 'Post term pregnancy, renal agenesis, preterm prelabour rupture of membranes.', 'D', 'Per Myles Textbook for Midwives, oligohydramnios results from reduced fetal urine output or fluid loss - post-term pregnancy (placental insufficiency), renal agenesis (Potter syndrome) and PPROM (D). Oesophageal atresia and open neural tube defects (A, C), and maternal diabetes, multiple gestation and rhesus isoimmunisation (B) cause POLYhydramnios, so those options are incorrect.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following include investigations that should be carried out on a baby born of a rhesus negative woman at birth?', 'Blood for culture sensitivity, haemoglobin, indirect coombs test, white blood cell count.', 'Peripheral blood smear, serum bilirubin, indirect coombs test, white blood cell count.', 'Direct coombs test, Rhesus factor, haemoglobin levels, serum bilirubin.', 'ABO blood group, peripheral blood smear, blood for culture and sensitivity, Rhesus factor.', 'C', 'Per Myles Textbook for Midwives, cord blood of a baby born to a Rhesus-negative mother is investigated for the baby''s Rhesus factor and ABO group, DIRECT Coombs test (to detect maternal antibodies coating the fetal red cells), haemoglobin (for anaemia) and serum bilirubin (for haemolytic disease of the newborn) - answer C. Options A and B are wrong because they list the INDIRECT Coombs test, which is performed on maternal serum, not on the neonate.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('While examining a pregnant woman at term the midwife elicits irregular uterine contractions lasting for 2 - 3 minutes with no cervical dilation. What is the possible diagnosis.', 'Preterm labour', 'True labour', 'Low abdominal pains', 'False Labour', 'D', 'Per Myles Textbook for Midwives, irregular contractions that do NOT produce progressive cervical dilatation (here, none) indicate false labour (Braxton Hicks contractions) - answer D. True labour (B) shows regular, intensifying contractions with progressive effacement and dilatation; preterm labour (A) would also produce cervical change, and ''low abdominal pains'' (C) is not a diagnosis.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Obstetric Risk factors to mother to child transmission of HIV include.', 'Sexually transmitted infections, unprotected sex, Vit A deficiency.', 'Preterm delivery, birth injuries, oral thrush.', 'Clinical stage of infection, high viral load, low maternal CD4 count.', 'Routine episiotomy, vaginal delivery, placental disruption.', 'C', 'Per the Kenya National PMTCT/HIV guidelines, the key maternal/obstetric determinants of mother-to-child HIV transmission are advanced clinical stage of infection, high maternal viral load and low CD4 count (C), with viral load the strongest predictor. Option D lists intrapartum factors (routine episiotomy, vaginal delivery, placental disruption) that modulate risk but are not the primary determinants; A and B list non-specific or unrelated factors.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('During breastfeeding, which one of the following is a sign of good attachment.', 'Baby''s body and head is in line', 'Baby''s chin touches the breast', 'Baby''s whole body is supported', 'There is more areola below baby''s bottom up than above baby''s top lip', 'B', 'Per Kenya MOH/WHO Baby-Friendly Hospital Initiative breastfeeding criteria, the four signs of good ATTACHMENT are chin touching the breast (B), mouth wide open, lower lip turned outward, and more areola visible above than below the mouth. Options A and C describe correct POSITIONING (not attachment), and option D reverses the areola sign (more areola should show ABOVE the top lip, not below the bottom lip), so it is incorrectly stated.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In fetal circulation the foramen ovale connects the:-', 'Right atrium to left atrium', 'Left atrium to right atrium', 'Umbilical vein to inferior vena cava', 'Pulmonary artery to aorta.', 'A', 'Per Myles Textbook for Midwives fetal circulation, the foramen ovale is an opening in the interatrial septum that shunts oxygenated blood from the RIGHT atrium to the LEFT atrium (A), bypassing the non-functional fetal lungs. The umbilical vein-to-IVC connection (C) is the ductus venosus and the pulmonary artery-to-aorta connection (D) is the ductus arteriosus.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which one of the following is a positive sign of pregnancy.', 'Presence of Human Gonadotrophic homone in urine.', 'Visible fetal movement per abdomen', 'Pulsation of the fornices', 'Bluish violet discoloration of the Vaginal walls.', 'B', 'Per Myles Textbook for Midwives, positive (absolute) signs of pregnancy require detection of the fetus itself - here, visible fetal movement per abdomen (B), fetal heart sounds, or ultrasound visualisation. HCG in urine (A) is a probable sign, and pulsation of the fornices (C, Osiander''s) and bluish vaginal discolouration (D, Jacquemier''s) are presumptive/probable signs only.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following includes elements of a basic essential obstetric care facility.', 'Parenteral antibiotics, parenteral oxytocics, blood transfusion services.', 'Manual removal of placenta, assisted vagina delivery, manual vacuum aspiration.', 'Parenteral sedatives , parenteral antihypertensives, intravenous fluidss', 'Manual removal of placenta, manual vacuum aspiration, caesarean section services.', 'B', 'Per WHO/Kenya MOH EmONC standards, the Basic Emergency Obstetric Care (BEmONC) signal functions are parenteral antibiotics, oxytocics and anticonvulsants, manual removal of placenta, removal of retained products (e.g. manual vacuum aspiration) and assisted vaginal delivery; option B (manual removal of placenta, assisted vaginal delivery, manual vacuum aspiration) lists three of these basic signal functions. Option A includes blood transfusion and option D includes caesarean section - both COMPREHENSIVE (CEmONC) functions - so they are not purely basic-facility elements.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which one of the following is not a positive sign of pregnancy:', 'Presence of human chorionic gonadotrophic hormone in urine.', 'Visualisation of fetal pulsation of ultrasound.', 'Palpation of fetal parts.', 'Palpation of fetal movement.', 'A', 'Per Myles Textbook for Midwives, positive signs of pregnancy detect the fetus directly - visualising fetal pulsation on ultrasound (B), palpating fetal parts (C) and palpating fetal movements (D). Presence of HCG in urine (A) is only a PROBABLE sign, so it is the one that is NOT a positive sign and is the correct answer to this negatively-phrased stem.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In fetal circulation, the temporary structure connecting the umbilical vein to the inferior vena cava is known as:', 'Foramen ovale.', 'Ductus venosus.', 'Ductus arteriosus.', 'Hypogastric arteries.', 'B', 'Per Myles Textbook for Midwives fetal circulation, the ductus venosus (B) is the temporary vessel carrying oxygenated blood from the umbilical vein to the inferior vena cava, bypassing the fetal liver. The foramen ovale (A) links the atria, the ductus arteriosus (C) links the pulmonary artery to the aorta, and the hypogastric arteries (D) become the umbilical arteries carrying deoxygenated blood to the placenta.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which region of the fetal skull lie from the anterior fontanelle and the coronal suture to the orbital ridges?', 'Sinciput.', 'Vertex.', 'Occuput.', 'Face.', 'A', 'Per Myles Textbook for Midwives, the sinciput (brow) is the region of the fetal skull extending from the anterior fontanelle and coronal suture forward to the orbital ridges (A). The vertex (B) lies between the fontanelles and parietal eminences, the occiput (C) lies behind the posterior fontanelle, and the face (D) lies from the orbital ridges to the chin.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which uterine support maintains the anteverted position of the uterus:', 'Transverse cervical ligament.', 'Ovarian ligament.', 'Broad ligament.', 'Round ligament.', 'D', 'Per Myles Textbook for Midwives, the round ligaments maintain the anteverted, anteflexed position of the uterus by pulling the fundus forward (D). The transverse cervical (cardinal) ligaments (A) provide the main support against prolapse, the ovarian ligament (B) anchors the ovary, and the broad ligament (C) is a peritoneal fold that does not maintain anteversion.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following statements best describes the vertex:', 'A region between the foramen magnum and the posterior fontanelle.', 'A region bounded by the posterior fontanelle, anterior fontanelle and two parietal eminencies.', 'A region from the anterior fontanelle and the coronal suture to the orbital ridges.', 'An area from the orbital ridges and the root of the nose to the junction of the chin and the neck.', 'B', 'Per Myles Textbook for Midwives, the vertex is the diamond-shaped region of the fetal skull bounded by the anterior fontanelle, the posterior fontanelle and the two parietal eminences (B). Option A describes the occipital region, option C describes the sinciput (brow), and option D describes the face.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The midwife should perform Ortolanis test on a new born to rule out congenital abnormality of:', 'Kneel joint.', 'Shoulder joint.', 'Hip joint.', 'Ankle joint.', 'C', 'Per Myles Textbook for Midwives and newborn examination, Ortolani''s test detects developmental dysplasia/congenital dislocation of the HIP joint (C) in the neonate. It does not assess the knee, shoulder or ankle joints (A, B, D).', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The term Godell''ssign is used to refer to:', 'Pulsation of fornices.', 'Bluish violet discouration of vaginal walls.', 'Softening of the cervix', 'Caesation of menstruation', 'C', 'Per Myles Textbook for Midwives, Goodell''s sign is the softening of the CERVIX in early pregnancy due to increased vascularity (C). Pulsation of the fornices (A) is Osiander''s sign, bluish-violet vaginal discolouration (B) is Jacquemier''s sign, and cessation of menstruation (D) is a presumptive sign.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In the 4th degree of inversion of the uterus:', 'The fundus reaches the internal os.', 'The cervix uterus and vagina are inverted and are visible.', 'The body of the uterus is inverted into the internal os.', 'The external os is turned upside down.', 'B', 'Per Myles Textbook for Midwives, in fourth-degree (total) inversion of the uterus the uterus, cervix and vagina are completely inverted and visible outside the vulva (B). Lesser degrees involve the fundus reaching only to the internal os or the body of the uterus passing through the cervix (A, C), so those describe first-to-third degree inversion.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Function of the surfactant factor is:', 'Initiating breathing at birth.', 'Maturing the respiratory centre in the brain.', 'Regulating breathing immediately the baby is born.', 'Preventing the alveoli of the lungs from collapsing.', 'D', 'Per Myles Textbook for Midwives and neonatal physiology, surfactant reduces alveolar surface tension and prevents the alveoli from collapsing (atelectasis) at end-expiration, maintaining lung expansion after birth (D). Its deficiency in preterm infants causes respiratory distress syndrome. It does not itself initiate or regulate breathing (A, C) nor mature the respiratory centre (B).', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('On first examination of the new born, a midwife elicits undescended testis, which term is used to refer to this condition?', 'Exomphalos.', 'Gastroschisis.', 'Hypospadias.', 'Cryptorchidism.', 'D', 'Per Myles Textbook for Midwives and neonatal examination, cryptorchidism is the term for an undescended testis/testes (D). Hypospadias (C) is an abnormally sited urethral opening, while exomphalos (A) and gastroschisis (B) are anterior abdominal wall defects, not testicular conditions.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('During postnatal examination of a mother, painful stiff calf muscles with unilateral oedema and a positive Homan''s sign is diagnostic of:', 'Deep vein thrombosis.', 'Superficial vein thrombosis.', 'Deep thrombophlebitis.', 'Superficial thrombophlebitis.', 'A', 'Per Myles Textbook for Midwives, painful stiff calf muscles with unilateral leg oedema and a positive Homan''s sign in the postnatal period is characteristic of deep vein thrombosis (A). Superficial thrombophlebitis (D) presents as a tender, palpable, inflamed superficial vein without significant limb oedema, and the distinction from the other options rests on the deep, unilateral oedema and positive Homan''s sign.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Light for date baby is one :', 'Whose weight is below 2500gms.', 'Who is born before 37 completed weeks.', 'Whose weight is below 1500gms at birth.', 'Whose weight is below the 10th percentile for that gestational age.', 'D', 'Per Myles Textbook for Midwives, a light-for-date (small-for-gestational-age) baby is one whose birth weight falls below the 10th percentile for that gestational age (D). Weight below 2500 g (A) defines low birth weight, weight below 1500 g (C) is very low birth weight, and birth before 37 completed weeks (B) defines prematurity - none of which is synonymous with light-for-date.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Trisomy 18 results into:', 'Turners syndrome.', 'Edwards syndrome.', 'Patau syndrome.', 'Downs syndrome.', 'B', 'Per standard genetics and Myles Textbook for Midwives, trisomy 18 causes Edwards syndrome (B). Trisomy 21 is Down syndrome (D), trisomy 13 is Patau syndrome (C), and Turner syndrome (A) is 45,XO monosomy, not a trisomy.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('One of the following statements include the incorrect management of a woman who has cardiac disease in pregnancy:', 'Use of diuretics in third stage of labour.', 'Perform assisted vaginal delivery to all women with cardiac disease.', 'Administration of syntocinon during AMTSL.', 'If oxytocin infusion is required, use a lower concentration at a slower rate', 'B', 'Per Myles Textbook for Midwives, this negatively-phrased stem asks for INCORRECT management: assisted vaginal delivery should be used selectively to shorten the second stage in cardiac patients, not performed for ALL women with cardiac disease (B), so this is the incorrect statement. Cautious diuretic use to avoid fluid overload (A), giving syntocinon during AMTSL (C), and using a lower-concentration oxytocin infusion at a slower rate (D) are all appropriate, correct measures.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following statements best describes a complete breech?', 'The hips are flexed, and the legs are extended over the abdomen.', 'The hips and the knees are flexed and the feet are tucked besides the buttocks.', 'The hips and the feet are not fully flexed and the feet are lower than the buttocks.', 'Hips are extended while knees are flexed.', 'B', 'Per Myles Textbook for Midwives, a complete (flexed) breech has both hips and knees flexed with the feet tucked beside the buttocks, matching option B. Option A (hips flexed, legs extended over the abdomen) describes a frank breech; option C (feet lower than the buttocks) describes a footling breech; option D (hips extended, knees flexed) is not a recognised breech type. B is the single best answer.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('One of the following include the incorrect intervention for a woman who has cardiac disease in pregnancy:', 'Administer anticoagulant in women who have prosthetic valves.', 'Use of assisted vaginal delivery as the main modality.', 'Administer crystalline penicillin to reduce risk of infective endocarditis.', 'Use ergometrine in active management third stage labour.', 'D', 'The stem asks for the INCORRECT intervention. Per Myles Textbook for Midwives and Kenya MOH maternal guidelines, ergometrine is contraindicated in cardiac disease because its marked vasoconstriction and abrupt increase in venous return can precipitate acute pulmonary oedema/cardiac failure; oxytocin (slow) is preferred in AMTSL, so using ergometrine (D) is the wrong intervention and the correct choice. Anticoagulation for prosthetic valves (A), assisted vaginal delivery to shorten the strenuous second stage (B) and penicillin prophylaxis against infective endocarditis (C) are all appropriate.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When taking history in children, which statement is true?', 'Closed questions should not be used', 'A 4-year-old child can be relied on to give history', 'A child should remain still for the clinician to successfully take the history', 'The presenting complaints should be listed in the order in which they are stated by the mother', 'D', 'In paediatric history-taking the caregiver is the historian and presenting complaints are recorded in the order given by the mother/caregiver (Nelson Textbook of Pediatrics; Kenya Basic Paediatric Protocols), making D true. Closed questions are legitimately used (so A is false), a 4-year-old is not a reliable historian (B false), and a child need not be kept still to obtain a history (C false).', 'BScN', 'Paper I', 'Paediatric Nursing', 'Paediatrics', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('As regards physical examination in children:', 'Abdominal auscultation should be done before palpation', 'The apex is normally found in the 5th intercostal space mid-clavicular line', 'Pleural effusion gives a resonant note on percussion', 'ENT examination should be done at the beginning of the systemic examination', 'B', 'The cardiac apex beat is normally in the 5th intercostal space at the mid-clavicular line (standard clinical examination; Nelson), so B is a true and unambiguous finding. Pleural effusion gives a stony DULL note, not resonant (C false), and painful ENT examination is done last in children (D false). Note that option A (''abdominal auscultation before palpation'') is also correct clinical order for the abdomen, so the item technically has two true statements; B is the intended single best/most unambiguous answer.', 'BScN', 'Paper I', 'Paediatric Nursing', 'Paediatrics', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('TORCHES include the following EXCEPT:', 'German measles', 'Cryptococcus infection', 'Toxoplasmosis', 'Herpes simplex', 'B', 'TORCHES = Toxoplasmosis, Other (syphilis), Rubella/German measles, Cytomegalovirus, Herpes simplex, Syphilis (Nelson; congenital infection teaching). Cryptococcus is not part of this group and is the correct EXCEPT answer. German measles (rubella), toxoplasmosis and herpes simplex are all included.', 'BScN', 'Paper I', 'Paediatric Nursing', 'Paediatrics', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('TRUE of neonatal infections is that:', 'A negative blood culture rules out sepsis', 'The commonest cause of ophthalmia neonatorum is Neisseria gonorrhea', 'The correct duration for the treatment of neonatal sepsis is 5 days', 'The treatment of choice for cord infection currently in Kenya is 7% Chlorhexidine', 'B', 'Neisseria gonorrhoeae is the classic, most serious cause of ophthalmia neonatorum (Kenya Basic Paediatric Protocols; Nelson), so B is true. A negative blood culture does not exclude neonatal sepsis (A false), neonatal sepsis is treated for 7-10+ days not 5 (C false), and Kenyan cord care uses 7.1% chlorhexidine digluconate gel delivering 4% chlorhexidine (D''s figure/framing is off), leaving B as the correct statement.', 'BScN', 'Paper I', 'Paediatric Nursing', 'Paediatrics', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In the care of large for gestational age infants, the most common problem in the first 24 hours after delivery is:', 'Hyperglycemia', 'Hypoglycemia', 'Birth injury', 'Hypothermia', 'B', 'Large-for-gestational-age infants (often infants of diabetic mothers with fetal hyperinsulinism) are at highest risk of hypoglycaemia in the first 24 hours (Kenya Basic Paediatric Protocols; Nelson), so B is correct. Hyperglycaemia (A) is not the early problem; birth injury (C) and hypothermia (D) occur but hypoglycaemia is the most common early metabolic complication.', 'BScN', 'Paper I', 'Paediatric Nursing', 'Paediatrics', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the vaccine below is correctly matched with the age at which it is normally administered?', 'Measles - 6 and 18 months', 'BCG - 6 weeks', 'Rota - 6 and 10 weeks', 'Pentavalent - 10 and 14 weeks', 'C', 'Per the KEPI/Kenya immunization schedule, rotavirus vaccine is given at 6 and 10 weeks, so C is correctly matched. BCG is given at birth not 6 weeks (A wrong), measles at 9 and 18 months not 6 and 18 (B wrong), and pentavalent at 6, 10 and 14 weeks not just 10 and 14 (D wrong).', 'BScN', 'Paper I', 'Paediatric Nursing', 'Paediatrics', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A one-year-old is brought to the MCH clinic for the routine monitoring. What statement below reflects normal growth and development at this age?', 'A weight of 14kgs', 'A head circumference of 47cm', 'Crawling', 'A 2-word sentence', 'B', 'At 12 months the average head circumference is approximately 46-47 cm (Nelson; Kenya MCH growth monitoring), so B reflects normal development. Normal weight at 1 year is about 9-10 kg not 14 (A wrong), crawling is expected by ~8-9 months and most infants walk by ~12 months so crawling alone is not the milestone highlighted (C), and 2-word sentences appear around 2 years not 1 year (D wrong).', 'BScN', 'Paper I', 'Paediatric Nursing', 'Paediatrics', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Poliomyelitis is a notifiable disease. A correct statement about poliomyelitis is that:', 'Most of the infections result in paralysis', 'It leads to an ascending paralysis similar to Gullian Barre Syndrome', 'Full recovery follows paralytic disease', 'Intramuscular injections increase the risk of paralytic disease', 'D', 'Provocation paralysis is well described: intramuscular injections and trauma during poliovirus infection increase the risk of paralytic disease in the affected limb (WHO; Nelson), making D correct. Most polio infections are asymptomatic/non-paralytic (A false), recovery from paralytic polio is often incomplete (C false), and polio causes asymmetric flaccid paralysis unlike the symmetric ascending pattern of Guillain-Barre (B false).', 'BScN', 'Paper I', 'Paediatric Nursing', 'Paediatrics', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Choose among the listed conditions an acyanotic congenital heart disease:', 'Patent ductus arteriosus', 'Truncus arteriosus', 'Ebstein anomaly', 'Tetralogy of fallot', 'A', 'Patent ductus arteriosus is an acyanotic left-to-right shunt lesion (Nelson), so A is correct. Truncus arteriosus (B), Ebstein anomaly (C) and Tetralogy of Fallot (D) are cyanotic congenital heart lesions with right-to-left shunting or mixing.', 'BScN', 'Paper I', 'Paediatric Nursing', 'Paediatrics', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Congestive cardiac failure in children is characterized by which of the following cardinal features on physical examination?', 'Crying a lot', 'Cyanosis', 'Elevated temperature', 'Displaced apex', 'D', 'Congestive cardiac failure in children produces cardiomegaly with a displaced apex beat, alongside tachycardia, tachypnoea and hepatomegaly (Nelson; Basic Paediatric Protocols), so D is the cardinal physical sign. Crying (A), cyanosis (B) and elevated temperature (C) are non-specific and not cardinal signs of CCF.', 'BScN', 'Paper I', 'Paediatric Nursing', 'Paediatrics', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Identify among the following that which belongs to the minor criteria for the diagnosis of Acute Rheumatic fever:', 'Sydenham''s chorea', 'Elevated Antistreptolysin O titres', 'Prolonged PR interval', 'Migratory Polyarthritis', 'C', 'By the revised Jones criteria, a prolonged PR interval is a MINOR criterion for acute rheumatic fever (Nelson), so C is correct. Sydenham''s chorea (A) and migratory polyarthritis (D) are MAJOR criteria, and an elevated ASO titre (B) is evidence of preceding streptococcal infection rather than a minor criterion.', 'BScN', 'Paper I', 'Paediatric Nursing', 'Paediatrics', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Joe is admitted with features that are highly suggestive of pulmonary tuberculosis. Which of the following is true of PTB in children?', 'Children suffer open as opposed to close PTB', 'Isoniazid is associated with peripheral neuropathy', 'Sputum is easily obtained through coughing up in all ages of children', 'The total duration of treatment is 4 months', 'B', 'Isoniazid depletes pyridoxine (vitamin B6) and can cause peripheral neuropathy (Kenya National TB Guidelines; BNF), so B is true. Children characteristically have closed/paucibacillary PTB (A false), sputum is hard to obtain in young children so gastric aspirate is used (C false), and standard treatment is 6 months not 4 (D false).', 'BScN', 'Paper I', 'Paediatric Nursing', 'Paediatrics', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Hookworms in the paediatric age group are likely to cause:', 'Iron deficiency anaemia', 'Bloody stools', 'Intestinal obstruction', 'Severe vomiting', 'A', 'Hookworm (Ancylostoma/Necator) attaches to the gut mucosa causing chronic occult blood loss and iron deficiency anaemia (Kenya deworming programme/IMNCI; Nelson), so A is correct. It does not typically cause frank bloody stools (B), intestinal obstruction (C) or severe vomiting (D).', 'BScN', 'Paper I', 'Paediatric Nursing', 'Paediatrics', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Dysentery is most likely to be caused by which of the following organism?', 'Rota virus', 'Entamoeba histolytica', 'Giardia lamblia', 'Campylobacter jejuni', 'B', 'Dysentery (bloody, mucoid diarrhoea) is classically caused by Entamoeba histolytica (amoebic) and Shigella (Kenya IMNCI; Basic Paediatric Protocols), so among the options B is the best fit. Rotavirus (A) and Giardia lamblia (C) cause watery non-bloody diarrhoea; Campylobacter jejuni (D) can cause bloody diarrhoea but Entamoeba histolytica is the classic dysentery organism intended here.', 'BScN', 'Paper I', 'Paediatric Nursing', 'Paediatrics', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('True of upper airway infections in children is:', 'Epiglottitis is commonly caused by viruses', 'Enlarged adenoids are likely to present with mouth breathing', 'Laryngotracheobronchitis (croup) is best treated with antibiotics', 'It is safe to use a spatula to examine the throat if one suspects diphtheria', 'B', 'Adenoidal hypertrophy obstructs the nasopharynx and presents with chronic mouth breathing, snoring and nasal speech (Nelson), so B is correct. Epiglottitis is bacterial (H. influenzae type b), not viral (A false); croup (laryngotracheobronchitis) is viral and treated with steroids/supportive care not antibiotics (C false); and a spatula must NOT be used to examine the throat when diphtheria is suspected because of the risk of precipitating airway obstruction (D false).', 'BScN', 'Paper I', 'Paediatric Nursing', 'Paediatrics', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Regarding the WHO classification and management of dehydration:', 'Some dehydration is best managed with IV Ringers Lactate', 'A weak or absent pulse is a sign of severe dehydration', 'Hypovolemic shock is first treated with IV boluses of Normal saline', 'No dehydration does not require any treatment in the presence of loose stools', 'B', 'Per WHO/Kenya IMNCI, a weak or absent pulse (with lethargy, sunken eyes and a very slow skin pinch) indicates SEVERE dehydration, so B is correct. Severe (not ''some'') dehydration is managed with IV Ringer''s Lactate (A misassigns the fluid), paediatric hypovolaemic shock is resuscitated with Ringer''s Lactate rather than routine normal saline boluses under IMNCI (C questionable), and ''no dehydration'' with ongoing diarrhoea still requires Plan A ORS and continued feeding (D false).', 'BScN', 'Paper I', 'Paediatric Nursing', 'Paediatrics', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('UTI in young children is likely to present with:', 'Dysuria', 'Frequency', 'Enuresis', 'Failure to thrive', 'D', 'In infants and young children UTI presents non-specifically with failure to thrive, poor feeding, fever, irritability and vomiting rather than the classic urinary symptoms (Nelson; Basic Paediatric Protocols), so D is correct. Dysuria (A), frequency (B) and enuresis (C) are features seen in older, verbal children.', 'BScN', 'Paper I', 'Paediatric Nursing', 'Paediatrics', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the statement below is correct about Nephrotic syndrome?', 'It presents with mild periorbital oedema', 'It occurs after a throat infection with GABH streptococcus', 'Bee stings is a differential diagnosis', 'IV Dexamethasone is the main drug used in its treatment', 'C', 'Nephrotic syndrome causes massive generalised oedema, and the marked periorbital/facial swelling can mimic an allergic reaction such as a bee/insect sting (angioedema), so a bee sting is a differential of the facial swelling (Nelson), making C the intended answer. The oedema is severe, not mild (A false); it is NOT preceded by streptococcal throat infection (that describes post-streptococcal glomerulonephritis, B false); and oral prednisolone, not IV dexamethasone, is the mainstay of treatment (D false).', 'BScN', 'Paper I', 'Paediatric Nursing', 'Paediatrics', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Acute kidney injury:', 'Mostly results in chronic kidney disease', 'Severe dehydration is a common cause in children', 'Hypertension is present in most cases', 'Convulsions do not occur in this condition', 'B', 'In children, pre-renal acute kidney injury from severe dehydration (diarrhoeal disease, sepsis) is a common and reversible cause (Kenya Basic Paediatric Protocols; Nelson), so B is correct. Most childhood AKI is reversible and does not progress to CKD (A false), hypertension is not present in most cases (C false), and convulsions can occur from uraemia/electrolyte disturbance (D false).', 'BScN', 'Paper I', 'Paediatric Nursing', 'Paediatrics', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A feature of Hypothyroidism in infants among the following is:', 'Crying all the time', 'Good appetite', 'Poor cold tolerance', 'Small tongue', 'C', 'Congenital hypothyroidism causes a hypometabolic state with poor cold tolerance, lethargy, poor feeding, constipation, macroglossia and a hoarse cry (Nelson), so C is correct. The infant is sluggish rather than crying constantly (A false), feeds poorly with a poor appetite (B false), and has a LARGE tongue not a small one (D false).', 'BScN', 'Paper I', 'Paediatric Nursing', 'Paediatrics', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Kwashiorkor is characterized by one of the stated features below:', 'Moon faces', 'Wizened look', 'Ferocious appetite', 'Weight for age of less than 60%', 'A', 'Kwashiorkor (oedematous malnutrition) is characterised by a round ''moon'' face, bilateral pitting oedema, apathy, poor appetite and skin/hair changes (Kenya IMNCI; Basic Paediatric Protocols), so A is correct. The wizened/old-man look (B) and ferocious appetite (C) belong to marasmus, and weight-for-age <60% (D) describes marasmic severity rather than the defining feature of kwashiorkor.', 'BScN', 'Paper I', 'Paediatric Nursing', 'Paediatrics', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Downs syndrome:', 'Is trisomy 22', 'Is also called cretinism', 'Ventriculoseptal defects are an associated', 'The children have normal IQ', 'C', 'Down syndrome (trisomy 21) is strongly associated with congenital heart defects, notably AV septal and ventricular septal defects (Nelson), so C is correct. It is trisomy 21 not trisomy 22 (A false), cretinism is congenital hypothyroidism and a distinct condition (B false), and affected children have intellectual disability with reduced IQ (D false).', 'BScN', 'Paper I', 'Paediatric Nursing', 'Paediatrics', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The test that is included as part of cerebrospinal fluid analysis is:', 'The protein level', 'Viral culture', 'Electrolytes', 'Immunoglobulins', 'A', 'Standard CSF analysis includes protein, glucose, cell count/differential, Gram stain and culture (Nelson; Basic Paediatric Protocols), so protein level (A) is a routine component. Viral culture (B), electrolytes (C) and immunoglobulins (D) are not part of routine CSF analysis.', 'BScN', 'Paper I', 'Paediatric Nursing', 'Paediatrics', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The correct level of placing the lumbar puncture needle in children is between:', 'L1 and L2', 'L2 and L3', 'L3 and L4', 'L4 and L5', 'C', 'Lumbar puncture in children is performed at the L3/L4 (or L4/L5) interspace, below the termination of the spinal cord, using the intercristal (supracristal) line as a landmark (Nelson; Basic Paediatric Protocols), so C (L3/L4) is the standard and safest of the offered levels. L1/L2 (A) and L2/L3 (B) risk cord injury; L4/L5 (D) is acceptable but L3/L4 is the conventional answer.', 'BScN', 'Paper I', 'Paediatric Nursing', 'Paediatrics', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Convulsions are common in children. True of convulsions is that:', 'Febrile convulsions occur in the 6 months to 4 years window', 'Low magnesium levels are a contributing factor', 'A history of a fall from a height is not significant', 'The most common type is the tonic type', 'A', 'Simple febrile convulsions occur in the 6 months to ~5-6 years window, and of the options the 6 months-4 years range best fits (Nelson; Basic Paediatric Protocols), so A is correct. Hypocalcaemia (calcium), not magnesium, is the classic contributing electrolyte (B false); a fall from height is significant as it suggests trauma (C false); and the generalised tonic-clonic type is the most common (D false).', 'BScN', 'Paper I', 'Paediatric Nursing', 'Paediatrics', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Sickle cell disease:', 'Is an autosomal dominant inherited disorder', 'Presents with hand and foot syndrome in children older than 2 years', 'Life span in these patients is less than 20 years', 'The painful crisis is the same as the thrombotic crisis', 'D', 'In sickle cell disease the vaso-occlusive crisis IS the painful (thrombotic) crisis (Nelson; Kenya sickle cell guidelines), so D is the correct statement. It is autosomal recessive not dominant (A false), hand-foot syndrome/dactylitis occurs in infants usually under 2 years not older (B false), and with modern care survival extends well beyond 20 years (C false).', 'BScN', 'Paper I', 'Paediatric Nursing', 'Paediatrics', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('As regard the Hemophilias:', 'Christmas disease is also known as Hemophilia A', 'Hemathrosis is the commonest presentation', 'Hemophilia A is caused by deficiency of factor IX', 'Hemophilia B is caused by deficiency of factor VIII', 'B', 'Haemarthrosis (bleeding into joints) is the hallmark and commonest presentation of haemophilia (Nelson), so B is correct. Christmas disease is Haemophilia B/factor IX deficiency not Haemophilia A (A false), Haemophilia A is factor VIII deficiency (C false), and Haemophilia B is factor IX deficiency not VIII (D false).', 'BScN', 'Paper I', 'Paediatric Nursing', 'Paediatrics', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Acute leukemia:', 'Leucopenia is a likely laboratory finding', 'AML has a better prognosis than ALL', 'Radiation is the main mode of treatment', 'Diagnosis is made through a total blood count mostly', 'A', 'In acute leukaemia the marrow is replaced by blasts, causing anaemia, thrombocytopenia and frequently leucopenia/neutropenia of normal cells, so leucopenia (A) is a likely finding (Nelson). Definitive diagnosis is by bone marrow aspirate/biopsy not total blood count alone (D false), ALL carries a better prognosis than AML in children (B false), and chemotherapy not radiation is the mainstay of treatment (C false).', 'BScN', 'Paper I', 'Paediatric Nursing', 'Paediatrics', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following vaccine is a live vaccine:', 'Diphtheria', 'Pertussis', 'Hepatitis B', 'Tetanus Toxoid', 'A', 'None of the listed options is genuinely a live vaccine: diphtheria and tetanus are toxoids, pertussis is inactivated (killed), and hepatitis B is a recombinant subunit vaccine (KEPI; standard immunology). Live vaccines are BCG, OPV, measles and rotavirus, none of which appear here; A is retained only as the least-wrong/keyed choice while the item is flawed.', 'BScN', 'Paper I', 'Paediatric Nursing', 'Paediatrics', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A side effect of phototherapy is:', 'Convulsions', 'Grey baby syndrome', 'Damage to the cornea', 'Burns', 'D', 'Recognised side effects of phototherapy include loose stools, dehydration, hyperthermia, skin rash/burns and retinal damage if the eyes are unshielded (Kenya Basic Paediatric Protocols; Nelson), so of the options burns (D) is correct. Convulsions (A) are not caused by phototherapy, grey baby syndrome (B) is a chloramphenicol toxicity, and corneal damage (C) is not the recognised term (retinal damage from unshielded eyes is the concern).', 'BScN', 'Paper I', 'Paediatric Nursing', 'Paediatrics', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following is true concerning HIV infection in children?', 'A positive HIV Elisa test in a child less than 18 months old shows that the child is HIV infected', 'An HIV virologic test is necessary to make a diagnosis of HIV in children of all ages', 'HIV ELISA tests for presence of antibodies to HIV in blood', 'HIV PCR tests for presence of antibodies to HIV in blood', 'C', 'The HIV ELISA/rapid test detects antibodies to HIV in blood (Kenya HIV Guidelines), so C is correct. In children under 18 months maternal antibodies persist, so a positive antibody test does not confirm infection (A false); a virologic DNA-PCR test is required under 18 months, not at all ages (B false); and PCR detects viral nucleic acid, not antibodies (D false).', 'BScN', 'Paper I', 'Paediatric Nursing', 'Paediatrics', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('According to the WHO staging of HIV, a diagnosis of PTB puts the patient in which stage?', 'Stage 1', 'Stage 2', 'Stage 3', 'Stage 4', 'C', 'In WHO HIV clinical staging, pulmonary tuberculosis is a Stage 3 condition (Kenya/WHO HIV Guidelines), so C is correct. Stage 1 is asymptomatic, Stage 2 covers minor mucocutaneous conditions, and Stage 4 includes extrapulmonary TB and other AIDS-defining illnesses.', 'BScN', 'Paper I', 'Paediatric Nursing', 'Paediatrics', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following treatment is indicated in a child who is convulsing now:', 'I.V. Diazepam 0.3 mg/kg/body weight STAT', 'I.M. Diazepam 0.5 mg/kg/body weight STAT', 'I.V. Phenobarbitone 3mg/kg/body weight STAT', 'Phenobarbitone per oral 3-8mg/kg/body weight', 'A', 'For a child actively convulsing, IV diazepam 0.3 mg/kg (or rectal 0.5 mg/kg) is the recommended first-line anticonvulsant (Kenya Basic Paediatric Protocols), so A is correct. The IM route for diazepam is unreliable and not used (B wrong), and the phenobarbitone doses/routes given (C, D) are not the first-line abortive therapy for an active seizure.', 'BScN', 'Paper I', 'Paediatric Nursing', 'Paediatrics', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In the lifecycle of the malaria parasite, which stage below occurs in the mosquito?', 'Merozoite', 'Trophozoite', 'Sporozoite', 'Gametocyte', 'C', 'The sexual (sporogonic) cycle of the malaria parasite occurs in the mosquito, culminating in sporozoites in the salivary glands that are injected into humans (Kenya Malaria Guidelines; standard parasitology), so C is the mosquito stage. Merozoites (A) and trophozoites (B) are human erythrocytic stages, and gametocytes (D) form in humans and are only taken up by the mosquito.', 'BScN', 'Paper I', 'Paediatric Nursing', 'Paediatrics', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following is a risk factor for Mother to child transmission of HIV:', 'High viral load', 'High CD4 count', 'Malaria', 'Multiple gestation', 'A', 'A high maternal HIV viral load is the strongest risk factor for mother-to-child transmission (Kenya PMTCT Guidelines), so A is correct. A high CD4 count is protective (B wrong), and malaria (C) and multiple gestation (D) are not primary determinants of MTCT compared with viral load.', 'BScN', 'Paper I', 'Paediatric Nursing', 'Paediatrics', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What drug that can be used safely if needed during new born resuscitation?', 'IV Adrenalin 0.1-0.3ml/kg of 1:1000 solution', 'IV Sodium bicarbonate 1-2mmol/kg of the 8.4% solution', 'IV 10% dextrose 2.5ml/kg STAT', 'IV Aminophylline', 'A', 'Adrenaline is the drug used in newborn resuscitation when the heart rate remains below 60/min despite adequate ventilation (Kenya Basic Paediatric Protocols/NRP), so A is the correct drug. Sodium bicarbonate (B) and aminophylline (D) are not routine resuscitation drugs, and 10% dextrose (C) is only for documented hypoglycaemia. Note the stem''s concentration is erroneous: NRP adrenaline is 1:10,000 (0.1-0.3 ml/kg IV), not the 1:1000 written.', 'BScN', 'Paper I', 'Paediatric Nursing', 'Paediatrics', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following is not a differential diagnosis for a wheezing child aged 3 years:', 'Bronchiolitis', 'Congestive Heart failure', 'Empyema Thoracis', 'Foreign body aspiration', 'C', 'Empyema thoracis is a purulent pleural collection presenting with dullness to percussion and reduced/absent breath sounds, NOT wheeze, so it is not a differential for a wheezing child (Nelson Textbook of Pediatrics; Kenya Basic Paediatric Protocols). By contrast bronchiolitis (small-airway obstruction), congestive heart failure (cardiac wheeze from pulmonary congestion) and foreign body aspiration (localised airway obstruction) all produce wheeze, making empyema the correct ''not a differential'' answer.', 'BScN', 'Paper I', 'Paediatric Nursing', 'Paediatrics', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following drug can be routinely and safely given to a 1-year-old baby who you are treating for acute gastroenteritis:', 'IV Ceftriaxone 50mg/kg OD for 5 days', 'Oral Zinc sulphate 20mg OD for 14 days', 'Oral Vitamin A 300,000IU STAT', 'Syrup Amoxycillin 125mg three times per day for 5 days', 'B', 'Per Kenya IMNCI and the Basic Paediatric Protocols, every child with acute gastroenteritis routinely receives zinc supplementation alongside ORS — 20 mg daily for 10-14 days for children 6 months and older (10 mg for infants under 6 months) — to reduce diarrhoea duration and recurrence, making oral zinc sulphate safe and routine for a 1-year-old. Antibiotics (ceftriaxone, amoxicillin) are reserved for specific indications such as dysentery or cholera, not routine watery diarrhoea, and high-dose vitamin A is not indicated for uncomplicated gastroenteritis, so zinc is the correct routine drug.', 'BScN', 'Paper I', 'Paediatric Nursing', 'Paediatrics', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The first test done at the bedside on the cerebrospinal fluid is:', 'White blood cell count', 'Glucose level determination', 'Looking for turbidity', 'Protein level', 'C', 'The first bedside assessment of CSF at lumbar puncture is visual inspection of its appearance/turbidity (clear versus cloudy), which immediately suggests bacterial meningitis when cloudy (Kenya Basic Paediatric Protocols; Nelson). White cell count, glucose and protein all require laboratory analysis and cannot be obtained at the bedside, so looking for turbidity is the correct first bedside test.', 'BScN', 'Paper I', 'Paediatric Nursing', 'Paediatrics', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following are examined under higher centers in Central Nervous system examination in a 5-year-old:', 'Hallucinations', 'Balance', 'Level of consciousness', 'Deep tendon reflexes', 'C', 'Higher (cerebral/cortical) functions assessed in a CNS examination include level of consciousness, orientation, memory, speech and cognition; level of consciousness is the classic higher-centre item (Nelson; standard neurological examination). Balance is a cerebellar function and deep tendon reflexes belong to the reflex/motor examination, while hallucinations are a mental-state symptom rather than a routinely elicited higher-centre examination finding in a 5-year-old, so level of consciousness is the correct answer.', 'BScN', 'Paper I', 'Paediatric Nursing', 'Paediatrics', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Humoral immunity is carried out by ______, while cell-mediated immunity is carried out by ______.', 'B cells / T cells', 'T cells / B cells', 'Antigens / antibodies', 'Epitopes / antigens', 'A', 'Humoral (antibody-mediated) immunity is effected by B lymphocytes and the antibodies secreted by their plasma-cell progeny, while cell-mediated immunity is effected by T lymphocytes (Abbas Basic Immunology; Roitt). Option B reverses the two; options C, D and E name antigenic structures (antigens, epitopes, haptens) or effector cells that are not the lymphocyte populations responsible, so ''B cells / T cells'' is the only correct pairing.', 'BScN', 'Paper I', 'Community Health Nursing', 'Immunology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which one of the following is NOT a privileged immunological site?', 'Testis', 'The brain', 'Bone marrow', 'The uterus', 'C', 'Immunologically privileged sites tolerate foreign antigen without mounting a destructive inflammatory response, and classically include the brain/CNS, the eye (anterior chamber, cornea), the testis and the pregnant uterus/placenta (Kuby; Roitt). Bone marrow is an active haematopoietic and lymphoid organ where immune cells are generated, not a privileged site, so it is the correct ''NOT'' answer.', 'BScN', 'Paper I', 'Community Health Nursing', 'Immunology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following are the characteristic features displayed by adaptive immunity. Which one is NOT?', 'Diversity', 'Intolerance', 'Immunologic memory', 'Discrimination between self and nonself', 'B', 'The four defining features of adaptive immunity are specificity, diversity, immunologic memory, and discrimination between self and non-self (self-tolerance) (Abbas Basic Immunology). The adaptive system is characterised by tolerance, not ''intolerance''; intolerance is not a feature, whereas diversity, memory, self/non-self discrimination and antigenic specificity all are, making B the correct exception.', 'BScN', 'Paper I', 'Community Health Nursing', 'Immunology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following best describes haptens?', 'Repeated units that are able to induce responses in sublethally irradiated mice reconstituted with B cells only', 'Chemicals that induce cell-mediated immune responses but not antibody synthesis', 'Small organic molecules that do not induce an immune response by themselves, but induce antibody formation when coupled to an immunogenic molecule', 'Induce tolerance when injected intravenously in soluble form and induce an immune response when injected intradermally', 'C', 'Haptens are small organic molecules that are antigenic but not immunogenic on their own; they elicit specific antibody only after being coupled to a larger immunogenic carrier molecule (Kuby; Roitt). Option C is the standard textbook definition, whereas the other options describe tolerogens, direct MHC-interacting compounds or T-cell-only stimulators that do not fit the hapten concept.', 'BScN', 'Paper I', 'Community Health Nursing', 'Immunology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following class of immunoglobulin has very high affinity to membrane receptors on tissue mast cells and blood basophils?', 'Immunoglobulin E', 'Immunoglobulin G', 'Immunoglobulin A', 'Immunoglobulin M', 'A', 'IgE binds with very high affinity to the FcεRI receptor on tissue mast cells and blood basophils, and allergen cross-linking of this bound IgE triggers degranulation in type I (immediate) hypersensitivity (Abbas; Roitt). IgE is the reaginic/cytophilic antibody; IgG, IgA, IgM and IgD do not have this high-affinity mast-cell/basophil binding role.', 'BScN', 'Paper I', 'Community Health Nursing', 'Immunology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which one of the following does not occur when the classical complement pathway is activated?', 'Breakdown of C5 into C5a and C5b', 'Binding of C3b to factor B', 'Breakdown of C3 into C3a and C3b', 'Activation of the membrane attack complex', 'B', 'Binding of C3b to factor B (forming C3bB, then the C3bBb convertase) is a step of the ALTERNATIVE pathway, not the classical pathway (Abbas; Roitt). Classical activation does cleave C3 into C3a/C3b and C5 into C5a/C5b, generates anaphylatoxins (C3a, C5a) and forms the membrane-attack complex, so B is the only event that does not occur in the classical pathway.', 'BScN', 'Paper I', 'Community Health Nursing', 'Immunology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which one of the following factors does NOT influence immunogenicity?', 'The genotype of the recipient', 'Antibody molecule', 'Molecular size', 'Chemical composition and complexity', 'B', 'Immunogenicity depends on properties of the antigen (molecular size, chemical complexity, foreignness), the host (genotype/genetic background) and the dose and route of administration (Kuby). The antibody molecule is a product of the immune response, not a determinant of whether an antigen is immunogenic, so B is the correct exception.', 'BScN', 'Paper I', 'Community Health Nursing', 'Immunology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The stimulation of cytotoxic T lymphocytes requires the association of an antigen-derived peptide with a:', 'MHC-I molecule', 'MHC-I molecule identical to one of those expressed by the cytotoxic T lymphocyte', 'MHC-II molecule', 'MHC-II molecule identical to one of those expressed by the cytotoxic T lymphocyte', 'B', 'CD8+ cytotoxic T lymphocytes recognize antigen-derived peptide presented on MHC class I, and this recognition is MHC-restricted — the CTL responds only to peptide on a self MHC-I molecule identical to one it expresses (Abbas). Option B captures both the class (MHC-I) and the self-restriction, making it more precise than the unqualified option A; MHC-II options are for CD4+ cells and are wrong.', 'BScN', 'Paper I', 'Community Health Nursing', 'Immunology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Antibody affinity can be defined as:', 'A measure of the overall strength of binding of an antigen with many antigenic determinants and multivalent antibodies', 'The number of antigenic determinants on an antigen', 'The combined strength of the non-covalent interactions between a single antigen-binding site on an antibody and a single epitope on an antigen', 'The clumping caused by antibody and antigen', 'C', 'Affinity is the strength of the non-covalent binding between a single antibody paratope and a single epitope (Kuby; Roitt). Option A describes avidity (the overall multivalent strength) and option E wrongly equates the two; option B is valency and option D is agglutination, so C is the correct definition of affinity.', 'BScN', 'Paper I', 'Community Health Nursing', 'Immunology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('All the following statements are true about inflammation. Which one is FALSE?', 'Apoptosis induces inflammation', 'Vasodilation causes leakage of blood components', 'The process can cause damage to host tissue', 'Neutrophils predominate at the site during the early stages of acute inflammation', 'A', 'Apoptosis is programmed, physiologic cell death in which the cell''s contents are neatly packaged and cleared by phagocytes without spilling, so it does NOT induce inflammation (unlike necrosis) (Robbins; Abbas). The other statements are true: vasodilation increases vascular leakage, inflammation can injure host tissue, neutrophils predominate early in acute inflammation, and the cardinal signs are redness, swelling, heat and pain — hence A is the false statement.', 'BScN', 'Paper I', 'Community Health Nursing', 'Immunology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Immunological unresponsiveness to self antigens is called:', 'Acquired immunity', 'Antibody dependent cell-mediated immunity', 'Tolerance', 'Tolerogen', 'C', 'Immunological tolerance is the specific unresponsiveness of the immune system to an antigen, and self-tolerance is unresponsiveness to self antigens (Abbas; Roitt). A tolerogen (D) is the antigen that induces tolerance, not the state itself, so C is correct; acquired immunity and the other options do not describe self-unresponsiveness.', 'BScN', 'Paper I', 'Community Health Nursing', 'Immunology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('X-linked Hyper-IgM Syndrome is characterized by:', 'Decrease in numbers of antibody-producing plasma cells, low levels of most immunoglobulin isotypes, and recurrent infections', 'Defective B cell heavy chain class switching, resulting in IgM being the major serum antibody, and severe deficiency of cell-mediated immunity against intracellular microbes', 'Skin abscesses, recurrent pneumonia, eczema, and elevated levels of IgE accompanied by facial abnormalities and bone fragility', 'Low amount of IgA', 'B', 'X-linked Hyper-IgM syndrome results from CD40 ligand (CD154) deficiency on T cells, which blocks immunoglobulin class-switch recombination so IgM remains the major serum antibody with low IgG/IgA, and impairs CD40L-dependent macrophage/T-cell defence against intracellular microbes (Abbas). Option B matches this; option A describes CVID/agammaglobulinaemia and option C describes Hyper-IgE (Job) syndrome.', 'BScN', 'Paper I', 'Community Health Nursing', 'Immunology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following pairs of immunoglobulins is found on the surface of the mature B cells?', 'IgG and IgD', 'IgG and IgA', 'IgM and IgE', 'IgM and IgD', 'D', 'Mature naive B cells co-express membrane IgM and IgD as their B-cell receptors (Abbas; Kuby). IgG, IgA and IgE appear only after antigen-driven class switching, so ''IgM and IgD'' is the correct surface pair on the mature B cell; the other pairings include switched isotypes not co-expressed on naive B cells.', 'BScN', 'Paper I', 'Community Health Nursing', 'Immunology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Natural killer cells play an important role in', 'Hypersensitivity reactions', 'Killing of viral infected cells and intracellular bacteria', 'Autoimmunity', 'Preventing viral infectivity', 'B', 'Natural killer cells are innate lymphocytes that kill virus-infected and stressed cells via missing-self recognition and antibody-dependent cellular cytotoxicity, and contribute to control of intracellular pathogens through cytotoxicity and IFN-gamma secretion (Abbas; Roitt). Option B states this principal role; neutralizing infectivity and toxins are antibody functions, not NK-cell roles.', 'BScN', 'Paper I', 'Community Health Nursing', 'Immunology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following are molecules expressed on the membrane of mature B cells EXCEPT?', 'Class II MHC', 'CD40', 'B220', 'CD3', 'D', 'Mature B cells express MHC class II, CD40, B220 (CD45R) and CD35 (complement receptor 1) (Kuby). CD3 is the signal-transducing complex of the T-cell receptor and is a T-cell marker not present on B cells, so CD3 is the correct exception.', 'BScN', 'Paper I', 'Community Health Nursing', 'Immunology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which one of the following is NOT the biological function of immunoglobulin M?', 'Is the first immunoglobulin class produced in a primary response to an antigen', 'IgM is more efficient at activating the classical pathway of complement', 'It induces mast cell degranulation', 'Is the first immunoglobulin made during B-cell maturation and is expressed as membrane-bound antibody on B cells', 'C', 'IgM is the first isotype produced in a primary response and the first made during B-cell maturation (surface IgM), is the most efficient activator of the classical complement pathway (pentameric, multiple C1q sites), and helps neutralize pathogens (Abbas; Roitt). Mast-cell degranulation is mediated by IgE via FcεRI, not IgM, so C is NOT a function of IgM.', 'BScN', 'Paper I', 'Community Health Nursing', 'Immunology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A reactive rapid plasma reagin (RPR) test suggests which one of the following diseases?', 'Chronic infectious mononucleosis', 'Primary syphilis', 'Scarlet fever', 'Primary atypical pneumonia', 'B', 'The RPR is a non-treponemal reaginic test that detects anti-cardiolipin (reagin) antibody and is used to screen for and monitor Treponema pallidum infection (Kenya MOH/WHO STI guidelines; Roitt). A reactive RPR therefore suggests syphilis (primary syphilis among the options); mononucleosis, scarlet fever, atypical pneumonia and rubella immunity are detected by other tests.', 'BScN', 'Paper I', 'Community Health Nursing', 'Immunology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which one of the following does NOT protect the external body surfaces:', 'Skin', 'Mucus', 'Gastric acid', 'Salivary amylase', 'D', 'External body surfaces are protected by the skin barrier, mucus that traps microbes, gastric acid that kills ingested organisms, and commensal gut microflora that competitively exclude pathogens (Roitt; Abbas). The salivary antimicrobial enzyme is lysozyme, not salivary amylase, which only digests starch and has no barrier or antimicrobial role, so D is correct.', 'BScN', 'Paper I', 'Community Health Nursing', 'Immunology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Precipitation tests include all of the following, EXCEPT', 'Agglutination', 'Radial immunodiffusion', 'Ring test', 'Immunoelectrophoresis', 'A', 'Precipitation reactions involve SOLUBLE antigen and include radial immunodiffusion, the ring (interface) test, immunoelectrophoresis and double (Ouchterlony) gel diffusion (Kuby). Agglutination involves PARTICULATE antigen (cells or latex beads) clumping and is a distinct reaction type, so it is the correct exception.', 'BScN', 'Paper I', 'Community Health Nursing', 'Immunology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which antibody isotypes activate the classical complement pathway?', 'IgG1 and IgA2', 'IgG4 and IgG3', 'IgM and IgG3', 'IgE and IgG2', 'C', 'The classical complement pathway is activated by antigen-bound IgM (most efficient, pentameric) and by IgG subclasses in the order IgG3 > IgG1 > IgG2, whereas IgG4, IgA, IgE and IgD do not activate it (Abbas; Roitt). Of the listed pairs, ''IgM and IgG3'' contains the two strongest classical activators and is correct; the other pairs include non-activating isotypes.', 'BScN', 'Paper I', 'Community Health Nursing', 'Immunology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Vaccines that consist of inactivated organisms are:', 'Good at inducing humoral immunity', 'Less stable than live vaccines', 'Incapable of reverting to virulence', 'More immunogenic than live vaccines', 'C', 'Inactivated (killed) vaccines contain organisms that cannot replicate and therefore cannot revert to virulence, which is their defining safety feature (Kenya KEPI/WHO immunization principles; Roitt). They are generally MORE stable but LESS immunogenic than live attenuated vaccines and often need adjuvants/boosters, so options A, B, D and E misstate their properties while C is correct.', 'BScN', 'Paper I', 'Community Health Nursing', 'Immunology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Immediate hypersensitivity (Type I) often requires quick treatment to ensure stopping the reaction. Which one of the following would not allow the allergen to react with the IgE immunoglobulin present on the mast cell membrane?', 'Antihistamine', 'Blocking antibody', 'Adrenalin', 'Cromolyn sodium', 'B', 'Only a blocking (IgG) antibody actually binds the allergen and competes with mast-cell-bound IgE, preventing the allergen from engaging IgE — the basis of allergen immunotherapy (Roitt). Antihistamines, adrenaline, cromolyn sodium and theophylline act DOWNSTREAM on mediator release or on the effects of mediators, not on the allergen-IgE interaction, so B is correct.', 'BScN', 'Paper I', 'Community Health Nursing', 'Immunology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which type of graft rejection depends on preformed antibodies present in the recipient of the graft?', 'Chronic', 'Acute', 'Accelerated', 'Hyperacute', 'D', 'Hyperacute rejection occurs within minutes to hours and is mediated by PREFORMED recipient antibodies (e.g. anti-ABO or anti-HLA) that bind graft vascular endothelium and activate complement, causing thrombosis (Abbas). Acute rejection is T-cell/antibody responses developing over days-weeks, chronic is months-years, and GVHD is donor lymphocytes attacking the host, so preformed antibody is the hallmark of hyperacute rejection (D).', 'BScN', 'Paper I', 'Community Health Nursing', 'Immunology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Cytokines play different roles in regulating the immune response. Which cytokine is most involved in the class switch to IgE production?', 'Interleukin-2', 'Interleukin-16', 'Tumor necrosis factor (TNF)', 'Interleukin-4', 'D', 'IL-4 (with IL-13) is the key Th2 cytokine that drives B-cell immunoglobulin class switching to IgE (Abbas; Kuby). IL-2 is a T-cell growth factor and TNF is a proinflammatory cytokine; IL-16 and ''IL-87'' (the latter not a real interleukin) have no role in IgE switching, so IL-4 (D) is correct.', 'BScN', 'Paper I', 'Community Health Nursing', 'Immunology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Hypotension in acute pancreatitis is mainly caused by;', 'Profuse vomiting', 'Loss of large amounts of protein rich fluid into tissues and peritoneal cavity.', 'Bleeding into the tissues and peritoneal cavity.', 'Profuse sweating and anxiety', 'B', 'In acute pancreatitis, activated enzymes increase vascular permeability causing massive third-spacing of protein-rich fluid into the retroperitoneum and peritoneal cavity, producing hypovolaemia and hypotension, per Brunner & Suddarth''s Medical-Surgical Nursing. Vomiting and sweating cause lesser fluid loss, and frank haemorrhage (C) is not the principal early mechanism.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Anatomy & Physiology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Clinical manifestations of neurogenic shock include;', 'Tachycardia, hypotension and dysrythmias.', 'Hypotension, hyperthermia and tachypnea.', 'Warm dry skin, bradycardia and hypothermia.', 'Hypothermia, warm dry skin and tachycardia.', 'C', 'Neurogenic shock from loss of sympathetic tone causes vasodilation with warm dry skin, bradycardia (unopposed vagal tone), hypotension and hypothermia, per Brunner & Suddarth''s Medical-Surgical Nursing. Options with tachycardia (A, D) reflect hypovolaemic/distributive shock and are wrong; B pairs hyperthermia incorrectly.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Anatomy & Physiology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Hysteroscopy is indicated in ;', 'Cases of infertility and cervical carcinoma.', 'Endometrial carcinoma & infertility.', 'Unexplained per vaginal bleeding & recurrent early pregnancy loss.', 'Retained intra-uterine device & acute pelvic inflammation.', 'C', 'Hysteroscopy visualises the uterine cavity and is indicated for unexplained/abnormal vaginal bleeding and recurrent early pregnancy loss, per standard gynaecology references. Acute pelvic inflammation (D) and cervical carcinoma (A) are contraindications, and endometrial carcinoma diagnosis usually relies on biopsy/D&C.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Anatomy & Physiology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Abnormal findings on Breast examination includes;', 'Longstanding nipple inversion, breast tenderness before menses.', 'Unilateral venous prominence, skin dimpling.', 'Lumpiness before menstruation, skin dimpling.', 'Longstanding nipple inversion, edema', 'B', 'Skin dimpling (tethering/peau d''orange) and unilateral venous prominence are pathological breast findings suggestive of malignancy, per Brunner & Suddarth''s Medical-Surgical Nursing. Longstanding nipple inversion and premenstrual lumpiness/tenderness (A, C, D as paired) are usually benign/physiological.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Anatomy & Physiology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Early signs of cervical cancer include;', 'Bleeding between menstrual periods, dyspareunia and prolonged bleeding.', 'Heavy bleeding post intercourse, pelvic pain and unusual discharge.', 'Pelvic pain, unusual vaginal discharge and increased urinary frequency.', 'Prolonged bleeding, dyspareunia and bleeding between menstrual periods.', 'A', 'Early cervical cancer presents with abnormal bleeding (intermenstrual, prolonged/menorrhagia) and dyspareunia, per Kenya cervical cancer screening guidelines and gynaecology texts. Pelvic pain, unusual discharge and urinary frequency are late features, making the other options less consistent with early disease.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Anatomy & Physiology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The primary outcome of the assessment component of the nursing process is;', 'Complete data base', 'Comprehensive system review.', 'Detailed nursing history', 'Nursing diagnosis.', 'A', 'The assessment phase of the nursing process produces a complete client database from which diagnoses are later formulated, per Kozier & Erb''s Fundamentals of Nursing. Nursing diagnosis (D) is the outcome of the separate diagnosis phase; system review and nursing history are components, not the overall outcome.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Anatomy & Physiology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Fracture immobilization is meant to achieve the following;', 'Pain relieve, reduced movement and correction of malunion', 'Prevention of displacement, pain relieve and reduced deformities.', 'Prevent muscle spasms, bone alignment and increased circulation.', 'Reduce malformations, restore circulation and relieve pain', 'B', 'Fracture immobilisation maintains reduction/alignment (prevents displacement), relieves pain and prevents deformity during healing, per Brunner & Suddarth''s Medical-Surgical Nursing. It does not correct existing malunion (A) nor increase circulation (C), so those options are wrong.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Anatomy & Physiology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The stratified epithelium lines the following;', 'Kidney tubules, buccal cavity and the throat.', 'Lungs, heart and inner lining of blood vessels.', 'Eye conjunctiva,vagina and oesophagus', 'Inner lining of blood vessels, buccal cavity and lungs.', 'C', 'Stratified squamous epithelium lines surfaces exposed to abrasion such as the conjunctiva, vagina and oesophagus, per anatomy and physiology texts. Kidney tubules, blood vessel lining (endothelium) and alveoli are lined by simple epithelium, so options A, B and D are wrong.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Anatomy & Physiology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A third degree burn involves;', 'The epidermis and a portion of the dermis.', 'Epidermis, upper dermis & a portion of deeper dermis.', 'Epidermis, entire dermis, subcutaneous & connective tissue.', 'Muscles and the bones only c+d.', 'C', 'A third-degree (full-thickness) burn destroys the epidermis and the entire dermis, extending into subcutaneous and connective tissue, per Brunner & Suddarth''s Medical-Surgical Nursing. Options A and B describe superficial/partial-thickness burns, and D (muscle/bone) describes a fourth-degree burn.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Anatomy & Physiology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The common causative bacterial pathogens for otitis media are;', 'Staphylococcus aureus, pneumococci.', 'Klebsiella spp., pseudomonas spp.', 'Staphylococcus aureus, pseudomonas spp.', 'Streptococcus spp. Neisseria menengitidis', 'A', 'The commonest bacterial causes of acute otitis media are Streptococcus pneumoniae (pneumococci), Haemophilus influenzae and Moraxella catarrhalis, per Kenya Basic Paediatric Protocols/ENT references; of the listed choices only option A includes pneumococci, making it the least-wrong answer. No option lists the classic triad and S. aureus is a minor cause, so the item is imperfect.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Anatomy & Physiology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The stages of urine formation are in the order of:-', 'Filtration, urine concentration, secretion and reabsorption.', 'Secretion, urine concentration, filtration and reabsorption.', 'Filtration, reabsorption, secretion and urine concentration.', 'Urine concentration, filtration, secretion and reabsorption.', 'C', 'Urine formation proceeds as glomerular filtration, tubular reabsorption, tubular secretion, and finally concentration in the collecting duct, per anatomy and physiology texts. The other sequences place secretion or concentration before filtration, which is physiologically impossible.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Anatomy & Physiology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('While caring for a patient in the recovery room after an operation under general anaesthesia, the nurse should notify the physician if the;', 'Patient pushes out the airway.', 'Respiration is regular but shallow.', 'Systolic pressure drops from 130mmhg to 100mmhg.', 'Patient has snoring respirations.', 'C', 'A 30 mmHg fall in systolic pressure (130 to 100) in the post-anaesthesia recovery room signals possible hypovolaemia/haemorrhage or shock and must be reported to the physician, per Brunner & Suddarth''s post-anaesthesia care. Pushed-out airway, snoring and shallow respiration (A, B, D) are airway issues managed at the bedside by repositioning/stimulation.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Anatomy & Physiology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Contact dermatitis is initially suspected if the rash appears;', 'Erythematous with raised papules.', 'Dry & scaly flaking skin.', 'Inflamed with weeping and crusting lesion', 'Excoriated with multiple fissures.', 'A', 'Acute contact dermatitis initially presents with erythema and raised papules (progressing to vesicles) at the site of allergen/irritant contact, per Brunner & Suddarth''s dermatologic disorders. Dry scaly skin (B) and fissuring/excoriation (D) reflect chronic eczematous change, and weeping/crusting (C) is a later exudative stage rather than the initial rash.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Anatomy & Physiology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Prior craniotomy the nurse should;', 'Rule out facial oedema, shave the surgical site & restrict fluid intake.', 'Ensure the patient is on antiseizures, shave the head & stop all other medications.', 'Rule out neurological deficits, ensure patient is well hydrated and insert indwelling urinary catheter.', 'Relieve pain, obtain results for all investigations & restrict fluid intake.', 'A', 'Pre-craniotomy nursing includes assessing for facial/periorbital oedema, shaving/preparing the surgical site and restricting fluids to limit cerebral oedema and raised ICP, per Brunner & Suddarth''s neurosurgical nursing. Stopping all other medications (B), and routine indwelling catheter with liberal hydration (C) are not standard preparation.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Anatomy & Physiology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('To assess the level of consciousness using the Glasgow coma scale, the nurse should check;', 'Pupil size, orientation and muscle tone.', 'Eye opening, motor and verbal response.', 'Grasp strength, pupil size and response to commands.', 'Flexing of limbs, muscle strength and orientation.', 'B', 'The Glasgow Coma Scale scores three components: best eye-opening, best verbal response and best motor response, per Brunner & Suddarth''s neurological assessment. Pupil size, muscle tone, grasp strength and orientation (A, C, D) are separate neuro assessments, not GCS parameters.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Anatomy & Physiology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The 24 hr urine collection is meant for the following investigations;', 'Glomerula filtration rate and creatinine clearance.', 'Blood urea nitrogen (BUN) and conjugated bilirubin levels determination.', 'Analysis of adrenaline metabolite levels and blood urea nitrogen (BUN).', 'Glomerula filtration rate (GFR) and serum potassium levels.', 'A', 'A 24-hour timed urine collection is used to measure creatinine clearance, which estimates glomerular filtration rate, per Brunner & Suddarth''s renal function tests. BUN, conjugated bilirubin and serum potassium (B, C, D) are blood tests, and adrenaline metabolites (VMA) are a niche urine test not paired correctly here.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Anatomy & Physiology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Clinical manifestations of retinal detachment include;', 'Pain, luminous rays and floaters in the field of vision.', 'Painless changes in vision, flashing lights & floaters in field of vision.', 'Pain in the affected eye, headache & reduced visual acuity for near objects.', 'Painless changes in vision, excessive lacrimation & photophobia.', 'B', 'Retinal detachment is classically painless and presents with sudden flashing lights (photopsia), floaters and a curtain/shadow over the visual field, per Brunner & Suddarth''s retinal disorders. Pain (options A and C) is not a feature, and excessive lacrimation/photophobia (D) suggest other ocular conditions.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Anatomy & Physiology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The three major factors associated with increased risk of pancreatic carcinoma are:-', 'Diabetes mellitus,obesity,high protein diet', 'Obesity,hypertension,age 35 - 40 years', 'Hypertension, tobacco use, age 35 – 40 years', 'Diabetes mellitus, tobacco use, high fat diet', 'D', 'Established major risk factors for pancreatic carcinoma include diabetes mellitus, cigarette (tobacco) smoking and a high-fat diet, per Brunner & Suddarth''s oncology. Age 35-40 is too young (risk rises after 60), excluding options B and C, and high-protein diet (A) is not an established risk.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Anatomy & Physiology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('During thoracocentesis', 'Fluid is aspirated from the peritoneal space', 'Consent is not necessary', 'Medications can be instilled into the pleural space', 'Local anaesthesia is not advisable', 'C', 'Thoracocentesis aspirates fluid from the pleural space and can also be used to instil medications (e.g. sclerosing or chemotherapeutic agents) into the pleural space, per Brunner & Suddarth''s respiratory procedures. Fluid is pleural not peritoneal (A), and both informed consent and local anaesthesia are required, making B and D wrong.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Anatomy & Physiology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When preparing a patient for barium enema, the nurse will inform the patient that:-', 'He should take the radio-opaque substance orally a day before the procedure', 'Nothing should be taken orally after midnight', '‘The procedure will take 2-4 hours', 'An evacuating enema or laxative will not be necessary after the procedure', 'B', 'For a barium enema the bowel must be empty, so the patient is kept NPO after midnight (with bowel prep) before the procedure, per Brunner & Suddarth''s GI diagnostic studies. Barium is given per rectum not orally (A), and a laxative IS required afterwards to clear retained barium (D is wrong).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Anatomy & Physiology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A potential nursing diagnosis for a patient with breast cancer is:-', 'Potential for pain related to surgical incision as evidenced by irritability', 'Disturbed body image related to loss of part or all of the breast', 'Potential for impaired mobility related to shoulder immobility', 'Anxiety related to fear of cancer as manifested by difficulty in falling asleep', 'B', '''Disturbed body image related to loss of part or all of the breast'' is a correctly constructed nursing diagnosis for breast cancer/mastectomy, per NANDA and Brunner & Suddarth''s. The other options mix a ''potential/risk'' label with defining characteristics (''as evidenced by''), which is structurally incorrect for a risk diagnosis.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Anatomy & Physiology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Relaxation of the intercostals muscles and diaphragm results in:-', 'Downward and outward movement of the rib cage and elastic recoil of the lungs', 'Upward and inward movement of the ribcage and elastic recoil of the lungs', 'Downward and inward movement of the rib cage and elastic recoil of the lungs', 'Enlargement of the thoracic cavity from back to front', 'C', 'During expiration the intercostal muscles and diaphragm relax, the rib cage moves downward and inward, and the lungs recoil elastically, reducing thoracic volume, per respiratory physiology (Guyton/Brunner & Suddarth''s). Enlargement of the thoracic cavity (D) and outward rib movement (A) occur on inspiration, not relaxation.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Anatomy & Physiology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The appropriate intervention in decreasing absorption of an ingested poison is:-', 'Performing haemodialysis', 'Administering milk', 'Performing gastric lavage', 'Administering activated charcoal', 'D', 'Activated charcoal adsorbs many ingested poisons in the gut and decreases their absorption, per Kenya MOH/WHO poisoning guidelines and Brunner & Suddarth''s. Haemodialysis removes already-absorbed toxin, gastric lavage physically removes rather than binds poison, and milk is not an effective decontaminant.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Anatomy & Physiology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The drug that would be used to control oedema of the spinal cord in a patient with a spinal cord injury at level T12 is:-', 'Acetazolamide', 'Furosemide', 'Methylpredinsolone', 'Sodium bicarbonate', 'C', 'High-dose methylprednisolone (a corticosteroid) is used to reduce oedema/inflammation of the cord after acute spinal cord injury, per Brunner & Suddarth''s spinal cord injury management. Furosemide and acetazolamide (A, B) are diuretics, and sodium bicarbonate (D) corrects acidosis; none targets cord oedema.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Anatomy & Physiology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A patient with Angina Pectoris manifests with:-', 'An acute onset of dyspnea and pleuritic chest pain', 'Severe crushing chest pain that is not relieved by nitroglycerin', 'Pressure in the chest that is relieved by morphine sulphate', 'Substernal chest pain that is usually accompanied by diaphoresis', 'D', 'Angina pectoris presents as substernal chest pain/pressure usually accompanied by diaphoresis, provoked by exertion and relieved by rest or nitroglycerin, per Brunner & Suddarth''s coronary artery disease. Pain NOT relieved by nitroglycerin (B) indicates myocardial infarction, and acute dyspnoea with pleuritic pain (A) is non-cardiac.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Anatomy & Physiology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Fluid filled blisters that are greater than 0.5cm in diameter are referred to as:-', 'Macules', 'Vesicles', 'Papules', 'Bullae', 'D', 'A bulla is a fluid-filled blister greater than 0.5 cm in diameter, whereas a vesicle is the same lesion 0.5 cm or smaller, per Brunner & Suddarth''s integumentary assessment. Macules are flat non-palpable and papules are solid raised lesions, so neither is fluid-filled.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Anatomy & Physiology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Chemosis is;', 'Seeing one object as two', 'Oedema of the conjunctiva', 'Dilatation of the vasculature of the conjunctiva', 'Presence of blood in the anterior chamber of the eye', 'B', 'Chemosis is swelling (oedema) of the conjunctiva, per Brunner & Suddarth''s ophthalmic assessment. Seeing one object as two is diplopia (A), conjunctival vascular dilatation is injection/hyperaemia (C), and blood in the anterior chamber is hyphaema (D).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Anatomy & Physiology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Principle of ethics in Midwifery autonomy means', 'Self governance', 'Voluntary agreement', 'Greaetest good', 'Involuntary agreement', 'A', 'Autonomy is the ethical principle of self-governance — respecting the client''s right to make her own informed decisions (Kozier Fundamentals of Nursing; ICM Code of Ethics for Midwives). ''Voluntary agreement'' describes consent, and ''greatest good'' describes utilitarian beneficence, so they are distractors. Self-governance is the direct definition of autonomy.', 'BScN', 'Paper II', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Principle of ethics in midwifery Beneficience means', 'Duty to do no harm', 'Truth telling', 'Duty to do good', 'Duty to make up for a good', 'C', 'Beneficence is the ethical duty to do good and act in the client''s best interest (Kozier Fundamentals of Nursing). ''Duty to do no harm'' is non-maleficence and ''truth telling'' is veracity, so those options are wrong. ''Duty to do good'' is the correct definition.', 'BScN', 'Paper II', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Components of the reproductive health include', 'Management of infertility', 'Essential obstretic care', 'Post abortion care', 'Clean and safe deliveries', 'A', 'Management of infertility is a recognised distinct component/pillar of comprehensive reproductive health services (Kenya National Reproductive Health Policy; WHO RH framework). The other options (essential obstetric care, post-abortion care, clean/safe deliveries) are safe-motherhood activities that fall under the maternal-health pillar, so infertility management is the uniquely listed RH component intended. The stem is loosely worded but option A best fits the ''component of reproductive health'' framing.', 'BScN', 'Paper II', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Set measures, procedures or practices to assess performance in the provision of the services.', 'Standards', 'Documents', 'Manual', 'Care plan', 'A', 'Standards are the established set measures, procedures or practices used to assess and benchmark performance/quality in service provision (Kenya MOH quality-of-care framework; nursing management). A care plan guides individual patient care, a manual and documents are supporting records, so they do not define benchmark measures. Option A is correct.', 'BScN', 'Paper II', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('An official statement issued by the government, a company or an non-governmental organization to guide the workers on what to do.', 'Policy', 'Guidelines', 'Standards', 'Documents', 'A', 'A policy is an official statement issued by a government, company or NGO to guide workers on what to do (Kenya health policy framework; nursing management). Guidelines and standards operationalise a policy, and documents is a generic term, so the overarching directive statement is a policy. Option A is correct.', 'BScN', 'Paper II', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Factors that can cause people to deviate from their values.', 'Education pressure, experiment else’s values, personal gain, rebel to get attention', 'Peer pressure, experiment else’s values, family gain, rebel to gain attention', 'Peer pressure, experiment else’s values, personal gain, rebel to gain attention', 'Peer pressure, experiment else’s values, personal gain, rebel to loose attention', 'C', 'Factors that cause people to deviate from their values include peer pressure, experimenting with others'' values, personal gain and rebelling to gain attention (adolescent/life-skills health education). Options A (''education pressure''), B (''family gain'') and D (''lose attention'') each corrupt one correct element. Option C states all four correctly.', 'BScN', 'Paper II', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Assertiveness, which means', 'Lack confident and not able to make a stand on their words, action or beliefs', 'Being confident and not able to make and stand with their words, action or believes', 'Lack confidentand able to make and stand on their word, actions and beliefs', 'Being confident and able to make a stand on their word, actions or beliefs', 'D', 'Assertiveness is being confident and able to make and stand by one''s own words, actions or beliefs while respecting others (life-skills; mental health nursing). Options A and C begin with ''lack confidence'' and option B negates (''not able to make a stand''), so they describe non-assertiveness. Option D is the correct positive definition.', 'BScN', 'Paper II', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Some poor life descision young people make.', 'Practice of unprotected sex, Crime, lack of drug abuse', 'Practice of unprotected sex, Crime, Drug abuse', 'Abstinence from sex, Crime, drug abuse', 'Practice of unprotected sex, not being involved in Crime, Drug Abuse', 'B', 'Poor life decisions young people may make include practising unprotected sex, engaging in crime and drug abuse (adolescent reproductive health). Option A says ''lack of drug abuse'', option C says ''abstinence from sex'', and option D says ''not being involved in crime'' — each negates a poor decision. Option B correctly lists three genuinely poor decisions.', 'BScN', 'Paper II', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What are the community and government interventions to improve the health of young people?', 'Youth friendly and accessible RH services, education, advocate theneed for informed choice and privacy', 'Youth friendly and inaccessible RH services, education, avocate theneed for informed choice and privacy', 'Youth friendly and inaccessible RH services, education, advocate lack of informed choice and privacy', 'Youth unfriendly and accessible RH services, education, advocate uninformed choice and privacy.', 'A', 'Community/government interventions to improve youth health provide youth-friendly and accessible RH services, education, and advocate for informed choice and privacy (Kenya Adolescent Reproductive Health policy). Options B/C/D introduce negations (''inaccessible'', ''lack of informed choice'', ''unfriendly'', ''uninformed choice''). Option A is the only fully positive, correct statement.', 'BScN', 'Paper II', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The aim of safe motherhood is to gradually reduce death rates through intersectional collaboration efforts. The millennium Development goals 4,5 and 6 are closely follow up in order include.', 'Improve maternal health, reduced child mortality,combat HIV/AIDs, malaria', 'Reduce child mortality, improve maternal health, combat HIV/AIDs, Malaria', 'Reduced child mortality, Combat HIV/AIDS, Malaria, improve maternal health', 'Improve maternal health, Combat HIV/AIDS, Malaria, Reduce child mortality', 'B', 'The Millennium Development Goals in numeric order are MDG 4 (reduce child mortality), MDG 5 (improve maternal health) and MDG 6 (combat HIV/AIDS, malaria and other diseases); the stem asks for goals 4,5,6 ''in order'' (UN Millennium Development Goals). Option B follows this exact sequence, whereas the other options reorder the goals. Option B is correct.', 'BScN', 'Paper II', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Maternal and perinatal death reviews have resulted into improved quality of maternal and perinatal services as a reflected by:', 'Reduction in neonatal mortality', 'Reduction in maternal mortality', 'Increase in maternal mortality', 'Increased in maternal mortality', 'B', 'Maternal and perinatal death surveillance and response (MPDSR) audits improve quality of care, reflected by a reduction in maternal mortality (Kenya MPDSR guidelines). Options C and D describe an increase in mortality, which would indicate failure rather than improvement, and option A (neonatal) is not the maternal indicator emphasised. Option B is correct.', 'BScN', 'Paper II', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Informed Choice include the following except', 'Disclosure of information', 'Comprehension', 'Involuntary agreement', 'Competency to make decision', 'C', 'Informed choice/consent requires disclosure of information, comprehension, competency to decide and VOLUNTARY agreement (Kozier Fundamentals of Nursing; ICM ethics). ''Involuntary agreement'' contradicts the free/voluntary nature of consent, so it is the correct ''except'' answer. Options A, B and D are genuine elements of informed choice.', 'BScN', 'Paper II', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('International code of ethics for midwife (ICM) include the following', 'Respect, equity, trust, justice', 'Injustice, respect, equity, trust', 'Inequity, injustice, respect, trust', 'Mistrust, injustice, respect, equity', 'A', 'The ICM International Code of Ethics for Midwives is grounded in positive values such as respect, equity, trust and justice (ICM Code of Ethics for Midwives). Options B/C/D each contain a negative term (injustice, inequity, mistrust) that cannot belong to a code of ethics. Option A lists only positive ethical values and is correct.', 'BScN', 'Paper II', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('One of the following is a guiding principle into the maternal death review process.', 'The focus should be on individuals and not on the health facility system.', 'The meeting is primarily an educational experience.', 'The meeting is a team building and disciplinary learning.', 'Reviewing documentation of patients notes is not the main source of information.', 'B', 'A guiding principle of the Maternal Death Review (MDR) process is that it is a confidential, blame-free exercise that is PRIMARILY an educational/learning experience aimed at system improvement (Kenya MOH Maternal and Perinatal Death Surveillance and Response guidelines) - option B. It should focus on the health-system/facility rather than blaming individuals (contradicting A), it is not disciplinary (contradicting C), and review of patient case notes IS a main source of information (contradicting D).', 'BScN', 'Paper II', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following best describes the function of a health systems manager?', 'Direct patient care', 'Strategic planning and decision making', 'Diagnostic testing', 'Medication administration', 'B', 'A health systems manager works at the organisational level on strategic planning, governance and decision-making, not hands-on clinical tasks. Per the WHO health systems building blocks (leadership/governance) as applied in Kenya''s health management curriculum, direct care, diagnostics and medication administration are clinician roles, so B is correct.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the primary purpose of health information systems in a healthcare organization?', 'To provide direct patient care', 'To collect and manage data for informed decision-making', 'To perform surgical procedures', 'To dispense medications', 'B', 'Health Information Systems (HIS) are a WHO health-system building block whose purpose is to generate, collect, analyse and manage reliable data for evidence-based decision-making (e.g. Kenya DHIS2). They are not for direct care, surgery or dispensing, so B is correct.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following strategies is most effective in improving patient safety within a healthcare system?', 'Increasing the number of staff', 'Implementing electronic health records (EHR)', 'Extending hospital visiting hours', 'Reducing patient-staff interaction', 'B', 'Electronic health records improve patient safety by reducing transcription and medication errors, ensuring complete accessible records and providing clinical decision support, consistent with WHO/Kenya digital health and quality-of-care strategy. Merely adding staff or extending hours does not systematically address safety, so B is correct.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the role of a health systems manager in managing healthcare costs?', 'Increasing patient fees', 'Reducing staff salaries', 'Ensuring efficient resource allocation', 'Limiting patient admissions', 'C', 'Cost management in health systems means efficient allocation of finite resources (WHO financing building block), not blunt cost-cutting. Raising fees, cutting salaries or limiting admissions harm access and quality, so C (ensuring efficient resource allocation) is correct.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following is an essential component of a successful health system?', 'High patient turnover', 'Effective leadership and governance', 'Limited access to care', 'High staff attrition rates', 'B', 'Leadership and governance is one of the WHO six health-system building blocks and the foundation of a well-functioning system, as adopted in Kenya''s Health Sector Strategic Plan. High patient turnover, limited access and high staff attrition are markers of system failure, not essential components.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('How can health systems managers improve healthcare quality?', 'By reducing the number of healthcare providers', 'By implementing continuous quality improvement programs', 'By limiting patient access to services', 'By increasing the length of hospital stays', 'B', 'Continuous Quality Improvement (CQI) is the established systematic method for raising healthcare quality per the Kenya MOH Quality Improvement framework and WHO. Reducing providers, limiting access or prolonging stays worsen quality and are inappropriate distractors.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the significance of patient-centered care in health systems management?', 'It reduces the workload of healthcare providers', 'It increases patient satisfaction and outcomes', 'It limits the responsibilities of healthcare managers', 'It decreases the need for healthcare services', 'B', 'Patient-centred care is a recognised dimension of quality (IOM/WHO) that improves satisfaction, adherence and clinical outcomes, and is central to Kenya''s people-centred UHC agenda. It does not reduce provider workload or overall need for services.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following is a key principle of health systems management?', 'Centralized decision-making', 'Patient autonomy', 'Equitable access to care', 'Limiting health services to reduce costs', 'C', 'Equitable access to care is a foundational principle of health systems management and Kenya''s UHC agenda (WHO). Centralized decision-making is a management style, patient autonomy is a clinical-ethics principle, and rationing services to cut costs contradicts equity, so none is the defining HSM principle.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('How does effective communication impact health systems management?', 'It increases patient complaints', 'It improves coordination and collaboration among healthcare providers', 'It delays the implementation of healthcare policies', 'It reduces the need for staff training', 'B', 'Effective communication strengthens teamwork, coordination and collaboration among providers, a core competency in WHO patient-safety and Kenya HSM guidance. It reduces complaints and errors rather than increasing them or delaying policy.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the role of performance measurement in health systems management?', 'To punish underperforming staff', 'To provide feedback and guide improvements', 'To limit patient access to care', 'To increase healthcare costs', 'B', 'Performance measurement provides objective feedback that guides quality improvement and management decisions, per Kenya MOH M&E and CQI frameworks. Its purpose is improvement, not punishing staff or rationing care.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following is a benefit of integrating health services?', 'Increased healthcare costs', 'Improved coordination and continuity of care', 'Reduced access to specialized services', 'Increased administrative workload', 'B', 'Integrating health services improves coordination and continuity of care across levels, a central aim of Kenya''s integrated service delivery and UHC (WHO). It reduces, not raises, duplication, costs and administrative burden.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the purpose of health policy development in health systems management?', 'To increase bureaucratic procedures', 'To guide decision-making and resource allocation', 'To limit healthcare innovation', 'To reduce patient engagement', 'B', 'Health policy development provides the framework guiding decision-making and resource allocation, per the Kenya Health Policy 2014-2030 and the WHO governance building block. It is not intended to add bureaucracy, stifle innovation or reduce engagement.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('How can health systems managers address health disparities?', 'By ignoring socioeconomic factors', 'By implementing targeted interventions and programs', 'By limiting healthcare access for minority groups', 'By reducing healthcare funding', 'B', 'Health disparities are reduced through targeted, equity-focused interventions addressing social determinants, consistent with Kenya''s UHC and health-equity strategy (WHO). Ignoring socioeconomic factors or cutting access widens disparities.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following best describes the importance of health workforce planning?', 'Ensuring a sufficient number of healthcare providers to meet patient needs', 'Reducing the cost of healthcare education', 'Limiting the number of healthcare professionals', 'Increasing administrative burden', 'A', 'Health workforce planning (a WHO building block) ensures a sufficient, well-distributed workforce to meet population health needs, central to Kenya''s Human Resources for Health strategy. Reducing education costs, limiting professionals or adding administrative burden are not its purpose.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the impact of healthcare technology on health systems management?', 'It complicates healthcare delivery', 'It enhances efficiency and quality of care', 'It increases the risk of medical errors', 'It reduces patient satisfaction', 'B', 'Appropriately implemented health technology enhances efficiency and quality of care, per the Kenya Digital Health strategy and WHO. Framing technology as inherently complicating, error-prone or dissatisfying is incorrect when implemented well.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following is a key challenge in health systems management?', 'Overabundance of resources', 'Limited financial resources and budget constraints', 'High levels of patient satisfaction', 'Excessive healthcare access', 'B', 'Limited financial resources and budget constraints are a key, well-recognised HSM challenge, especially in Kenya''s resource-limited setting (WHO financing building block). Overabundance of resources, high satisfaction and excessive access describe favourable conditions, not challenges.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('How does health systems management contribute to public health?', 'By focusing solely on individual patient care', 'By implementing policies and programs that address population health needs', 'By reducing the scope of public health initiatives', 'By limiting the role of healthcare providers in community health', 'B', 'HSM contributes to public health by implementing policies and programs that address population-level health needs, aligned with Kenya''s population-based UHC approach (WHO). A sole focus on individual care neglects the public-health mandate.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the role of accreditation in health systems management?', 'To increase healthcare costs', 'To ensure healthcare organizations meet established standards of quality and safety', 'To reduce the number of healthcare providers', 'To limit patient access to care', 'B', 'Accreditation verifies that healthcare organizations meet established quality and safety standards, e.g. the Kenya Quality Model for Health (KQMH) and MOH standards. It is not designed to raise costs, cut providers or restrict access.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following is an effective strategy for managing healthcare resources?', 'Overstaffing healthcare facilities', 'Implementing resource allocation frameworks', 'Limiting the use of healthcare technology', 'Reducing staff training and development', 'B', 'Effective resource management uses structured resource allocation frameworks to match resources to needs (WHO financing/stewardship). Overstaffing, limiting technology or cutting training are inefficient or harmful.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the significance of patient satisfaction surveys in health systems management?', 'They reduce the need for quality improvement', 'They provide feedback for improving healthcare services', 'They increase administrative workload', 'They limit patient engagement in care', 'B', 'Patient satisfaction surveys are a feedback tool that drives quality improvement, per the Kenya MOH client-satisfaction/CQI approach. They inform rather than replace QI and enhance patient engagement.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('How does financial management impact health systems management?', 'It focuses only on patient care', 'It ensures sustainable operations and resource allocation', 'It reduces the need for strategic planning', 'It limits healthcare innovation', 'B', 'Financial management ensures sustainable operations and sound resource allocation, per the WHO financing building block and Kenya HSM. It underpins, rather than replaces, strategic planning and does not limit innovation.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the purpose of strategic planning in health systems management?', 'To respond reactively to immediate issues', 'To set long-term goals and outline steps to achieve them', 'To limit healthcare services', 'To increase patient complaints', 'B', 'Strategic planning sets long-term goals and outlines the steps to achieve them, per Kenya MOH strategic plans and management theory. It is proactive rather than merely reactive to immediate issues.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following is a primary focus of quality improvement initiatives in healthcare?', 'Increasing patient fees', 'Enhancing patient outcomes and satisfaction', 'Reducing staff numbers', 'Limiting access to healthcare services', 'B', 'Quality improvement initiatives primarily aim to enhance patient outcomes and satisfaction, per the Kenya MOH QI framework and WHO quality dimensions. Raising fees, cutting staff or limiting access are not QI goals.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('How can health systems managers address the challenge of healthcare disparities?', 'By ignoring minority health needs', 'By developing culturally competent care practices', 'By reducing healthcare access for disadvantaged groups', 'By limiting community health initiatives', 'B', 'Developing culturally competent care practices reduces disparities by tailoring care to diverse populations, aligned with Kenya''s equity-focused, people-centred UHC (WHO). Ignoring minority needs or cutting access worsens disparities.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the impact of regulatory compliance on health systems management?', 'It complicates healthcare delivery', 'It ensures adherence to standards and enhances patient safety', 'It limits innovation in healthcare', 'It reduces healthcare quality', 'B', 'Regulatory compliance ensures adherence to standards and enhances patient safety, per NCK, MOH and Kenyan regulatory frameworks. It safeguards rather than degrades quality or innovation.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following is an essential skill for health systems managers?', 'Technical medical expertise', 'Leadership and interpersonal skills', 'Manual dexterity', 'Physical strength', 'B', 'Leadership and interpersonal skills are essential managerial competencies (WHO leadership/governance; management theory). Technical medical expertise, manual dexterity and physical strength are clinician attributes, not the defining HSM skill.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the purpose of benchmarking in health systems management?', 'To increase patient wait times', 'To compare performance against best practices and standards', 'To limit healthcare services', 'To reduce staff morale', 'B', 'Benchmarking compares organizational performance against best practices and standards to drive improvement, a CQI/management-theory tool applied in Kenya HSM. It is not intended to lengthen waits or lower morale.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('How can health systems managers promote a culture of safety in healthcare organizations?', 'By ignoring safety protocols', 'By encouraging open communication and reporting of errors', 'By reducing staff training', 'By limiting patient involvement in care', 'B', 'A culture of safety is built on open communication and non-punitive reporting of errors, per the WHO patient-safety framework and Kenya patient-safety guidance. Ignoring protocols, cutting training or limiting patient involvement undermine safety.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the role of health economics in health systems management?', 'To increase healthcare costs', 'To analyze and optimize the allocation of resources', 'To limit healthcare innovation', 'To reduce patient engagement', 'B', 'Health economics analyses costs and benefits to optimize resource allocation (WHO financing; health economics). Its aim is efficiency, not raising costs or limiting innovation.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following is a benefit of using electronic health records (EHR) in healthcare?', 'Increased medical errors', 'Improved accuracy and accessibility of patient information', 'Reduced patient engagement', 'Increased administrative burden', 'B', 'EHRs improve accuracy, legibility and accessibility of patient information, supporting safer coordinated care, per the Kenya Digital Health strategy and WHO. They reduce rather than increase errors and administrative burden.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the significance of risk management in health systems management?', 'To ignore potential risks', 'To identify, assess, and mitigate risks to patient safety and organizational stability', 'To increase healthcare costs', 'To limit healthcare services', 'B', 'Risk management systematically identifies, assesses and mitigates risks to patient safety and organizational stability (WHO patient-safety; Kenya HSM). Ignoring risks is the opposite of its purpose.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('How can health systems managers enhance staff performance and satisfaction?', 'By increasing workloads', 'By providing ongoing training and development opportunities', 'By limiting communication', 'By reducing staff involvement in decision-making', 'B', 'Ongoing training and development opportunities improve staff competence, performance and satisfaction, per the WHO workforce building block and Kenya HRH strategy. Increasing workloads or limiting participation reduce satisfaction.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the impact of patient education on health outcomes?', 'It decreases patient compliance with treatment plans', 'It empowers patients to make informed decisions about their care', 'It increases healthcare costs', 'It reduces the need for healthcare services', 'B', 'Patient education empowers informed decision-making and improves adherence and outcomes, per the Kenya MOH health-promotion approach and Kozier''s Fundamentals of Nursing. It increases rather than decreases compliance.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following is an effective approach to managing healthcare innovation?', 'Ignoring new technologies', 'Encouraging a culture of innovation and continuous improvement', 'Reducing investment in research and development', 'Limiting staff involvement in innovation initiatives', 'B', 'Managing healthcare innovation effectively means encouraging a culture of innovation and continuous improvement (management theory; WHO learning health systems). Ignoring new technologies or cutting R&D stifles innovation.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the role of collaboration in health systems management?', 'To increase competition among healthcare providers', 'To enhance coordination and efficiency in patient care', 'To limit patient access to care', 'To reduce the quality of healthcare services', 'B', 'Collaboration enhances coordination and efficiency in patient care, per WHO integrated people-centred services and Kenya HSM. It fosters teamwork rather than competition, restricted access or reduced quality.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following is a challenge in implementing health information technology?', 'Improved patient outcomes', 'High initial costs and resistance to change', 'Enhanced data security', 'Increased accessibility to patient information', 'B', 'The main barriers to implementing health information technology are high initial costs and staff resistance to change, per the Kenya eHealth Strategy and health informatics texts. Improved outcomes, enhanced security and increased accessibility are benefits, not challenges.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the purpose of healthcare accreditation programs?', 'To increase healthcare costs', 'To ensure organizations meet established quality and safety standards', 'To reduce the number of healthcare providers', 'To limit patient access to care', 'B', 'Healthcare accreditation programs exist to ensure organizations meet established quality and safety standards, per KQMH/KEPH quality standards and the Joint Commission model. They drive improvement, not increased costs or restricted access.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('How can health systems managers support evidence-based practice?', 'By disregarding clinical research', 'By promoting the use of best available evidence in clinical decision-making', 'By limiting access to medical journals', 'By reducing investment in staff education', 'B', 'Managers support evidence-based practice by promoting use of the best available evidence in clinical decision-making, per nursing research texts and MOH policy. Disregarding research or limiting access to journals contradicts EBP.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the role of data analytics in health systems management?', 'To reduce patient care quality', 'To provide insights for informed decision-making and performance improvement', 'To increase administrative workload', 'To limit healthcare innovation', 'B', 'Data analytics converts routine health data (e.g. DHIS2/KHIS) into insights that guide informed decisions and performance improvement in HSM. It supports rather than reduces quality or increases workload.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following strategies can improve healthcare access in rural areas?', 'Reducing healthcare services', 'Implementing telehealth services and mobile clinics', 'Limiting healthcare provider training', 'Increasing patient fees', 'B', 'Telehealth services and mobile clinics extend care to hard-to-reach rural populations, per Kenya''s UHC and Community Health Strategy. Reducing services, limiting training or raising fees would worsen rural access.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the significance of healthcare policy in health systems management?', 'It has no impact on healthcare delivery', 'It guides the legal and regulatory framework for healthcare practice', 'It increases patient wait times', 'It limits healthcare innovation', 'B', 'Healthcare policy guides the legal and regulatory framework for practice, e.g. the Kenya Health Policy 2014-2030 and Health Act 2017. It directs, rather than has no impact on, service delivery and does not exist to lengthen waits or limit innovation.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following is a key aspect of human resource management in healthcare?', 'Ignoring staff needs', 'Recruiting, training, and retaining qualified healthcare professionals', 'Limiting professional development opportunities', 'Reducing staff engagement', 'B', 'A key aspect of healthcare human resource management is recruiting, training and retaining qualified professionals, consistent with Kenya''s HRH strategy. Ignoring staff needs or limiting development undermines the workforce.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('How can health systems managers address the issue of healthcare fraud and abuse?', 'By ignoring fraudulent activities', 'By implementing robust compliance and monitoring programs', 'By reducing oversight', 'By limiting patient care', 'B', 'Healthcare fraud and abuse are controlled through robust compliance and monitoring programs, a core governance function in HSM. Ignoring fraud or reducing oversight would allow it to persist.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the role of leadership in health systems management?', 'To increase staff turnover', 'To inspire and guide the organization towards achieving its goals', 'To limit organizational growth', 'To reduce patient satisfaction', 'B', 'Leadership in HSM inspires and guides the organization toward achieving its goals, per nursing management/leadership theory. Increasing turnover, limiting growth or reducing satisfaction are outcomes of poor, not effective, leadership.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following is an effective method for managing healthcare costs?', 'Increasing patient fees', 'Implementing cost-effective care models and resource allocation', 'Reducing staff numbers', 'Limiting patient access to care', 'B', 'Effective cost management implements cost-effective care models and rational resource allocation, rather than shifting cost to patients or cutting staff. This aligns with WHO financing/stewardship and Kenya HSM principles.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('How can health systems managers ensure ethical decision-making in healthcare?', 'By disregarding ethical principles', 'By establishing and enforcing ethical guidelines and standards', 'By limiting patient involvement', 'By reducing staff training on ethics', 'B', 'Ethical decision-making is ensured by establishing and enforcing ethical guidelines and standards, aligned with the NCK Code of Ethics and Conduct for Nurses in Kenya. Disregarding principles or cutting ethics training undermines it.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the impact of workforce diversity on health systems management?', 'It reduces the quality of care', 'It enhances cultural competence and improves patient outcomes', 'It increases staff conflicts', 'It limits healthcare innovation', 'B', 'Workforce diversity enhances cultural competence and responsiveness to varied patient populations, improving outcomes. Framing diversity as reducing quality or increasing conflict is incorrect.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following is a benefit of interprofessional collaboration in healthcare?', 'Increased medical errors', 'Enhanced patient care through integrated services', 'Reduced efficiency', 'Limited innovation', 'B', 'Interprofessional collaboration enhances patient care through coordinated, integrated services and reduces errors, per WHO and Kenyan practice standards. Increased errors, reduced efficiency and limited innovation are the opposite of its benefits.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('How can health systems managers use performance metrics to improve healthcare quality?', 'By ignoring performance data', 'By regularly monitoring and analyzing key performance indicators', 'By reducing the use of performance metrics', 'By limiting staff involvement in quality improvement', 'B', 'Regular monitoring and analysis of key performance indicators (KPIs) is the core quality-improvement mechanism, allowing managers to identify performance gaps and drive corrective action per WHO health-systems performance and Kenya MOH quality-of-care frameworks. Ignoring or reducing use of performance data (A, C) and limiting staff involvement (D) directly undermine quality improvement.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the primary focus of health systems integration?', 'Increasing patient fees', 'Coordinating care across different healthcare settings', 'Limiting patient access to specialists', 'Reducing the quality of care', 'B', 'Health systems integration primarily aims to coordinate and link care across different settings and levels for continuity, consistent with Kenya''s tiered referral system and WHO integrated people-centred health services. Increasing fees (A), limiting specialist access (C) and reducing quality (D) contradict the purpose of integration.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('How does a health systems manager use SWOT analysis in strategic planning?', 'To ignore external threats', 'To identify strengths, weaknesses, opportunities, and threats', 'To increase organizational weaknesses', 'To limit strategic initiatives', 'B', 'SWOT analysis is a standard strategic-planning tool that assesses internal Strengths and Weaknesses and external Opportunities and Threats to inform strategy, per nursing management and leadership theory. Ignoring threats (A), increasing weaknesses (C) and limiting initiatives (D) are the opposite of what SWOT is designed to achieve.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('How can health systems managers improve emergency preparedness?', 'By ignoring potential disasters', 'By developing and regularly updating emergency response plans', 'By reducing staff training on emergency procedures', 'By limiting resources for emergency management', 'B', 'Emergency preparedness is improved by developing, drilling and regularly updating emergency/disaster response plans, consistent with WHO health emergency and Kenya MOH disaster-preparedness guidance. Ignoring disasters (A), reducing staff training (C) and limiting resources (D) weaken preparedness.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What role do health systems managers play in promoting health equity?', 'Ignoring disparities in care', 'Implementing policies that address social determinants of health', 'Limiting access to preventive services', 'Increasing healthcare costs for disadvantaged populations', 'B', 'Health equity is advanced by implementing policies that address the social determinants of health, aligned with WHO equity principles and Kenya''s UHC agenda. Ignoring disparities (A), limiting preventive services (C) and raising costs for disadvantaged groups (D) worsen inequity.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('How can health systems managers enhance patient safety culture?', 'By penalizing error reporting', 'By fostering an environment of transparency and learning', 'By reducing staff training on safety protocols', 'By limiting patient involvement in safety initiatives', 'B', 'A just, non-punitive culture of transparency and learning from errors strengthens patient safety, per WHO Patient Safety and Kenya MOH quality standards. Penalizing error reporting (A) suppresses disclosure, while reducing safety training (C) and limiting patient involvement (D) erode the safety culture.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the impact of telemedicine on health systems management?', 'It decreases access to care', 'It improves access to care for remote and underserved populations', 'It increases healthcare costs', 'It reduces patient engagement', 'B', 'Telemedicine improves access to care for remote and underserved populations, a key benefit supporting Kenya''s UHC and digital-health strategy. It does not inherently decrease access (A) or engagement (D), and by reducing travel it commonly lowers rather than raises overall costs (C).', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('How can health systems managers effectively manage change within healthcare organizations?', 'By ignoring staff concerns', 'By involving staff in the change process and providing support', 'By reducing communication about changes', 'By limiting resources for change initiatives', 'B', 'Effective change management (Lewin, Kotter) involves staff in the change process and provides support to reduce resistance and sustain change, per nursing leadership and management theory. Ignoring concerns (A), reducing communication (C) and limiting resources (D) increase resistance and failure.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the role of continuous quality improvement (CQI) in health systems management?', 'To increase healthcare costs', 'To continuously enhance care processes and outcomes', 'To limit access to care', 'To reduce patient satisfaction', 'B', 'Continuous quality improvement (CQI) is an ongoing cyclical effort (e.g. PDSA cycles) to continuously enhance care processes and patient outcomes, per WHO and Kenya MOH quality frameworks. Increasing costs (A), limiting access (C) and reducing satisfaction (D) are contrary to CQI''s purpose.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('How does health information exchange (HIE) benefit healthcare systems?', 'By reducing data security', 'By improving the sharing of patient information across providers', 'By limiting access to patient records', 'By increasing administrative workload', 'B', 'Health information exchange (HIE) improves the secure sharing of patient information across providers, enhancing continuity and coordination of care per WHO digital-health and Kenya HIS strategy. It is designed to enhance not reduce data security (A), broaden access (C), and streamline rather than increase administrative workload (D).', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the importance of clinical governance in health systems management?', 'To reduce the quality of care', 'To ensure accountability and improve clinical practice', 'To limit patient involvement in care', 'To increase healthcare costs', 'B', 'Clinical governance provides a framework to ensure accountability and continuously improve clinical practice, quality and safety, per WHO/MOH quality-of-care frameworks. Reducing quality (A), limiting patient involvement (C) and increasing costs (D) are not its aims.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('How can health systems managers support the mental health of healthcare staff?', 'By ignoring staff well-being', 'By providing mental health resources and support programs', 'By increasing workloads', 'By limiting staff communication', 'B', 'Staff mental health is supported by providing mental health resources and support programs (e.g. counselling, employee assistance programmes), sustaining workforce wellbeing per WHO workforce-wellbeing guidance. Ignoring wellbeing (A), increasing workloads (C) and limiting communication (D) worsen staff mental health.', 'BScN', 'Paper II', 'Mental Health Nursing', 'Mental Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the role of healthcare analytics in improving patient outcomes?', 'To increase patient confusion', 'To provide insights into treatment effectiveness and patient trends', 'To limit access to patient data', 'To reduce healthcare quality', 'B', 'Healthcare analytics provides insights into treatment effectiveness and patient/population trends, guiding decisions that improve outcomes, aligned with the WHO health-information-systems building block. It reduces rather than increases confusion (A) and supports rather than limits data use and quality (C, D).', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('How can health systems managers address the challenge of antimicrobial resistance (AMR)?', 'By overprescribing antibiotics', 'By implementing antimicrobial stewardship programs', 'By reducing infection control measures', 'By limiting patient education on AMR', 'B', 'Antimicrobial resistance is addressed by implementing antimicrobial stewardship programs, the core managerial strategy per Kenya''s National Action Plan on AMR and WHO guidance. Overprescribing antibiotics (A), reducing infection control (C) and limiting AMR education (D) accelerate resistance.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the significance of patient advocacy in health systems management?', 'To increase patient dissatisfaction', 'To ensure that patient rights and interests are represented', 'To limit patient involvement in care decisions', 'To reduce healthcare quality', 'B', 'Patient advocacy ensures that patients'' rights and interests are represented, a core professional nursing responsibility per the NCK Code of Conduct and Ethics. Increasing dissatisfaction (A), limiting involvement in decisions (C) and reducing quality (D) contradict advocacy.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('How can health systems managers enhance the sustainability of healthcare organizations?', 'By ignoring environmental impact', 'By implementing eco-friendly practices and resource management', 'By increasing waste generation', 'By limiting sustainability initiatives', 'B', 'Organizational sustainability is enhanced through eco-friendly practices and efficient resource/waste management, consistent with green-healthcare principles and IPC healthcare-waste guidelines. Ignoring environmental impact (A), increasing waste (C) and limiting sustainability initiatives (D) undermine sustainability.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the impact of value-based care on health systems management?', 'It increases healthcare costs without improving outcomes', 'It focuses on improving patient outcomes while controlling costs', 'It limits access to care', 'It reduces patient satisfaction', 'B', 'Value-based care focuses on improving patient outcomes while controlling costs, in contrast to fee-for-volume models, per WHO and modern health-financing principles. Options describing higher costs without benefit (A), limited access (C) and reduced satisfaction (D) are the opposite of value-based care.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('How can health systems managers address workforce shortages in healthcare?', 'By reducing recruitment efforts', 'By implementing retention strategies and promoting healthcare careers', 'By limiting professional development opportunities', 'By increasing staff workloads', 'B', 'Workforce shortages are addressed by implementing retention strategies and promoting healthcare careers, aligned with Kenya''s Human Resources for Health strategy and WHO workforce guidance. Reducing recruitment (A), limiting development (C) and increasing workloads (D) worsen shortages and attrition.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the role of patient engagement in health systems management?', 'To reduce patient satisfaction', 'To involve patients in their own care decisions', 'To increase healthcare costs', 'To limit patient access to information', 'B', 'Patient engagement means involving patients in their own care decisions, improving adherence and outcomes per patient-centred-care and WHO quality frameworks. Reducing satisfaction (A), increasing costs (C) and limiting access to information (D) contradict engagement.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('How can health systems managers use benchmarking to improve performance?', 'By ignoring industry standards', 'By comparing performance metrics with best practices', 'By limiting staff involvement in performance improvement', 'By reducing data analysis', 'B', 'Benchmarking compares an organization''s performance metrics against best practices and standards to identify improvement opportunities, a recognized quality-management technique. Ignoring standards (A), limiting staff involvement (C) and reducing data analysis (D) defeat the purpose of benchmarking.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the significance of health literacy in health systems management?', 'To increase patient confusion', 'To empower patients to make informed health decisions', 'To limit patient access to information', 'To reduce healthcare quality', 'B', 'Health literacy empowers patients to understand information and make informed health decisions, improving self-care and outcomes per WHO and Kenya MOH health-promotion guidance. Increasing confusion (A), limiting information (C) and reducing quality (D) are contrary to health literacy.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('How can health systems managers promote a culture of innovation in healthcare?', 'By discouraging new ideas', 'By encouraging creativity and supporting pilot projects', 'By limiting resources for innovation', 'By reducing staff involvement in innovation initiatives', 'B', 'A culture of innovation is fostered by encouraging creativity and supporting pilot projects, allowing safe testing of new ideas per management and leadership theory. Discouraging ideas (A), limiting resources (C) and reducing staff involvement (D) suppress innovation.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('How can health systems managers use predictive analytics to improve healthcare delivery?', 'By ignoring patient data', 'By forecasting patient outcomes and optimizing resource allocation', 'By reducing the use of data in decision-making', 'By limiting the application of analytical tools', 'B', 'Predictive analytics forecasts patient outcomes and service demand, enabling optimized resource allocation and proactive care delivery, aligned with the WHO health-information-systems building block. Ignoring patient data (A), reducing data use (C) and limiting analytical tools (D) negate its value.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the importance of regulatory compliance in health systems management?', 'To increase legal risks', 'To ensure adherence to laws and standards', 'To limit patient rights', 'To reduce the quality of care', 'B', 'Regulatory compliance ensures adherence to applicable laws and standards, reducing legal risk and protecting patients, per health-systems governance and Kenyan health law. Increasing legal risk (A), limiting patient rights (C) and reducing quality (D) are the harms compliance prevents.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('How can health systems managers enhance patient satisfaction?', 'By ignoring patient feedback', 'By actively seeking and addressing patient concerns', 'By increasing patient wait times', 'By limiting communication with patients', 'B', 'Patient satisfaction is enhanced by actively seeking and addressing patient concerns, a core continuous-quality-improvement practice per WHO/MOH quality frameworks. Ignoring feedback (A), increasing wait times (C) and limiting communication (D) reduce satisfaction.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the role of risk management in health systems management?', 'To ignore potential risks', 'To identify, assess, and mitigate risks to patient safety and organizational stability', 'To increase the likelihood of adverse events', 'To limit the use of safety protocols', 'B', 'Risk management systematically identifies, assesses and mitigates risks to patient safety and organizational stability, per WHO Patient Safety and clinical-governance frameworks. Ignoring risks (A), increasing adverse events (C) and limiting safety protocols (D) are contrary to its purpose.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('How can health systems managers promote the use of evidence-based practice (EBP)?', 'By ignoring research findings', 'By encouraging the integration of research evidence into clinical practice', 'By limiting access to scientific literature', 'By reducing professional development opportunities', 'B', 'Managers promote evidence-based practice by encouraging the integration of research evidence into clinical practice and improving access to literature, per EBP principles (Sackett) and NCK professional standards. Ignoring research (A), limiting literature access (C) and reducing professional development (D) obstruct EBP.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the impact of healthcare accreditation on health systems management?', 'It reduces the quality of care', 'It ensures adherence to quality standards and improves organizational performance', 'It increases legal risks', 'It limits access to care', 'B', 'Healthcare accreditation (e.g. Kenya''s KQMH/SafeCare standards) ensures adherence to quality standards and improves organizational performance as an external quality-assurance mechanism, per WHO/MOH quality frameworks. Reducing quality (A), increasing legal risk (C) and limiting access (D) are harms accreditation prevents.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the role of patient safety initiatives in health systems management?', 'To increase medical errors', 'To reduce the risk of harm to patients', 'To limit staff involvement in safety efforts', 'To reduce the quality of care', 'B', 'Patient safety initiatives aim to reduce the risk of harm to patients and prevent adverse events, a core pillar of quality care per WHO Patient Safety and Kenya MOH quality standards. Increasing errors (A), limiting staff involvement (C) and reducing quality (D) are opposite to their intent.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('How can health systems managers improve healthcare access for vulnerable populations?', 'By reducing healthcare services', 'By implementing outreach programs and community partnerships', 'By increasing patient fees', 'By limiting healthcare provider training', 'B', 'Access for vulnerable populations is improved by implementing outreach programs and community partnerships, consistent with Kenya''s Community Health Strategy and PHC/UHC agenda. Reducing services (A), increasing fees (C) and limiting provider training (D) reduce access.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the significance of operational efficiency in health systems management?', 'To increase healthcare costs', 'To optimize resource use and reduce waste', 'To limit patient access to care', 'To reduce the quality of care', 'B', 'Operational efficiency optimizes use of scarce resources and reduces waste, a key objective under the WHO health-systems building blocks and MOH stewardship. Increasing costs (A), limiting access (C) and reducing quality (D) reflect inefficiency, not efficiency.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('How can health systems managers support continuous professional development (CPD) for healthcare staff?', 'By limiting access to training opportunities', 'By providing ongoing education and skill development programs', 'By reducing professional growth initiatives', 'By ignoring staff training needs', 'B', 'Continuous professional development (CPD) is supported by providing ongoing education and skill-development programs; NCK mandates CPD points for licence renewal, making this a management responsibility. Limiting training (A), reducing growth initiatives (C) and ignoring training needs (D) undermine CPD.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the role of strategic alliances in health systems management?', 'To limit organizational growth', 'To foster collaboration and resource sharing among healthcare organizations', 'To reduce access to care', 'To increase operational inefficiencies', 'B', 'Strategic alliances foster collaboration and resource sharing among healthcare organizations, strengthening service delivery per health-systems management and WHO partnership principles. Limiting growth (A), reducing access (C) and increasing inefficiency (D) are the opposite of their intent.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('How can health systems managers use patient feedback to drive quality improvement?', 'By ignoring patient opinions', 'By analyzing feedback and implementing changes based on patient experiences', 'By reducing the collection of patient feedback', 'By limiting communication with patients', 'B', 'Patient feedback drives quality improvement when analyzed and acted upon by implementing changes based on patient experiences, a core CQI principle in MOH/WHO quality frameworks. Ignoring opinions (A), reducing feedback collection (C) and limiting communication (D) waste the feedback loop.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the significance of financial management in health systems management?', 'To increase financial instability', 'To ensure the financial sustainability and effective resource allocation', 'To limit access to financial resources', 'To reduce organizational performance', 'B', 'Financial management ensures financial sustainability and effective resource allocation, a WHO health-financing building block essential to health-systems management. Increasing instability (A), limiting resource access (C) and reducing performance (D) are contrary to sound financial management.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('How can health systems managers promote health education and literacy among patients?', 'By limiting patient access to information', 'By providing clear and accessible health information and educational resources', 'By ignoring patient education needs', 'By increasing healthcare jargon', 'B', 'Health education and literacy are promoted by providing clear, accessible health information and educational resources, a core health-promotion function per Kenya MOH and WHO. Limiting information (A), ignoring education needs (C) and increasing jargon (D) reduce comprehension.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the role of technology in improving healthcare outcomes?', 'To reduce the use of digital health tools', 'To enhance diagnostics, treatment, and patient monitoring through innovative solutions', 'To limit access to healthcare information', 'To increase the complexity of care delivery', 'B', 'Technology enhances diagnostics, treatment and patient monitoring through innovative solutions, a WHO health-systems building block (medical products and technologies) that improves outcomes. Reducing digital tools (A), limiting information access (C) and increasing complexity (D) are not its role.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('How can health systems managers ensure the integration of mental health services into primary care?', 'By separating mental health services from primary care', 'By promoting collaborative care models and interdisciplinary teams', 'By reducing funding for mental health services', 'By limiting mental health training for primary care providers', 'B', 'Integrating mental health into primary care relies on promoting collaborative care models and interdisciplinary teams, consistent with WHO mhGAP and Kenya''s Mental Health Policy. Separating services (A), reducing funding (C) and limiting provider training (D) obstruct integration.', 'BScN', 'Paper II', 'Mental Health Nursing', 'Mental Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the impact of organizational culture on health systems performance?', 'It decreases staff morale and performance', 'It influences staff engagement, patient satisfaction, and overall performance', 'It limits organizational growth', 'It reduces the quality of care', 'B', 'Organizational culture influences staff engagement, patient satisfaction and overall performance, per nursing leadership and management theory. A blanket claim that it decreases morale (A), limits growth (C) or reduces quality (D) is incorrect, since culture can be positive or negative depending on its attributes.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('How can health systems managers use data analytics to enhance decision-making?', 'By avoiding data-driven decisions', 'By analyzing data to identify trends, patterns, and areas for improvement', 'By reducing data collection efforts', 'By limiting the use of analytical tools', 'B', 'Data analytics enhances decision-making by analyzing data to identify trends, patterns and areas for improvement; evidence/information is a WHO health-systems building block (health information systems). Avoiding data-driven decisions (A), reducing data collection (C) and limiting analytical tools (D) weaken decision-making.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the role of leadership in managing change within health systems?', 'To resist change', 'To guide and support staff through transitions and foster a positive change environment', 'To limit staff involvement in change processes', 'To reduce communication about changes', 'B', 'Leadership in change guides and supports staff through transitions and fosters a positive change environment, consistent with Lewin/Kotter change-management theory in nursing leadership. Resisting change (A), limiting staff involvement (C) and reducing communication (D) are barriers, not leadership roles.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('How can health systems managers address the challenge of physician burnout?', 'By increasing workloads', 'By implementing support programs, reducing administrative burdens, and promoting work-life balance', 'By limiting professional development opportunities', 'By ignoring burnout symptoms', 'B', 'Burnout is addressed by implementing support programs, reducing administrative burdens and promoting work-life balance, per WHO workforce-wellbeing and organizational-health guidance. Increasing workloads (A), limiting professional development (C) and ignoring symptoms (D) worsen burnout.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the role of patient-centered care in health systems management?', 'To prioritize organizational needs over patient needs', 'To focus on delivering care that respects and responds to individual patient preferences and values', 'To limit patient involvement in care decisions', 'To reduce patient engagement', 'B', 'Patient-centered care focuses on delivering care that respects and responds to individual patient preferences and values, a core quality domain per the IOM/WHO quality framework adopted in Kenya. Prioritizing organizational over patient needs (A), limiting involvement (C) and reducing engagement (D) contradict it.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('How can health systems managers leverage community partnerships to improve health outcomes?', 'By reducing collaboration with community organizations', 'By working with community partners to address local health needs and promote preventive care', 'By limiting outreach efforts', 'By ignoring community health issues', 'B', 'Community partnerships work with local partners to address local health needs and promote preventive care, central to Kenya''s Community Health Strategy and PHC/UHC agenda. Reducing collaboration (A), limiting outreach (C) and ignoring community issues (D) undermine health outcomes.', 'BScN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the impact of electronic health records (EHRs) on health systems management?', 'To increase administrative burdens', 'To improve data accuracy, accessibility, and coordination of care', 'To reduce patient engagement', 'To limit information sharing', 'B', 'EHRs improve data accuracy, accessibility and coordination of care, directly supporting the WHO health-information-system building block and Kenya''s digital-health strategy. The distractors (increasing administrative burden, reducing engagement, limiting information sharing) describe the opposite of the intended benefits of health information technology.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('How can health systems managers ensure effective communication within their organization?', 'By limiting communication channels', 'By establishing clear communication protocols and fostering an open dialogue', 'By ignoring staff feedback', 'By reducing information sharing', 'B', 'Effective organizational communication requires clear, standardized protocols plus open, two-way dialogue, per nursing management and organizational-behaviour theory. Limiting channels, ignoring feedback, or reducing information sharing all impair communication and are therefore wrong.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the role of quality improvement (QI) initiatives in health systems management?', 'To ignore performance issues', 'To systematically enhance processes and outcomes through continuous evaluation and improvement', 'To reduce staff involvement in improvement efforts', 'To limit the application of best practices', 'B', 'Quality improvement systematically enhances processes and outcomes through continuous evaluation and iterative change (e.g. PDSA cycles), per MOH Kenya Quality Improvement frameworks. Ignoring performance, reducing staff involvement, or limiting best-practice use all contradict the purpose of QI.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('How can health systems managers address the challenges of health disparities in their communities?', 'By ignoring social and economic factors affecting health', 'By implementing strategies to reduce barriers and improve access to care for underserved populations', 'By increasing healthcare costs for disadvantaged groups', 'By limiting outreach programs', 'B', 'Health disparities are reduced by implementing strategies that lower barriers and improve access for underserved populations, consistent with Kenya''s Universal Health Coverage equity agenda. Ignoring social/economic determinants, raising costs for disadvantaged groups, or limiting outreach worsen disparities.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the primary purpose of strategic planning in health systems management?', 'To limit organizational growth', 'To outline long-term goals and define the path to achieve them', 'To reduce patient care quality', 'To ignore market trends', 'B', 'Strategic planning defines an organization''s long-term goals and the roadmap to achieve them, per nursing management and health-systems planning theory. It does not limit growth, reduce care quality, or ignore market trends, so those distractors are wrong.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('How can health systems managers use cost-benefit analysis to make decisions?', 'By ignoring financial implications', 'By comparing the costs of an intervention with its expected benefits to determine value', 'By increasing operational costs', 'By reducing the scope of analysis', 'B', 'Cost-benefit analysis compares the costs of an intervention with its expected benefits to determine value and guide resource allocation, a standard health-economics decision tool. Ignoring financial implications, increasing costs, or narrowing scope defeat the analysis and are incorrect.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the role of a health systems manager in crisis management?', 'To ignore potential crises', 'To develop and implement strategies for effective response and recovery', 'To reduce communication during crises', 'To limit the involvement of staff', 'B', 'In crisis/disaster management the manager''s role is to develop and implement strategies for effective response and recovery, per WHO and Kenya disaster-management/emergency-preparedness guidance. Ignoring crises, cutting communication, or limiting staff involvement undermine response and are wrong.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('How can health systems managers improve patient throughput in an emergency department?', 'By increasing patient wait times', 'By optimizing workflow and resource allocation to reduce delays', 'By limiting staff training', 'By ignoring patient flow data', 'B', 'Emergency-department throughput improves by optimizing workflow and resource allocation to reduce delays, per operations-management principles applied in health-systems management. Increasing wait times, limiting training, or ignoring flow data all worsen throughput.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the significance of stakeholder engagement in health systems management?', 'To limit input from key stakeholders', 'To incorporate feedback and perspectives from various stakeholders into decision-making processes', 'To reduce collaboration with external parties', 'To increase organizational silos', 'B', 'Stakeholder engagement incorporates feedback and perspectives from diverse stakeholders into decision-making, improving buy-in, legitimacy and outcomes, per governance and leadership theory. Limiting input, reducing collaboration, or increasing silos are the opposite of engagement.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('How can health systems managers address the challenge of high staff turnover?', 'By increasing staff workloads', 'By implementing retention strategies such as competitive compensation and professional development opportunities', 'By reducing staff engagement', 'By ignoring exit feedback', 'B', 'High staff turnover is countered by retention strategies such as competitive compensation and professional-development opportunities, per human-resource-management theory in nursing. Increasing workloads, reducing engagement, or ignoring exit feedback increase turnover and are wrong.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What role does patient-centered technology play in health systems management?', 'To reduce patient engagement', 'To enhance patient experience and communication through digital tools', 'To limit access to healthcare information', 'To increase administrative burden', 'B', 'Patient-centered technology enhances patient experience and communication through digital tools, supporting the WHO information/technology building block. Reducing engagement, limiting access to information, or increasing administrative burden contradict its purpose.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('How can health systems managers ensure the effective use of telemedicine?', 'By ignoring technological advancements', 'By integrating telemedicine into existing care models and ensuring access and usability', 'By limiting telemedicine services', 'By reducing training for telemedicine platforms', 'B', 'Effective telemedicine requires integrating it into existing care models while ensuring access and usability, per Kenya''s digital-health strategy and WHO guidance. Ignoring technology, limiting services, or reducing training prevent effective telemedicine and are wrong.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the impact of data security on health systems management?', 'To increase the risk of data breaches', 'To protect sensitive patient information and maintain trust', 'To limit access to electronic health records', 'To reduce compliance with regulations', 'B', 'Data security protects sensitive patient information and maintains trust, aligning with Kenya''s Data Protection Act (2019) and professional confidentiality duties. Increasing breach risk, limiting legitimate EHR access, or reducing regulatory compliance are harms, not impacts of good data security.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('How can health systems managers leverage financial incentives to improve performance?', 'By reducing financial rewards', 'By linking incentives to performance metrics and outcomes to motivate staff', 'By ignoring performance results', 'By limiting bonus opportunities', 'B', 'Financial incentives improve performance when linked to defined performance metrics and outcomes, motivating staff, per performance-management and motivation theory. Reducing rewards, ignoring results, or limiting bonuses would not leverage incentives and are wrong.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the role of benchmarking in enhancing healthcare service quality?', 'To ignore industry standards', 'To compare performance against best practices and identify areas for improvement', 'To reduce the use of quality measures', 'To limit data analysis', 'B', 'Benchmarking compares an organization''s performance against best practices/industry standards to identify areas for improvement, a standard continuous-quality-improvement method. Ignoring standards, reducing quality measures, or limiting data analysis are the opposite of benchmarking.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('How can health systems managers utilize patient outcome data to drive quality improvement?', 'By ignoring outcome measures', 'By analyzing data to identify trends and areas for enhancement', 'By reducing the focus on patient outcomes', 'By limiting the use of data in decision-making', 'B', 'Patient-outcome data drives quality improvement when analyzed to identify trends and areas for enhancement, per MOH quality-improvement and monitoring/evaluation frameworks. Ignoring outcome measures, reducing focus on outcomes, or limiting data use defeat data-driven QI.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the importance of having a comprehensive risk management plan in a healthcare organization?', 'To increase exposure to risks', 'To identify, assess, and mitigate potential risks to patient safety and organizational operations', 'To limit safety protocols', 'To reduce staff involvement in risk management', 'B', 'A comprehensive risk-management plan identifies, assesses and mitigates potential risks to patient safety and organizational operations, per patient-safety and clinical-governance standards. Increasing exposure, limiting safety protocols, or reducing staff involvement defeat the purpose.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('How can health systems managers foster interprofessional collaboration?', 'By promoting siloed work environments', 'By creating opportunities for teamwork and communication among different healthcare professionals', 'By limiting interaction between disciplines', 'By reducing joint training sessions', 'B', 'Interprofessional collaboration is fostered by creating opportunities for teamwork and communication among different professionals, per the WHO Framework for Interprofessional Education and Collaborative Practice. Promoting silos, limiting interaction, or reducing joint training block collaboration.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the role of patient experience surveys in health systems management?', 'To ignore patient feedback', 'To gather insights into patient perceptions and identify areas for service improvement', 'To limit patient involvement in care assessment', 'To reduce communication with patients', 'B', 'Patient-experience surveys gather insights into patient perceptions and identify areas for service improvement, a core QI feedback mechanism in MOH quality standards. Ignoring feedback, limiting patient involvement, or reducing communication contradict their purpose.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('How can health systems managers address the challenge of increasing healthcare costs?', 'By reducing the quality of care', 'By implementing cost-control measures and improving operational efficiency', 'By limiting patient access to services', 'By ignoring financial management', 'B', 'Rising healthcare costs are addressed by implementing cost-control measures and improving operational efficiency, per health-financing management principles, without sacrificing quality or access. Reducing care quality, limiting access, or ignoring financial management are unacceptable and wrong.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the significance of performance evaluations in health systems management?', 'To limit staff feedback', 'To assess staff performance, identify strengths and weaknesses, and guide professional development', 'To reduce accountability', 'To ignore performance metrics', 'B', 'Performance evaluations assess staff performance, identify strengths and weaknesses, and guide professional development, per human-resource-management theory in nursing leadership. Limiting feedback, reducing accountability, or ignoring metrics are the opposite of a sound appraisal system.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('How can health systems managers use patient flow data to improve hospital operations?', 'By ignoring patient flow trends', 'By analyzing data to optimize resource allocation and reduce bottlenecks', 'By increasing patient wait times', 'By limiting the use of flow data', 'B', 'Patient-flow data is used to optimize resource allocation and reduce bottlenecks, improving hospital operations per operations-management principles. Ignoring flow trends, increasing wait times, or limiting data use undermine operational efficiency.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the role of clinical pathways in health systems management?', 'To ignore evidence-based practices', 'To standardize care processes and improve patient outcomes through evidence-based protocols', 'To reduce adherence to best practices', 'To limit the use of clinical guidelines', 'B', 'Clinical pathways standardize care processes using evidence-based protocols to improve outcomes and reduce unwarranted variation, per quality-of-care and clinical-governance standards. Ignoring evidence, reducing adherence to best practice, or limiting guideline use defeat their function.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('How can health systems managers enhance patient safety culture within their organization?', 'By reducing safety training', 'By promoting a culture of transparency, accountability, and continuous learning', 'By limiting staff involvement in safety initiatives', 'By ignoring safety concerns', 'B', 'A patient-safety culture is enhanced by promoting transparency, accountability, and continuous learning (a just culture where errors are reported and learned from), per the WHO patient-safety framework reflected in Kenya''s Quality of Care guidelines. Reducing training, limiting involvement, or ignoring concerns weaken safety.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('How can health systems managers ensure compliance with healthcare regulations?', 'By ignoring regulatory requirements', 'By implementing policies and procedures that adhere to regulatory standards and conducting regular audits', 'By reducing staff training on regulations', 'By limiting compliance monitoring', 'B', 'Regulatory compliance is ensured by implementing policies and procedures aligned to regulatory standards and verifying adherence through regular audits, per Kenya HSM and quality-assurance principles. Ignoring requirements, reducing training, or limiting monitoring create non-compliance.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What role does patient advocacy play in health systems management?', 'To limit patient involvement in care decisions', 'To ensure that patient rights are protected and their voices are heard in care planning and decisionmaking', 'To reduce patient support services', 'To ignore patient feedback', 'B', 'Patient advocacy ensures patient rights are protected and their voices are heard in care planning and decision-making, consistent with the Kenya Patients'' Rights Charter and NCK professional ethics. Limiting involvement, reducing support services, or ignoring feedback are contrary to advocacy.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('How can health systems managers utilize workflow analysis to improve efficiency?', 'By ignoring workflow bottlenecks', 'By identifying and addressing inefficiencies and streamlining processes', 'By increasing administrative tasks', 'By reducing staff involvement in process improvement', 'B', 'Workflow analysis improves efficiency by identifying and addressing inefficiencies and streamlining processes, a core operations/HSM quality-improvement principle. Ignoring bottlenecks, increasing administrative tasks, or reducing staff involvement work against efficiency.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the impact of leadership development programs on health systems management?', 'To limit career growth opportunities', 'To enhance leadership skills, improve decision-making, and support organizational goals', 'To reduce staff engagement', 'To ignore leadership training', 'B', 'Leadership development programs enhance leadership skills, improve decision-making, and support organizational goals, per nursing leadership/management theory in HSM. Limiting career growth, reducing engagement, or ignoring training are opposite outcomes and therefore wrong.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('How can health systems managers address healthcare disparities through policy changes?', 'By ignoring social determinants of health', 'By implementing policies that address social determinants and promote equitable access to care', 'By limiting support for underserved populations', 'By reducing funding for equity initiatives', 'B', 'Healthcare disparities are reduced by policies that address social determinants of health and promote equitable access to care, consistent with Kenya''s UHC and health-equity policy goals. Ignoring determinants, limiting support, or cutting equity funding perpetuate disparities.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the role of patient navigation programs in health systems management?', 'To limit patient access to services', 'To assist patients in navigating the healthcare system and accessing necessary care and resources', 'To reduce patient engagement', 'To ignore care coordination', 'B', 'Patient navigation programs assist patients in navigating the healthcare system and accessing necessary care and resources, improving continuity and outcomes (HSM/care-coordination principle). Limiting access, reducing engagement, or ignoring coordination contradict the program''s purpose.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('How can health systems managers use risk stratification to improve patient care?', 'By ignoring patient risk levels', 'By categorizing patients based on their risk levels and tailoring interventions accordingly', 'By reducing the use of risk assessments', 'By limiting patient care planning', 'B', 'Risk stratification categorizes patients by risk level so interventions can be tailored accordingly, improving efficiency and outcomes (population-health/HSM principle). Ignoring risk levels, reducing assessments, or limiting care planning defeat the approach.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the impact of healthcare mergers and acquisitions on health systems management?', 'To increase operational complexity and integration challenges', 'To consolidate resources and enhance service delivery', 'To reduce organizational efficiency', 'To limit patient access to services', 'B', 'Healthcare mergers and acquisitions (M&A) combine two or more health organisations with the primary objective of consolidating resources — staff, finances, equipment, infrastructure — and enhancing service delivery through economies of scale, reduced duplication, and improved care coordination (option B). While M&A can create short-term integration challenges (option A), these are transitional implementation difficulties, not the principal impact or purpose of M&A in health systems management. Reducing organisational efficiency (option C) and limiting patient access (option D) are contrary to the goals of M&A and represent failure, not intended impact. In single-best-answer examinations, the primary organisational benefit and purpose is the correct answer.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('How can health systems managers use evidence-based practice to improve care quality?', 'By ignoring clinical research', 'By incorporating the best available evidence into clinical decision-making and care protocols', 'By reducing the use of clinical guidelines', 'By limiting research integration', 'B', 'Evidence-based practice improves care quality by incorporating the best available evidence into clinical decision-making and care protocols, per NCK curriculum and EBP principles. Ignoring research, reducing guideline use, or limiting research integration are the opposite of EBP.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the role of health systems managers in implementing patient safety initiatives?', 'To ignore safety protocols', 'To develop and enforce safety protocols, conduct training, and monitor compliance', 'To reduce safety oversight', 'To limit staff involvement in safety efforts', 'B', 'Managers implement patient-safety initiatives by developing and enforcing safety protocols, conducting training, and monitoring compliance, per patient-safety and quality-assurance frameworks. Ignoring protocols, reducing oversight, or limiting staff involvement undermine safety.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('How can health systems managers address the challenge of healthcare workforce shortages?', 'By ignoring workforce planning', 'By implementing recruitment and retention strategies, and optimizing workforce utilization', 'By reducing staff training programs', 'By limiting career advancement opportunities', 'B', 'Workforce shortages are addressed by implementing recruitment and retention strategies and optimizing workforce utilization, per Kenya''s Human Resources for Health strategy. Ignoring planning, reducing training, or limiting advancement worsen shortages.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the significance of a balanced scorecard in health systems management?', 'To focus solely on financial performance', 'To provide a comprehensive view of organizational performance through financial and non-financial metrics', 'To limit performance measurement', 'To reduce focus on strategic objectives', 'B', 'The balanced scorecard provides a comprehensive view of organizational performance through both financial and non-financial metrics (financial, customer, internal process, learning/growth), per management theory. Focusing solely on finance, limiting measurement, or reducing strategic focus contradict its design.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('How can health systems managers use patient-centered care models to enhance service delivery?', 'By focusing on provider needs over patient needs', 'By designing care processes that prioritize patient preferences, values, and needs', 'By reducing patient engagement in care planning', 'By ignoring patient feedback', 'B', 'Patient-centered care models enhance service delivery by designing care processes that prioritize patient preferences, values, and needs, a core NCK/quality-of-care principle. Prioritizing provider needs, reducing engagement, or ignoring feedback are the antithesis of patient-centered care.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the role of health systems managers in fostering a culture of innovation?', 'To limit new ideas', 'To encourage creativity, support experimentation, and implement innovative solutions', 'To reduce research and development efforts', 'To ignore emerging trends', 'B', 'Fostering a culture of innovation means encouraging creativity, supporting experimentation, and implementing innovative solutions, per leadership/management theory. Limiting new ideas, reducing R&D, or ignoring emerging trends stifle innovation and are wrong.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('How can health systems managers address the needs of an aging population?', 'By ignoring geriatric care', 'By developing programs and services tailored to the specific needs of older adults', 'By reducing support for elderly care', 'By limiting research on aging', 'B', 'The needs of an aging population are addressed by developing programs and services tailored to the specific needs of older adults, per HSM and community-health geriatric-care principles. Ignoring geriatric care, reducing elderly support, or limiting research neglect this population.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('How can health systems managers use process improvement methodologies to enhance care quality?', 'By ignoring best practices', 'By applying methodologies such as Lean or Six Sigma to streamline processes and reduce inefficiencies', 'By reducing focus on process optimization', 'By limiting staff involvement in improvement efforts', 'B', 'Process-improvement methodologies such as Lean and Six Sigma streamline processes and reduce inefficiencies to enhance care quality, per quality-improvement/HSM practice. Ignoring best practices, reducing optimization focus, or limiting staff involvement defeat the methodologies.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the role of strategic planning in health systems management?', 'To focus solely on day-to-day operations', 'To set long-term goals, allocate resources, and guide decision-making to achieve organizational objectives', 'To ignore future trends', 'To reduce focus on organizational growth', 'B', 'Strategic planning sets long-term goals, allocates resources, and guides decision-making to achieve organizational objectives, per management theory. Focusing solely on day-to-day operations, ignoring future trends, or reducing growth focus contradict strategic (as opposed to operational) planning.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('How can health systems managers ensure effective care coordination across different providers?', 'By limiting communication between providers', 'By implementing integrated care models and communication systems to facilitate information sharing', 'By reducing care transitions', 'By ignoring interdisciplinary collaboration', 'B', 'Effective care coordination is ensured by implementing integrated care models and communication systems that facilitate information sharing across providers, per HSM/continuity-of-care principles. Limiting communication, reducing safe transitions, or ignoring interdisciplinary collaboration fragment care.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the impact of patient engagement on health systems management?', 'To reduce patient involvement in care decisions', 'To improve health outcomes and satisfaction by involving patients in their care planning and decision-making', 'To ignore patient preferences', 'To limit patient education efforts', 'B', 'Patient engagement improves health outcomes and satisfaction by involving patients in their care planning and decision-making, a patient-centered care principle. Reducing involvement, ignoring preferences, or limiting patient education are opposite effects and wrong.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('How can health systems managers leverage data analytics to improve decision-making?', 'By ignoring data-driven insights', 'By analyzing healthcare data to identify trends, predict outcomes, and inform strategic decisions', 'By reducing data collection efforts', 'By limiting the use of technology', 'B', 'Data analytics improves decision-making by analyzing healthcare data to identify trends, predict outcomes, and inform strategic decisions, per HSM/health-information-systems practice. Ignoring insights, reducing data collection, or limiting technology use undermine data-driven management.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What role does community health integration play in health systems management?', 'To limit community involvement in healthcare', 'To enhance collaboration between healthcare providers and community resources, addressing broader health needs', 'To reduce outreach efforts', 'To ignore local health issues', 'B', 'Community health integration enhances collaboration between providers and community resources to address broader determinants of health, per Kenya Community Health Strategy/WHO health systems building blocks. Options A, C and D describe neglecting or limiting community involvement, which contradicts the integration goal.', 'BScN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('How can health systems managers address healthcare fraud and abuse?', 'By ignoring suspicious activities', 'By implementing robust monitoring, auditing, and compliance programs', 'By reducing oversight', 'By limiting staff training on fraud prevention', 'B', 'Healthcare fraud and abuse are countered by robust monitoring, auditing and compliance programs that ensure accountability, per HSM governance principles and Kenya public financial-management controls. Ignoring activity, reducing oversight or limiting training (A, C, D) would increase fraud risk.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
